Ceviri.ekle("ka","olay",{
"OLAYLAR_EK5:1567-10-01:0":{"b": ["თავდაცვითი კავშირი აჩეს სასულთნოსთან და დახმარება ინდოეთის ოკეანეში", "8e835f24"], "d": ["პორტუგალიის თავდასხმების გამო კანუნისგან დახმარების მთხოვნელმა აჩეს ელჩებმა, ფადიშაჰის სიგეტვარში გარდაცვალების შემდეგ, ერთგულება სელიმ II-ს გამოუცხადეს და მასთან თავდაცვითი ხელშეკრულება დაიდო. ფადიშაჰმა ბრძანა, ალექსანდრიიდან ქვემეხები, თოფები, საბრძოლო მასალა და ოსტატები გაეგზავნათ; ინდოეთის წყლებში გასაგზავნად ჩვიდმეტი საბრძოლო ხომალდი მოამზადეს. იემენის აჯანყების გაფართოებამ ესკადრის გასვლა შეაფერხა, მაგრამ აჩეში მისულმა ოსმალმა მეზარბაზნეებმა და ოსტატებმა რეგიონში მუდმივი კვალი დატოვეს.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["კვიპროსის დესანტი: ლიმასოლის აღება", "9074ccc9"], "d": ["კუნძულზე გადმოსულმა ოსმალურმა ჯარმა დიდი წინააღმდეგობის გარეშე აიღო ლიმასოლი და მომდევნო დღეს ლარნაკისკენ გაემართა. ადგილობრივი მოსახლეობის ვენეციური მმართველობით უკმაყოფილებისა და ოსმალური ძალებისთვის დახმარების წყალობით ლარნაკაშიც სერიოზული წინააღმდეგობა არ შეხვდათ; ტუზლას ნავსადგური ჯარისა და აღჭურვილობის გადმოსხმის ბაზად აქციეს. ვენეციას თავდაცვა ნიქოზიასა და ფამაგუსტაში ჰქონდა თავმოყრილი; პაფოსის მმართველმა სერდარს მორჩილება მხოლოდ ნიქოზიის დაცემის შემდეგ აცნობა.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["ნიქოზიის აღება", "413d866b"], "d": ["1570 წლის 25 ივლისს დაწყებული და ორმოცდახუთდღიანი ალყის შემდეგ კვიპროსის ვენეციური მმართველობის დედაქალაქი ნიქოზია ოსმალურ ჯარს დანებდა. კუნძულის ცენტრის დაცემამ ვენეციური წინააღმდეგობა ფამაგუსტის ციხეში მომწყვდია. დაპყრობამ დასავლეთში დიდი გამოძახილი გამოიწვია და დააჩქარა პროცესი, რომელიც პაპის ინიციატივით წმინდა ლიგის ფლოტის შექმნამდე მიდიოდა.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["კირენიის ჩაბარება — კვიპროსის ჩრდილოეთ სანაპირო", "39fdeea5"], "d": ["9 სექტემბერს ნიქოზიის ხმლით ამოწყვეტით დაცემამ კვიპროსის ჩრდილოეთში წინააღმდეგობა გატეხა. ხუთთითა (ბეშფარმაქის) მთების უკან მდებარე კირენიის ციხემ, დედაქალაქის ბედის გაგების შემდეგ, რვა დღის შემდეგ პირობით დანებდა და მის გარნიზონს კუნძულიდან გასვლის ნება დართეს და გაუშვეს. კუნძულზე ვენეციური დროშა მხოლოდ ფამაგუსტაში დარჩა; იგიც კიდევ თერთმეტი თვე გაძლებდა.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["ფლოტის ხელახალი აშენება ლეპანტოს შემდეგ", "db51fe44"], "d": ["ლეპანტოს მარცხის შემდეგ კაპუდან-ფაშად დანიშნული ქილიჩ ალი-ფაშას პირველი საქმე მძიმედ დაზარალებული ფლოტის ხელახლა შექმნა იყო; გემთსაშენები 1571-1572 წლების მთელი ზამთრის განმავლობაში შეუსვენებლად მუშაობდა. 1572 წლის ივნისში დაახლოებით 250 გალერისა და 300 მოხალისე რეისის გალერისგან შემდგარი ახალი ესკადრა ხმელთაშუა ზღვაში გავიდა. ამ სწრაფმა გამოჯანმრთელებამ აჩვენა, რომ ლეპანტომ ოსმალური საზღვაო ძალა საბოლოოდ ვერ გატეხა.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["სტამბოლის ზავი ვენეციასთან — კვიპროსის აღიარება", "4d08ef50"], "d": ["წმინდა ლიგის დაშლის შემდეგ მარტო დარჩენილმა ვენეციამ ოსმალეთთან ცალკე ზავი დადო, ოფიციალურად აღიარა, რომ კვიპროსი ოსმალეთს ეკუთვნის, და საომარი კონტრიბუციის გადახდაზე დათანხმდა. ზავმა ნათლად აჩვენა, რომ ლეპანტოს გამარჯვებამ ქრისტიანულ სამყაროს პოლიტიკური სარგებელი ვერ მოუტანა. ამის შემდეგ ვენეცია სამოცდაათი წლის განმავლობაში მოერიდება ოსმალეთთან პირდაპირ ომში ჩართვას.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["სელიმ II-ის გარდაცვალება", "c289f5ee"], "d": ["სელიმ II დაცემის შემდეგ დაახლოებით ორი თვე დივანზე ვეღარ გამოვიდა და გარდაიცვალა. მისი სიკვდილი თორმეტი დღე საიდუმლოდ ინახებოდა სასახლეში, სანამ მანისაში მყოფი უფროსი ვაჟი მურადი სტამბოლში ჩავიდოდა. სიკვდილის დღეზე წყაროები განსხვავდება: სელანიქი 15 დეკემბერს ასახელებს; გერლახი, მეჰმედ ბინ მეჰმედი და ჯენაბი კი 13 დეკემბერს.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["სელიმ II-ის გარდაცვალების გამოცხადება და მურად III-ის ტახტზე ასვლა", "84334d70"], "d": ["სელიმ II-ის გარდაცვალება და მანისიდან ჩამოყვანილი მურად III-ის ტახტზე ასვლა 1574 წლის 22 დეკემბერს ოფიციალურად გამოცხადდა. ახალი ფადიშაჰი ოცდაერთი წელი დარჩება ტახტზე; მისი მმართველობა დამახსოვრდება აღმოსავლეთში ირანთან ხანგრძლივი ომებით, დასავლეთში გრძელი ომის წინა პერიოდით და ქვეყნის შიგნით აკჩეს (ვერცხლის მონეტის) გაუფასურებით. სოქოლუ მეჰმედ-ფაშას 1579 წელს გარდაცვალებამდე სახელმწიფო მმართველობაში ძველი წესრიგი გრძელდებოდა.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["ალ-კასრ ალ-ქაბირის (ვადი ალ-მახაზინის) ბრძოლა — ოსმალთა მხარდაჭერის მქონე აბდ ალ-მალიქმა პორტუგალიური ჯარი გაანადგურა", "21280dac"], "d": ["ოსმალთა მხარდაჭერით მაროკოს ტახტზე ასულმა აბდ ალ-მალიქმა პორტუგალიის მეფე სებასტიანის დიდი ჯარი ვადი ალ-მახაზინთან გაანადგურა; რადგან ბრძოლაში ერთდროულად სამი მმართველი დაიღუპა, დასავლურ წყაროებში მას „სამი მეფის ბრძოლას“ უწოდებენ. პორტუგალიის სამხედრო ძალა დაინგრა და ქვეყანა მალე ესპანეთის ხელში გადავიდა. აბდ ალ-მალიქიც ბრძოლაში დაიღუპა; მისმა მემკვიდრე ძმამ აჰმად ალ-მანსურმა გამარჯვება დელეგაციის საშუალებით სტამბოლს შეატყობინა. ორ სახელმწიფოს შორის ურთიერთობა ხარკის ან ვასალობის კი არა, ელჩებისა და საჩუქრების გაცვლის დონეზე დარჩა და მალე საჩუქრების საკითხის გამო დაიძაბა.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["დარუბანდის მოსახლეობის ლალა მუსტაფა-ფაშასთვის ერთგულების გამოცხადება — რკინის კარი ოსმალთა მმართველობაში", "9c55aeff"], "d": ["შირვანის ლაშქრობისას დარუბანდის მოსახლეობიდან შვიდკაციანი დელეგაცია ერეშში მყოფ სერდარ ლალა მუსტაფა-ფაშასთან მივიდა და ერთგულება გამოუცხადა. კავკასიის კედელსა და კასპიის ზღვას შორის ვიწრო გადასასვლელის ჩამკეტმა დარუბანდმა (რკინის კარმა), როგორც ჩრდილოეთიდან მომავალი სახმელეთო გზების სავალდებულო გასასვლელმა, შირვანის შენარჩუნებაში საკვანძო როლი ითამაშა. ოსმალთა ბატონობა აქ 1607 წლამდე გაგრძელდა.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["შირვანის დაპყრობა: შამახიის აღება", "9afae4c1"], "d": ["ჩილდირის გამარჯვების შემდეგ კავკასიაში გასული ჯარი სეფიანთა კასპიისპირეთის უმდიდრეს ეიალეთ შირვანში შევიდა და ცენტრალური ქალაქი შამახია აიღო. ოზდემიროღლუ ოსმან-ფაშას აქ ბეგლარბეგად დანიშვნით აბრეშუმის გზის ჩრდილოეთი ფრთა ოსმალთა კონტროლქვეშ მოექცა. შირვანი თორმეტი წლის განმავლობაში გაგრძელებული აღმოსავლური ომის ყველაზე ხშირად ხელიდან ხელში გადამსვლელ და ყველაზე ძვირად დამჯდარ ფრონტად იქცეოდა.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["ბაქოს აღება — კასპიის სანაპიროზე გასვლა", "eb5adab8"], "d": ["შირვანის ოპერაციის უკანასკნელი რგოლის სახით კასპიის ზღვის დასავლეთ სანაპიროზე მდებარე ბაქოს ნავსადგური აიღეს. ქალაქის შემოგარენის ნავთობის ჭები იმ დროსაც კი ცნობილი შემოსავლის წყარო იყო, ნავსადგური კი კასპიით მომავალი ირანული აბრეშუმის გასასვლელი პუნქტი იყო. ამგვარად, ოსმალეთის სახელმწიფო თავის ისტორიაში პირველად და ერთადერთხელ გახდა კასპიის ზღვის სანაპიროს მფლობელი.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["ერევნის (რევანის) აღება და ციხის აშენება", "7f623b7b"], "d": ["ყარსში ერევანში წასვლისა და იქ ციხის აშენების ბრძანების მიღების შემდეგ ფერჰად-ფაშა ერევანისკენ გაემართა და ქალაქი ჰიჯრის 991 წლის რამადანის დასაწყისში (1583 წლის სექტემბრის შუა რიცხვებში) ოსმალთა კონტროლქვეშ აიყვანეს. არაქსის ხეობის ჩრდილოეთი კარის მაკონტროლებელ ერევანში ახალი და დიდი ციხე აშენდა; ქალაქი საბეგლარბეგოს ცენტრად აქციეს. ყარსსა და თავრიზს შორის საჯარო გზის შუაში მდგარი ერევანი აღმოსავლეთი ფრონტის ლოგისტიკური ხერხემალი იყო. ციხე ისე მტკიცედ ააშენეს, რომ მომდევნო ორი საუკუნის განმავლობაში ოსმალურ-ირანული ომების უცვლელ სამიზნედ იქცა.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["ყარაბაღისა და განჯის ანექსია", "29abaead"], "d": ["ათწლიანი აღმოსავლური ომის უკანასკნელი შენაძენის სახით ფერჰად-ფაშამ 1588 წელს განჯისკენ გაილაშქრა და 1 სექტემბერს ქალაქში შევიდა; მტკვარსა და არაქსს შორის მდებარე ყარაბაღის მხარე და მისი ცენტრი განჯა ოსმალურ მმართველობაში გადავიდა. ამგვარად, შირვანი, ერევანი და ყარაბაღი გაერთიანდა და კავკასიაში შეუწყვეტელი ოსმალური ხაზი შეიქმნა. 1590 წელს ხელმოწერილი ფერჰად-ფაშას ზავი ამ საზღვარს დააფიქსირებდა, მაგრამ შენაძენის შენარჩუნება მხოლოდ ოცი წელი შეძლეს.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["ბიჰაჩის აღება", "651a7275"], "d": ["ბოსნიის ბეგლარბეგმა თელი ჰასან-ფაშამ, 1591 წლის ნოემბერში ბიჰაჩის წინა ციხის, რიპაჩის, აღების შემდეგ, 1592 წელს თავად ქალაქი და ციხეც აიღო; ათდღიანი ალყის შემდეგ მეთაური ლამბერგი დანებდა. ამ დაპყრობამ ბოსნიის საზღვარი მდინარე უნის გასწვრივ წინ წასწია და ბოლო დიდი ოსმალური შენაძენი გახდა გრძელი ომის წინა პერიოდში, რომელიც ერთი წლის შემდეგ, კულპასთან თელი ჰასან-ფაშას შაჰიდად დაღუპვით, აფეთქდებოდა.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["ოსმალეთ-ავსტრიის „გრძელი ომის“ დაწყება", "bd22c392"], "d": ["ბოსნიის ბეგლარბეგ თელი ჰასან-ფაშას კულპასთან (სისაკთან) დამარცხებისა და შაჰიდად დაღუპვის შემდეგ ოსმალეთის სახელმწიფომ ავსტრიას ომი გამოუცხადა და დაიწყო გრძელი ომი, რომელიც ცამეტი წელი გაგრძელდებოდა. ამ ომმა, რომელშიც ცეცხლსასროლი იარაღით შეიარაღებული ქვეითი ჯარი გადამწყვეტი იყო, ოსმალური ჯარის წყობაში სეკბანებისა და მეთოფე ჯარისკაცების დაქირავება დააჩქარა და თიმარიანი სიპაჰების დაქვეითება გააღრმავა. ომი 1606 წელს ჟიტვატოროკის ზავით დასრულდებოდა.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["ქოჯა სინან-ფაშა ავსტრიის ლაშქრობაში გაემართა — გრძელი ომის პირველი ლაშქრობა", "d4a2f46d"], "d": ["ბოსნიის ბეგლარბეგ ჰასან-ფაშას სისაკთან დამარცხებისა და შაჰიდად დაღუპვის შემდეგ დიდმა ვეზირმა ქოჯა სინან-ფაშამ ბრწყინვალე სიტყვებითა და დაპირებებით ფადიშაჰი ომზე დაიყოლია და 12.000 იანიჩარითა და სხვა ნაწილებით გზას გაუდგა. ამგვარად გაიხსნა ცამეტწლიანი ოსმალეთ-ავსტრიის ომის პირველი ლაშქრობა.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["იანიქქალეს (დიორის) აღება", "14b75207"], "d": ["დიდმა ვეზირმა ქოჯა სინან-ფაშამ თვეზე მეტხანს გაგრძელებული ალყის შემდეგ ვენის გზის საკეტად მიჩნეული იანიქქალე ჩაიბარა. ციხის დაცემამ ევროპაში დიდი პანიკა გამოიწვია და გრძელ ომში ოსმალების ყველაზე ბრწყინვალე შენაძენი გახდა. თუმცა ციხის შენარჩუნება მხოლოდ ოთხი წელი შეძლეს.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["მურად III-ის გარდაცვალება", "1b62e886"], "d": ["ოცდაერთწლიანი მმართველობის შემდეგ მურად III გარდაიცვალა იმ დღეებში, როცა ვლახეთის ჯარმა იბრაილი გადაწვა და სილისტრამდე მიაღწია, და აია-სოფიას სასაფლაოზე დაკრძალეს. მანისიდან გამოძახებული მისი ვაჟი მეჰმედ III ათი დღის შემდეგ სტამბოლში ჩავიდა და ტახტზე ავიდა (1595 წლის 27 იანვარი).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["ესტერგომის დაკარგვა ავსტრიის სასარგებლოდ", "f420d333"], "d": ["კარლ ფონ მანსფელდის ხელმძღვანელობით წარმოებულ ალყაში საკმარისი დახმარების ვერმიმღებმა ესტერგომის მცველებმა ციხე ერცჰერცოგ მათიასს ჩააბარეს. ორმოცდათორმეტწლიანი ოსმალთა ბატონობის დასრულებით დუნაის ხაზის თავდაცვითი ჯაჭვი გატყდა და ბუდა პირდაპირი საფრთხის ქვეშ აღმოჩნდა. ციხის დაბრუნება მხოლოდ ათი წლის შემდეგ, 1605 წელს, გახდება შესაძლებელი.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["ეგერის ციხის აღება", "3e511629"], "d": ["სამკვირიანი ბრძოლის შემდეგ ძლიერი ეგერის ციხე, რომლის აღებაც ოსმალებმა მანამდე ვერაფრით შეძლეს, მცველების დანებებით დაეცა. ამ დაპყრობამ, რომელშიც ფადიშაჰი პირადად მონაწილეობდა, გარკვეულწილად აღადგინა დაკარგული ესტერგომით შერყეული სულისკვეთება, და დაარსდა ეგერის ეიალეთი. ორი კვირის შემდეგ მოპოვებულ ხაჩოვას გამარჯვებასთან ერთად 1596 წელი გრძელ ომში ოსმალების ყველაზე წარმატებული წელი გახდა.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["იანიქქალეს (დიორის) დაკარგვა", "b4ccc679"], "d": ["მიკლოშ პალფისა და ადოლფ ფონ შვარცენბერგის სარდლობით ნაწილებმა მოულოდნელი თავდასხმით ციხის კარი ააფეთქეს და იანიქქალე დაიბრუნეს. ციხის დაკარგვამ, რომელიც ოთხი წლის წინ ქოჯა სინან-ფაშამ დიდი ძალისხმევით აიღო, უნგრეთში ოსმალთა წინა ხაზი ჩამოშალა. მიუხედავად იმისა, რომ იმავე წელს ბუდის ალყაში მოქცეული მტრის ძალები უკუაგდეს, ომის ბალანსი თანდათან გამომფიტავ ომად გადაიქცა.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["ყარაიაზიჯი აბდულჰალიმის აჯანყება", "30493b0d"], "d": ["გრძელ ომში ჯარიდან გაქცეული სეკბანებისა და ლევენდების შემკრებმა ყარაიაზიჯი აბდულჰალიმმა ცენტრალურ ანატოლიაში ვრცელი მხარე დაიმორჩილა, ურფის ციხე აიღო (1599 წლის ნოემბერი) და „ჰალიმ შაჰის“ ტიტულით თავი ფადიშაჰად გამოაცხადა, საკუთარი ტუღრათი დამოწმებულ ფირმანებს აგზავნიდა. ჯელალების დიდი ტალღის პირველ ლიდერად მიჩნეული ყარაიაზიჯი 1602 წელს გარდაიცვალა, მისი მოძრაობა კი ძმამ, დელი ჰასანმა, გააგრძელა. აჯანყება „დიდი გაქცევის“ ეპოქის დასაწყისია, როცა ანატოლიელი გლეხობა მასობრივად ტოვებდა მიწას.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["თირიაქი ჰასან-ფაშას მიერ კანიჟის თავდაცვა", "d56a5e6a"], "d": ["ერთი წლის წინ აღებული კანიჟის დასაბრუნებლად ერცჰერცოგმა ფერდინანდმა და მისმა მოკავშირეებმა ციხეს ორ თვეზე მეტხანს შემოარტყეს ალყა; თირიაქი ჰასან-ფაშამ 9000-კაციანი ძალით წინააღმდეგობა გაუწია. მიუხედავად იმისა, რომ გარედან დახმარებას ვერ იღებდა, საერთო იერიშები უკუაგდო და გამოხტომებით მტერი მძიმე დანაკარგებით უკან დახევაზე აიძულა. თავდაცვა ოსმალურ ისტორიოგრაფიაში ეპოსად იქცა და „კანიჟის ალყა“ ცალკე ლიტერატურულ ჟანრად ჩამოყალიბდა.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["მეჰმედ III-ის გარდაცვალება და აჰმედ I-ის ტახტზე ასვლა", "da735fde"], "d": ["20 დეკემბერს მეჰმედ III-ის გარდაცვალების შემდეგ ტახტზე მისი თოთხმეტი წლის ვაჟი აჰმედ I ავიდა. ის, რომ იგი ბავშვობის ასაკში და სანჯაყში გასვლის გარეშე ტახტზე ასული პირველი ფადიშაჰი იყო, აჩვენებს, რომ შაჰზადეების პროვინციაში აღზრდის წესი ფაქტობრივად დასრულდა. აჰმედ I-ის მმართველობისას ძმათა მკვლელობაზე უარი ითქმებოდა და „ექბერიეთის“ (ტახტზე დინასტიის უხუცესი მამაკაცი წევრის ასვლის) პრინციპზე გადავიდოდნენ.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["ესტერგომის დაბრუნება", "7330f273"], "d": ["დიდმა ვეზირმა ლალა მეჰმედ-ფაშამ ათი წლის წინ დაკარგულ ესტერგომს ალყა შემოარტყა და ოსმალურ მმართველობას კვლავ შეუერთა. იმავე ლაშქრობაში პეშტი და ვაციც გამოიხსნეს და ოსმალებმა უნგრეთში თავიანთი ხაზი გაამაგრეს. ამ წარმატებამ შესაძლებელი გახადა მომდევნო წელს ჟიტვატოროკში მოლაპარაკების მაგიდასთან შედარებით ძლიერი პოზიციით დაჯდომა; ესტერგომი 1683 წლამდე ოსმალთა ხელში დარჩებოდა.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["ორუჩის ველის გამარჯვება და ჯანბოლათოღლუს აჯანყების ჩახშობა", "30f93532"], "d": ["ალეპოში დამოუკიდებელი საბეილიქოს შემქმნელი და ტოსკანასთან კავშირის მძებნელი ჯანბოლათოღლუ ალი-ფაშა დიდმა ვეზირმა ქუიუჯუ მურად-ფაშამ ორუჩის ველზე სასტიკად დაამარცხა. სირიაში ცენტრალური ხელისუფლების აღდგენით ჯელალების ტალღის ყველაზე საშიში ფრთა გატყდა. ქუიუჯუ მურად-ფაშას ორწლიანმა დაუნდობელმა წმენდამ ანატოლიაში, თუნდაც დროებით, წესრიგი დაამყარა.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["ალაჩაიირის გამარჯვება და ქალენდეროღლუს აჯანყების ჩახშობა", "55db0485"], "d": ["მანისისა და ბურსის მხარეებზე ხარკის დამკისრებელი ჯელალების ლიდერი ქალენდეროღლუ ქუიუჯუ მურად-ფაშამ ალაჩაიირში დაამარცხა და იგი იძულებული გახდა ირანში გაქცეულიყო. ამ გამარჯვებით ანატოლიაში ჯელალების დიდი ჯარებიდან უკანასკნელი დაიშალა. ქუიუჯუ მურად-ფაშას მკაცრმა წმენდამ — გადმოცემის თანახმად, მის მიერ დახოცილ მეამბოხეებს სპეციალურად ამოთხრილ ჭებში ყრიდნენ — მოკლევადიან პერსპექტივაში წესრიგი კი დაამყარა, მაგრამ ანატოლიის მოსახლეობისა და წარმოების დანაკარგი ვერ აანაზღაურა.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["ჰოლანდიისთვის პირველი აჰდნამეს გაცემა", "5d9d117e"], "d": ["ნიდერლანდების გაერთიანებული რესპუბლიკის ელჩმა კორნელის ჰაგამ მოახერხა აჰმედ I-ისგან იმავე მოცულობის აჰდნამეს მიღება, რაც საფრანგეთსა და ინგლისს ჰქონდათ მიცემული. ამგვარად, ჰოლანდიამ სტამბოლში საელჩოს, ოსმალურ ნავსადგურებში საკონსულოების გახსნისა და საკუთარი დროშით ვაჭრობის უფლება მოიპოვა. ეს აჰდნამე სიმბოლურად გამოხატავს ხმელთაშუა ზღვის ვაჭრობაში ვენეციის ადგილის დამკავებელი ჩრდილოელი საზღვაო ძალების ოსმალურ ბაზარზე შესვლას.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["აჰმედ I-ის გარდაცვალება და მუსტაფა I-ის ტახტზე ასვლა — ექბერიეთის წესი", "9901c09e"], "d": ["ორმოცდათერთმეტდღიანი კუჭის ავადმყოფობის შემდეგ ოცდარვა წლის აჰმედ I გარდაიცვალა და ტახტზე მისი ვაჟის ნაცვლად ძმა მუსტაფა I აიყვანეს. ამგვარად, მამიდან შვილზე გადამავალი მემკვიდრეობის წესი მიატოვეს და ფაქტობრივად „ექბერიეთის“ სისტემაზე გადავიდნენ, რომლის მიხედვით ტახტზე დინასტიის უხუცესი მამაკაცი წევრი ადიოდა. ოთხმოცდათექვსმეტდღიანი ეს პირველი მმართველობა ასევე შაჰზადეების „გალიაში“ (ქაფესში) აღზრდის ეპოქის დასაწყისია.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["მუსტაფა I-ის გადაყენება და ახალგაზრდა ოსმანის (ოსმან II-ის) ტახტზე ასვლა", "e0f552f2"], "d": ["ფსიქიკური ჯანმრთელობის დარღვევის საბაბით მუსტაფა I ოთხმოცდათექვსმეტი დღის ბოლოს ტახტიდან ჩამოაგდეს და ფადიშაჰი აჰმედ I-ის თოთხმეტი წლის ვაჟი ოსმან II გახდა. ჰასანბეიზადეზე დაფუძნებული გადმოცემის მიხედვით, ამ გადაყენების გადაწყვეტილებაში გავლენიანი იყო ყიზლარ აღა მუსტაფა აღა. ახალგაზრდა ოსმანი, იანიჩართა კორპუსის გაუქმებისა და ახალი ჯარის შექმნის გეგმით, ოსმალური რეფორმის დისკუსიების პირველ რადიკალურ ფიგურად მიიჩნევა. ეს გეგმა ოთხი წლის შემდეგ მას სიცოცხლის ფასად დაუჯდებოდა.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["სარაბის ზავი — ირანთან მშვიდობის განახლება", "e778aca8"], "d": ["ფული შიქესთეს მარცხის შემდეგ ირანთან მიღწეულმა სარაბის ზავმა 1612 წლის ნასუჰ-ფაშას ზავის პირობები დიდწილად დაადასტურა; სეფიანების მიერ გასაგზავნი ყოველწლიური აბრეშუმის რაოდენობა ორასი საპალნიდან ას საპალნემდე შემცირდა. ამგვარად, 1603 წლიდან მიმდინარე აღმოსავლური ომების მეორე ეტაპი დასრულდა. მშვიდობა დიდხანს არ გაგრძელდება: 1623 წელს ბაღდადის ხელიდან გასვლით ომი კვლავ აგიზგიზდება.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["ხოტინის ლაშქრობა და ხოტინის ზავი", "bc4c823c"], "d": ["ოსმან II-ის პირადი მეთაურობით წარმოებული დიდი ჯარის წინააღმდეგ ხოდკევიჩის მიერ ხოტინთან მოწყობილი გამაგრებული ბანაკი ვერ გაარღვიეს და თვეების განმავლობაში განხორციელებულმა იერიშებმა შედეგი არ გამოიღო. 9 ოქტომბერს ხელმოწერილი ზავით საზღვრად მდინარე დნესტრი აღიარეს, პოლონელებმა კი კაზაკების თავდასხმების აღკვეთა იკისრეს. გამარჯვებად წარმოდგენილმა, მაგრამ უშედეგო ლაშქრობამ ახალგაზრდა ფადიშაჰის იანიჩრებისადმი უნდობლობა და კორპუსის ლიკვიდაციის განზრახვა გააძლიერა.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["ჰორმუზის პორტუგალიელებისთვის ჩამორთმევა", "93e5f6cf"], "d": ["სეფიანთა ძალებმა 1515 წლიდან პორტუგალიის ხელში მყოფ ჰორმუზს ალყა შემოარტყეს და უკან დაიბრუნეს; ქეშმი და სანაპიროზე მდებარე გამრუნიც (ბანდარ-აბასი) სეფიანთა მმართველობაში გადავიდა, ხოლო ყურის ვაჭრობამ ახალ ნავსადგურში გადაინაცვლა.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["მუსტაფა I-ის მეორედ გადაყენება და მურად IV-ის ტახტზე ასვლა", "1b3a9e74"], "d": ["ოსმან II-ის მკვლელობის შემდეგ მეორედ ტახტზე აყვანილი მუსტაფა I ერთი წლისა და სამი თვის შემდეგ კვლავ ჩამოაგდეს და თერთმეტი წლის მურად IV ფადიშაჰად გამოაცხადეს. პირველი ცხრა წელი სახელმწიფოს ფაქტობრივად მისი დედა ქოსემ სულთანი და სასახლის დიდებულები მართავდნენ. მურად IV 1632 წლიდან მმართველობას პირადად აიღებდა ხელში და მკაცრი ცენტრალიზაციის პერიოდს დაიწყებდა.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["ბაღდადის დაკარგვა სეფიანების სასარგებლოდ", "db81be0c"], "d": ["ბაღდადში აჯანყებული ბექირ სუბაშის სეფიანებთან წარმოებული მოლაპარაკებების ბოლოს, შიდა ციხის დამცველმა მისმა ვაჟმა დერვიშ მეჰმედმა ქალაქი შაჰ აბასის ძალებს ჩააბარა. ხალიფატის მემკვიდრეობის ერთ-ერთი სიმბოლური ქალაქისა და ერაყის დიდი ნაწილის ხელიდან გასვლამ სტამბოლში დიდი აღშფოთება გამოიწვია. ბაღდადის დაბრუნება თხუთმეტი წლის განმავლობაში ოსმალეთის აღმოსავლური პოლიტიკის ერთადერთი მიზანი იქნებოდა.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["აბაზა მეჰმედ-ფაშას ერზურუმის ცენტრის მქონე აჯანყების ჩახშობა", "e6da2729"], "d": ["ოსმან II-ის მკვლელობის შურისძიების პრეტენზიით იანიჩრების წინააღმდეგ აჯანყებულმა ერზურუმის ბეგლარბეგმა აბაზა მეჰმედ-ფაშამ წლების განმავლობაში აღმოსავლეთ ანატოლია თავის კონტროლქვეშ ჰქონდა და ცენტრს წინააღმდეგობას უწევდა. დიდი ვეზირ ჰუსრევ-ფაშას მიერ ერზურუმის ალყის შემდეგ იძულებული გახდა დანებებულიყო; შეიწყალეს და ბოსნიაში დანიშნეს. აჯანყების დასრულება წინაპირობა იყო იმისთვის, რომ მურად IV-ს ირანის წინააღმდეგ ლაშქრობაში გასვლა შესძლებოდა.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["შეიხულისლამის პირველი სიკვდილით დასჯა: აჰიზადე ჰუსეინ ეფენდი", "a60a58c5"], "d": ["სამხედრო არეულობაში შუამავლობის გაწევისა და ფადიშაჰისთვის სასამართლო წესის შესახებ წერილობითი გაფრთხილების გაგზავნის საბაბით შეიხულისლამი აჰიზადე ჰუსეინ ეფენდი ბიუქჩექმეჯეს მახლობლად სიკვდილით დასაჯეს. ის, რომ იგი სიკვდილით დასჯილი პირველი ოსმალი შეიხულისლამი იყო, არღვევდა ფესვგადგმულ ტრადიციას, რომლის მიხედვით ულემთა წარმომადგენლებისთვის უმძიმესი სასჯელი გადასახლება იყო. მოვლენა მურად IV-ის გამკაცრებული ავტორიტეტისა და სახელმწიფო-ულემთა ბალანსის რღვევის სიმბოლოდ მიიჩნევა.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["მურად IV-ის მიერ ერევნის აღება", "b65a9b73"], "d": ["1635 წლის 28 მარტს სტამბოლიდან გასულმა მურად IV-მ 28-29 ივლისს ერევანს ალყა შემოარტყა და 8 აგვისტოს ციხე ჩაიბარა; შემდეგ დაცარიელებულ თავრიზში შევიდა და ქალაქი ააოხრებინა. ფადიშაჰმა გამარჯვების სახსოვრად თოფქაფის სასახლეში ერევნის კოშკი (რევან ქიოშქი) ააგებინა. ეს ლაშქრობა ოცდაათწლიანი შესვენების შემდეგ პირველი დიდი აღმოსავლური ოპერაცია იყო, რომელშიც ფადიშაჰი პირადად მეთაურობდა ჯარს.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["ერევნის დაკარგვა სეფიანების სასარგებლოდ", "fbb8dd25"], "d": ["ოსმალური ჯარის უკან გაბრუნების შემდეგ შაჰ სეფის ძალებმა ერევანს ალყა შემოარტყეს და რვა თვის განმავლობაში დაიბრუნეს. ციხის ასე სწრაფად ხელიდან გასვლამ აჩვენა, რამდენად რთული იყო ლოგისტიკურად მუდმივი ბატონობა კავკასიაში. ერევანი 1639 წლის ყასრ-ი შირინის ზავითაც ირანს დარჩებოდა და ოსმალეთი აზერბაიჯანზე პრეტენზიაზე ხელს აიღებდა.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["ბაღდადის ხელახალი აღება", "4d2f27f3"], "d": ["1638 წლის 8 მაისს სტამბოლიდან გასულმა მურად IV-მ ორმოცდღიანი სასტიკი ალყის შემდეგ თხუთმეტი წელი სეფიანების ხელში მყოფი ბაღდადი დაიბრუნა; ალყისას ვეზირი თაიარ მეჰმედ-ფაშა შაჰიდად დაიღუპა. ქალაქის აღებით ერაყში ოსმალური მმართველობა აღდგა და ფადიშაჰმა „ბაღდადის დამპყრობლის“ ტიტული მიიღო. დაპყრობა მომდევნო წლის ყასრ-ი შირინის ზავით განმტკიცდა და დღევანდელი თურქეთ-ირანის საზღვრის საფუძველი ჩაიყარა.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["მურად IV-ის გარდაცვალება და სულთან იბრაჰიმის ტახტზე ასვლა", "e2ca1ca0"], "d": ["ოცდაშვიდი წლის (ჰიჯრის წელთაღრიცხვით ოცდარვა) ასაკში გარდაცვლილი მურად IV-ის შემდეგ ტახტზე დინასტიის ერთადერთი ცოცხლად დარჩენილი მამაკაცი წევრი, ძმა იბრაჰიმი ავიდა. წლების განმავლობაში გალიაში (ქაფესში) მცხოვრები ახალი ფადიშაჰის მმართველობისას სასახლის ხარჯებმა და სასახლის შიდა გავლენისთვის ბრძოლებმა სახელმწიფო წესრიგი შეარყია. რვა წლის შემდეგ მისი გადაყენებითა და მკვლელობით ოსმალეთის ისტორიაში ფადიშაჰის მეორე მკვლელობა მოხდებოდა.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["აზოვის ციხის დაბრუნება კაზაკებისგან", "e5fcf160"], "d": ["1637 წელს დონელი კაზაკების მიერ აღებული აზოვის ციხე სულთანზადე მეჰმედ-ფაშასა და ყირიმის ხან მეჰმედ IV გირაის ერთობლივი ოპერაციის წინაშე დაიცალა; კაზაკებმა ციხეს ცეცხლი წაუკიდეს და უკან დაიხიეს. შავი ზღვის ჩრდილოეთი კარის დაბრუნებამ დახურა საშიში პერიოდი, როცა კაზაკების თავდასხმები სტამბოლის სრუტემდე აღწევდა. ციხე 1696 წელს ამჯერად რუსეთის მეფე პეტრე I-ს ჩაუვარდებოდა ხელში.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["კრეტის ლაშქრობის დაწყება და ჰანიის აღება", "a1b0c77f"], "d": ["საბაბად იმის გამოყენებით, რომ მალტელმა კორსარებმა ოსმალური ჰაჯის ხომალდი დააზიანეს და კრეტაზე შეაფარეს თავი, ვენეციას ომი გამოუცხადეს და იუსუფ-ფაშას სარდლობით ფლოტმა კუნძულზე ჯარი გადასხა. ორმოცდათოთხმეტდღიანი ალყის შემდეგ ჰანიის ციხე აიღეს და კრეტაზე პირველი მუდმივი ოსმალური ბაზა შეიქმნა. ამგვარად დაიწყო ოსმალეთის ისტორიის ყველაზე ხანგრძლივი ომი; კუნძულის სრულად დაპყრობა მხოლოდ ოცდაოთხი წლის შემდეგ, 1669 წელს, გახდა შესაძლებელი.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["რეთიმნოს აღება — კრეტის ორად გაყოფა", "8f2c4353"], "d": ["ჰანიის აღებიდან ერთი წლის შემდეგ კუნძულის ცენტრალური ნაწილის რეთიმნოს ციხეც დაეცა და კრეტის დასავლეთი ნახევარი მთლიანად ოსმალურ მმართველობაში შევიდა. ვენეციის ხელში მხოლოდ დედაქალაქი კანდია და აღმოსავლეთი კიდე დარჩა; კუნძული ოცდასამი წელი ორად გაყოფილი ცხოვრობდა. რეთიმნოს აღება კანდიის ალყის დამწყები ნაბიჯი გახდა — ისტორიის ყველაზე ხანგრძლივი ალყა აქ დაიწყო.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["კლისის დაკარგვა ვენეციის სასარგებლოდ", "5473c22c"], "d": ["კრეტის (კანდიის) ომის დალმაციის ფრონტზე ვენეციელი მეთაურის ლეონარდო ფოსკოლოს კონტრშეტევამ 1537 წლიდან სანჯაყის ცენტრად მყოფი კლისიც მოიცვა; ციხე ვენეციას გადაეცა. ოსმალების მთელი ძალისხმევის კრეტაზე კონცენტრაციამ დალმაციის საზღვარზე ამ დანაკარგის ანაზღაურება შეუძლებელი გახადა — კლისი ოსმალურ მმართველობას აღარასოდეს დაუბრუნდებოდა; სანჯაყის ცენტრი ლივნოში გადაიტანეს.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["კანდიის ალყის დაწყება", "13016b10"], "d": ["ჰანიისა და რეთიმნოს აღების შემდეგ ოსმალურმა ჯარმა კუნძულზე ვენეციის უკანასკნელ დიდ საყრდენს, კანდიას, ალყა შემოარტყა. ეს ბლოკადა, რომელიც ოცდაერთი წელი გაგრძელდებოდა, მსოფლიო სამხედრო ისტორიაში ერთ-ერთ ყველაზე ხანგრძლივ ალყად ჩაიწერა. ალყის განმავლობაში ვენეციური ფლოტის მცდელობები დარდანელის სრუტის ჩასაკეტად ომს ეგეოსის ზღვის შუაგულში გადაიტანდა.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["უფროსი ვალიდე ქოსემ სულთნის მკვლელობა", "9d763f79"], "d": ["დაახლოებით სამოცდაორი წლის ქოსემ სულთანი ჰარემის ერთ ოთახში იპოვეს და მოკლეს მეჰმედ IV-ის დედის, თურჰან სულთნის, ბრძანებით მოქმედმა ბაშლალა უზუნ სულეიმან აღამ და მისმა ხალხმა. სამი ფადიშაჰის ეპოქაში სახელმწიფო პოლიტიკის წარმმართველი ამ ძლიერი დინასტიური ქალის სიკვდილი ე.წ. „ქალთა სულთანობის“ პერიოდის ფაქტობრივ დასასრულად მიიჩნევა. გამოთავისუფლებულმა ძალაუფლებამ გზა გაუხსნა იმას, რომ ხუთი წლის შემდეგ ქოფრულუ მეჰმედ-ფაშა საგანგებო უფლებამოსილებებით დიდი ვეზირი გამხდარიყო.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["დარდანელის მარცხი და ბოზჯაადისა და ლემნოსის დაკარგვა", "e01a1f7e"], "d": ["ვენეციელი ადმირალის მოჩენიგოს მიერ 1656 წლის ივნისში დარდანელის სრუტის წინ მოპოვებულმა დიდმა საზღვაო გამარჯვებამ ოსმალური ფლოტი თითქმის მთლიანად გაანადგურა; შემდეგ ბოზჯაადა, ლემნოსი და სამოთრაკე ოკუპირებული იქნა. სრუტის ვენეციურ ბლოკადაში მოქცევით სტამბოლში სურსათის ფასები გაიზარდა და დედაქალაქზე თავდასხმის შიში გავრცელდა. ეს კატასტროფა უშუალო მიზეზი გახდა იმისა, რომ 1656 წლის სექტემბერში ქოფრულუ მეჰმედ-ფაშა პირობითად და საგანგებო უფლებამოსილებებით დიდ ვეზირად დანიშნეს.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["დარდანელის გამარჯვება და ბოზჯაადის დაბრუნება", "603da863"], "d": ["ქოფრულუ მეჰმედ-ფაშას მიერ მობილიზებულმა ფლოტმა 1657 წლის 19 ივლისს სრუტის წინ ვენეციური ესკადრა დაამარცხა; შემდეგ ქურდ-ფაშას სარდლობით ძალებმა 25 აგვისტოს ბოზჯაადა დაიბრუნეს, ხოლო 30 აგვისტოს ვენეციელებმა კუნძული მთლიანად დაცალეს. ნოემბერში ლემნოსიც გამოიხსნეს, დარდანელის ბლოკადა გაარღვიეს და სტამბოლის სურსათის მომარაგების გზა კვლავ გაიხსნა. ქოფრულუმ პირადად გადავიდა კუნძულზე და სიმაგრეები შეაკეთებინა; ეს წარმატება ქოფრულუების ეპოქის პირველი დიდი სამხედრო შენაძენია.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["ინეუს (იანოვას) აღება და ტრანსილვანიის ლაშქრობა", "d1089616"], "d": ["უნებართვოდ პოლონეთში ლაშქრობით ოსმალური მფარველობის გამთელავი ტრანსილვანიის მთავრის დიორდ II რაკოცის დასასჯელად ლაშქრობაში გასულმა ქოფრულუ მეჰმედ-ფაშამ ბელგრადის გავლით გაილაშქრა და სტრატეგიული ინეუს ციხე აიღო. ტრანსილვანიაში ახალი მთავარი დანიშნეს და ვასალური კავშირი მკაცრად შეახსენეს. ეს ლაშქრობა ცენტრალურ ევროპაში ოსმალური ავტორიტეტის აღდგენის მცდელობის პირველი რგოლი იყო. ტრანსილვანია ისედაც ოსმალეთზე დაქვემდებარებული სამთავრო იყო; ინეუს აღება უცხო სახელმწიფოსგან დაპყრობა კი არ იყო, არამედ ვასალური ტრანსილვანიის ამ ციხის სამთავროს მმართველობიდან გამოყოფა და პირდაპირ ოსმალურ სანჯაყზე მიბმა; სამთავროს დანარჩენი ნაწილი ვასალურ სტატუსში დარჩა.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["აბაზა ჰასან-ფაშას აჯანყების ჩახშობა", "4ba74321"], "d": ["ქოფრულუ მეჰმედ-ფაშას მკაცრი წმენდების წინააღმდეგ ანატოლიის ბეგლარბეგებისა და სეკბანთა აღების მხარდაჭერით აბაზა ჰასან-ფაშამ დიდი ვეზირის გადაყენება მოითხოვა და დიდი აჯანყება წამოიწყო. აჯანყება ალეპოში ჩაახშეს და მეთაურები მოაშორეს; ეს პროვინციული ფაშების ცენტრის წინააღმდეგ ბოლო ერთობლივი წინააღმდეგობა იყო. ამგვარად, ქოფრულუს ავტორიტეტი უდავო გახდა და დიდი ვეზირის თანამდებობა კვლავ სახელმწიფოს ნამდვილი აღმასრულებელი ცენტრის დონემდე ამაღლდა.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["ორადეას (ვარადის) აღება", "0e6ad300"], "d": ["ოსმალეთისთვის ომის გამომცხადებელი ტრანსილვანიის მთავრის დიორდ II რაკოცის წინააღმდეგ მოწყობილი ლაშქრობის ფარგლებში ვარადის ციხე და ქალაქი აიღეს. ტრანსილვანიის ერთ-ერთი საკვანძო ციხის დაცემით რეგიონში ახალი ოსმალური ეიალეთი (ვარადის ეიალეთი) დაარსდა. დაპყრობამ ჰაბსბურგები განგაშში ჩააგდო და სამი წლის შემდეგ დაწყებული ოსმალეთ-ავსტრიის ომის ერთ-ერთი უშუალო მიზეზი გახდა. იმავე თარიღს შემოერთებული სხვა ადგილები: ვარადი. აქაც მიწა უცხო სახელმწიფოს არ წაართვეს: ტრანსილვანია ისედაც დაქვემდებარებული ოსმალური სამთავრო იყო; ვარადის ეიალეთად ქცევამ მხოლოდ ამ ქალაქის მმართველობა ვასალურ სამთავროს ჩამოართვა და პირდაპირ ფადიშაჰს დაუქვემდებარა, ისევე როგორც ორი წლის წინ ინეუში.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["სენტგოტარდის (სენ-გოთარდის) ბრძოლა", "61ebc1f2"], "d": ["მდინარე რააბის გადამლახველი ოსმალური ძალები მონტეკუკოლის სარდლობით მოკავშირე ევროპულმა ჯარმა შეაჩერა და მძიმე დანაკარგები მიაყენა. ბრძოლა სამხედრო ისტორიაში გარდამტეხ მომენტად მიიჩნევა, რადგან პირველად ნათლად აჩვენა დისციპლინირებული ცეცხლსასროლი ქვეითის თოფის სროლის უპირატესობა ოსმალური ცხენოსანი იერიშის წინაშე. მარცხის მიუხედავად, ოსმალებმა ცხრა დღის შემდეგ ხელმოწერილ ვაშვარის ზავში ხელსაყრელი პირობების მიღება მოახერხეს.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["ვაშვარის ზავი", "089c978c"], "d": ["სენტგოტარდის მარცხის მიუხედავად დადებულმა ზავმა გაითვალისწინა, რომ უივარი და ვარადი ოსმალეთს რჩებოდა, ტრანსილვანია ოსმალური მფარველობის ქვეშ ნეიტრალური დარჩებოდა, ავსტრია კი 200.000 ყურუშ „საჩუქარს“ გადაიხდიდა. ეს ოცწლიანი ზავი იშვიათი მაგალითია იმისა, როცა ომში წაგებულმა მხარემ მოლაპარაკების მაგიდასთან გაიმარჯვა. ზავით ჰაბსბურგულ საზოგადოებაში გაჩენილი უკმაყოფილება შუა უნგრეთის მოძრაობას და, არაპირდაპირ, 1683 წლის ვენის ლაშქრობას გამოკვებავდა.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["ალჟირში დეის მმართველობის დაწყება", "e99faa51"], "d": ["ალჟირის ოჯაღმა და რეისთა ტაიფამ (მეკობრე კაპიტნებმა) უკანასკნელი აღა გადააყენეს და ჰაჯი მეჰმედი სიცოცხლის ბოლომდე დეიდ აირჩიეს. ამ თარიღის შემდეგ ალჟირს მართავდა არა სტამბოლის დანიშნული ბეგლარბეგი, არამედ ადგილობრივი ოჯაღის საკუთარი წრიდან არჩეული დეი; ოსმალური კავშირი შეიზღუდა ხუთბაში ფადიშაჰის სახელის წაკითხვით, დროშითა და ლაშქრობაში მონაწილეობის ვალდებულებით. ამგვარად ალჟირი ეიალეთიდან ოჯაღლიკად გადაიქცა — იგივე ცვლილება ტუნისმა 1705 წელს ჰუსეინიდებთან, ტრიპოლიტანიამ კი 1711 წელს ყარამანლებთან განიცადა.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["პოლონეთის ლაშქრობა დაიწყო — მეჰმედ IV და ფაზილ აჰმედ-ფაშა ჯარის სათავეში", "75e15a39"], "d": ["ოსმალთა მფარველობაში შესული უკრაინის ჰეტმანის პეტრო დოროშენკოს წინააღმდეგ პოლონეთის შეტევები რომ არ შეწყდა, სტამბოლმა პოლონეთის მეფეს თავდასხმებზე ხელის აღება მოსთხოვა; დადებითი პასუხის მიუღებლობის შემდეგ პოლონეთის წინააღმდეგ ლაშქრობის გადაწყვეტილება მიიღეს. დიდი ვეზირი ფაზილ აჰმედ-ფაშა ჯართან ერთად, რომელშიც ფადიშაჰიც იყო, 1672 წლის 4 ივნისს პოლონეთისკენ დაიძრა. ლაშქრობა კამენეცის აღებითა და ბუჩაჩის ზავით დასრულდებოდა.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["კამენეცის აღება და პოდოლიის ეიალეთის დაარსება", "c3f4f6d0"], "d": ["ცხრადღიანი ალყის შემდეგ აღმოსავლეთში პოლონეთის უძლიერეს ციხედ მიჩნეული კამენეცი ჩაბარდა; მეჰმედ IV-მ 2 სექტემბერს საკათედრო ტაძრიდან გადაკეთებულ მეჩეთში პირველი პარასკევის ლოცვა აღასრულა. ციხე ცენტრად აქციეს, პოდოლიის ეიალეთი დაარსდა და ოსმალურმა დროშამ დღევანდელი უკრაინის ტერიტორიაზე ყველაზე ჩრდილო წერტილს მიაღწია. კამენეცი 1699 წლის კარლოვიცის ზავამდე იმპერიის ჩრდილო-დასავლეთ კიდედ დარჩებოდა.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["ყარა მუსტაფა-ფაშამ უმანი პოლონეთისგან ჩაიბარა", "0d3543a0"], "d": ["პოლონეთის წინააღმდეგ გაგზავნილმა ყარა მუსტაფა-ფაშამ პოლონეთის ხელში მყოფი ციხეებიდან უმანი ჩაიბარა; ქალაქი კარლოვიცამდე ოსმალური მმართველობის ქვეშ დარჩა.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["ჩიგირინის ციხის აღება", "a17cedd0"], "d": ["წინა წელს მელექ იბრაჰიმ-ფაშას უშედეგო ოპერაციის შემდეგ დიდმა ვეზირმა მერზიფონელმა ყარა მუსტაფა-ფაშამ პირადად ისარდლა, გამაგრებულ ჩიგირინის ციხეს ალყა შემოარტყა (19/21 ივლისი) და 21 აგვისტოს აიღო. უკრაინის კაზაკთა საჰეტმანოზე ოსმალეთ-რუსეთის მეტოქეობის სიმბოლო ამ ციხის დაცემამ რუსეთი ზავისკენ აიძულა. ეს წარმატება მერზიფონელის იმ თავდაჯერების ერთ-ერთი წყარო გახდა, რომელიც ვენისკენ მიმართავდა მას.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["ბახჩისარაის ზავი — პირველი ოფიციალური ზავი რუსეთთან", "df82bc0b"], "d": ["ჩიგირინის ლაშქრობების შემდეგ ყირიმის ხანის შუამავლობით წარმოებული მოლაპარაკებების ბოლოს, საზღვრად მდინარე დნეპრი (ოზუ) აღიარეს და ოსმალეთის სახელმწიფოსა და რუსეთს შორის ოცწლიანი ზავი დაიდო. რადგან ეს ორ სახელმწიფოს შორის პირველი ყოვლისმომცველი ხელშეკრულება იყო, ის ოსმალურ-რუსული ურთიერთობების საწყის დოკუმენტად მიიჩნევა. ზავის წყალობით აღმოსავლეთის ფრონტი დაიცვეს და ჯარის ცენტრალური ევროპისკენ მიმართვა შესაძლებელი გახდა.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["ტეკელი იმრესთვის შუა უნგრეთის მეფობის ბერათის გადაცემა", "3cd8d51d"], "d": ["ჰაბსბურგული ზეწოლის წინააღმდეგ აჯანყებული პროტესტანტი უნგრელი დიდგვაროვანი ტეკელი იმრე 1682 წლის აპრილიდან „შუა უნგრეთის არჩეულ მეფედ“ ითვლებოდა, ხოლო 16 სექტემბერს ბუდის ბეგლარბეგმა იბრაჰიმ-ფაშამ მას სამთავრო ნიშნები გადასცა. ამგვარად, ოსმალთა მფარველობაში ახალი ვასალური უნგრული სახელმწიფო შეიქმნა. ამ ჩარევამ ავსტრიასთან ომი გარდაუვალი გახადა და დაიწყო ჯაჭვი, რომელიც მომდევნო წელს ვენის მეორე ალყამდე მიდიოდა.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["ლეფკადის (აია-მავრას) დაკარგვა ვენეციის სასარგებლოდ", "e6905fee"], "d": ["წმინდა ლიგაში გაწევრიანებული ვენეციის ფლოტმა, ქალაქის ზარბაზნებით დაბომბვის შემდეგ, იონიის ზღვაში მდებარე ლეფკადის კუნძული დაიპყრო. იმავე წელს პრევეზის დაცემით ადრიატიკის შესასვლელში ოსმალური კონტროლი გატყდა. ეს დანაკარგები იმ ოპერაციის საწყისი ნაბიჯები იყო, რომლითაც მოროზინი სამ წელიწადში მთელ მორეას დაიპყრობდა.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["კორონის დაკარგვა ვენეციის სასარგებლოდ", "2ed762bc"], "d": ["მოროზინის სარდლობით ვენეციურმა ძალებმა მორეის ნახევარკუნძულის სამხრეთ-დასავლეთ კიდეზე კორონის ციხე აიღეს; ქალაქი ამის შემდეგ ოცდაათი წელი ვენეციური მმართველობის ქვეშ დარჩებოდა. კორონის დაცემა მორეის დასაპყრობად მიმართული ვენეციური ოპერაციის პირველი დიდი შენაძენი იყო. ციხის დაბრუნება მხოლოდ 1715 წელს სილაჰდარ ალი-ფაშას სარდლობით ოსმალურმა ჯარმა შეძლო.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["ათენის დაბრუნება — ვენეციის უკანდახევა", "03393b46"], "d": ["1687 წლის სექტემბერში აკროპოლისის დამბომბავმა და პართენონის ამფეთქებელმა მოროზინიმ, ზამთრის ათენში გატარების შემდეგ, მიხვდა, რომ ქალაქში ვერ გაძლებდა. შავი ჭირის ეპიდემიის, მომარაგების სირთულისა და ოსმალური ძალების შეკრების გამო ვენეციურმა გარნიზონმა ქალაქი დაცალა და მორეაში დაიხია. ამგვარად, ათენი უბრძოლველად კვლავ ოსმალურ მმართველობას დაუბრუნდა, მაგრამ პართენონის ნგრევა ვეღარ აღდგა.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["ლიპოვა (ლიპა) კარაფას დანებდა — ავსტრიის ხელში გადავიდა", "7f0a8d38"], "d": ["ანტონიო კარაფას სამდღიანი ალყის შემდეგ ლიპოვა 1688 წლის 12-22 ივნისს შორის დანებდა და ავსტრიის ხელში გადავიდა. შემდგომში ოსმალებმა ქალაქი უკან დაიბრუნეს, ავსტრიამ 1691 წელს ხელახლა დაიკავა; 1695 წლის ლაშქრობისას ოსმალებმა კონტროლი აღადგინეს. იმავე თარიღით ატლასში ოსმალეთიდან ჰაბსბურგებს გადასული სხვა დასახლებებია: არადი და ვილაგოში (შირია). არადის შესახებ წყარო მხოლოდ წელს ასახელებს (MKL, Arad: 1551-1688 წლებში ოსმალთა ხელში); დღე ლიპოვადანაა აღებული, ვილაგოში არადის ჯაჭვს მისდევს (გაცხადებული მიახლოებითობა). ლუგოშისა (ლუგოჟი) და კარანშებეშის (კარანსებეში) ციხეებიც ივნისის ბოლოს ავსტრიას გადაეცა (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["ვენეციის მიერ ევბეის ალყის მოგერიება", "aae7e6a0"], "d": ["მორეის დაპყრობის შემდეგ ეგეოსისკენ მიმართული მოროზინი სამ თვეზე მეტხანს გაგრძელებული ალყით ცდილობდა ევბეის (ეღრიბოზის) აღებას; მაგრამ 1687-1688 წლების ზამთარში გამაგრებული სიმაგრეებისა და გარნიზონის წინააღმდეგობის წინაშე, მძიმე დანაკარგებით, იძულებული გახდა უკან დაეხია. ამ მარცხმა ეგეოსში ვენეციის წინსვლა შეაჩერა და მოროზინის სამხედრო რეპუტაცია შეარყია. ევბეა კარლოვიცაზეც ოსმალთა ხელში დარჩებოდა.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["კანიჟის ციხის დაკარგვა ავსტრიის სასარგებლოდ", "553b45f3"], "d": ["1690 წლის იანვრიდან 60.000-კაციანი ჰაბსბურგული ჯარის მჭიდრო ბლოკადაში მოქცეულმა კანიჟამ თვეების განმავლობაში დახმარების გარეშე გაუწია წინააღმდეგობა და მისმა უკანასკნელმა მცველმა მუსტაფა-ფაშამ ხელმოწერილი კაპიტულაციის ხელშეკრულებით ციხე ხელიდან გაუშვა. ამგვარად, თირიაქი ჰასან-ფაშას ეპიკური თავდაცვით ცნობილ ციხეში ოთხმოცდაათწლიანი ოსმალთა ბატონობა დასრულდა. კანიჟის დაკარგვა უნგრეთის დასავლეთში ოსმალების უკანასკნელი დიდი საყრდენის ნგრევა იყო.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["სულეიმან II-ის გარდაცვალება", "d2478080"], "d": ["სულეიმან II, რომელიც „ყაფესში“ დაახლოებით ორმოცი წლის გატარების შემდეგ 1687 წელს აიყვანეს ტახტზე, ავადმყოფი, ჯარის მზადებას რომ ადევნებდა თვალს, 1691 წლის 22 ივნისს, პარასკევს, შუადღის ახლოს ედირნეში გარდაიცვალა; მისი სულთნობა სამ წელს, რვა თვესა და ორ დღეს გაგრძელდა. დიდ ვეზირს წინასწარ ჰქონდა გაცემული საჭირო მითითებები, რომ ფადიშაჰის გარდაცვალების შემთხვევაში ტახტზე მისი ძმა აჰმედი აეყვანათ. დაკრძალვის ლოცვა იმავე დღეს ალაი-ქიოშქში აღასრულეს; ნეშტი სტამბოლში ჩაასვენეს და სულთან სულეიმან კანუნის აკლდამაში, მის მარჯვენა მხარეს დაკრძალეს.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["აჰმედ II-ის ტახტზე ასვლა", "52947b14"], "d": ["სულეიმან II-ის გარდაცვალების შემდეგ ორმოცდაცხრა წლის ძმა აჰმედ II ედირნეში ტახტზე ავიდა. მისი მმართველობა წმინდა ლიგის ომების უმძიმეს წლებს დაემთხვა; მისი გამეფებიდან ორი თვის შემდეგ სალანკემენთან დიდი ვეზირი ფაზილ მუსტაფა-ფაშა შაჰიდად დაიღუპა. ამის საპირისპიროდ, მის ეპოქაში დანერგილი მალიქანეს სისტემა ოსმალური ფინანსების გრძელვადიანი სტრუქტურის შემცვლელი ერთ-ერთი უმნიშვნელოვანესი რეფორმა გახდა.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["მეჰმედ IV-ის გარდაცვალება ედირნეში", "17388b7e"], "d": ["1687 წელს ტახტიდან ჩამოგდებული ავჯი მეჰმედი სულეიმან II-ის 1689 წლის უნგრული ლაშქრობის დროს ედირნეში გადმოიყვანეს და ის თავისი მეორე ძმის, აჰმედ II-ის სულთნობის მოწმეც გახდა. ამ საყვარელ ქალაქში გარდაიცვალა. ნეშტი სტამბოლში ჩაასვენეს და დედამისის, ტურჰან სულთანის, იენიჯამის გვერდით მდებარე აკლდამაში დაკრძალეს.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["აჰმედ II-ის გარდაცვალება ედირნეში", "c6306c08"], "d": ["აჰმედ II, რომლის ოთხწლიანი სულთნობა ომში გავიდა, ორმოცდათორმეტი წლისა წყალმანკის (შეშუპების) გამო ედირნეში გარდაიცვალა. ნეშტი სტამბოლში ჩაასვენეს და სულთან სულეიმან კანუნის აკლდამაში დაკრძალეს. მის ადგილას მისი ძმისწული მუსტაფა II ავიდა.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["ბასრის ირანელების მიერ აღება", "a9cdf3a3"], "d": ["როცა ოსმალეთის სახელმწიფო დასავლეთში წმინდა ლიგის ომებით იყო დაკავებული, ბასრა 1690 წლის შავი ჭირის ეპიდემიის შემდეგ ჯერ მუნთაფიყის შეიხ მანიმ, შემდეგ კი ჰუვეიზეს ხან ფარაჯალაჰმა გაძარცვეს. ამ არეულობით ისარგებლეს ირანელებმა, 1696 წელს ქალაქი აიღეს და ბასრაში მცველი დატოვეს.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["სტამბოლის ზავი — აზოვის რუსეთისთვის დათმობა", "79db4724"], "d": ["კარლოვიცაზე რუსეთთან მხოლოდ ორწლიანი ზავის დადება იყო შესაძლებელი; მუდმივი ზავი სტამბოლში წელიწადნახევრიანი მძიმე ვაჭრობის შემდეგ მოეწერა ხელი. ოსმალეთის სახელმწიფომ 1696 წელს დაკარგული აზოვის ციხე და მისი შემოგარენი ოფიციალურად რუსეთს დაუთმო, ყირიმის ხანმა კი მოსკოვისგან მიღებულ ყოველწლიურ ხარკზე უარი თქვა. ამის სანაცვლოდ რუსეთმა სტამბოლში მუდმივი ელჩის ყოლის უფლება მოიპოვა; ამგვარად, შავი ზღვის ჩრდილოეთ სანაპიროზე რუსული ყოფნა სამართლებრივად დადასტურდა.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["დალთაბან მუსტაფა-ფაშას მიერ ყურნასა და ბასრის დაბრუნება", "7adb777d"], "d": ["კარლოვიცის ზავის შემდეგ ბაღდადის ვალად და ბასრის სერასქერად დანიშნული დალთაბან მუსტაფა-ფაშა ალეპოს, რაქას, სივასისა და ყარამანის ძალებით და ბირეჯიქიდან ჩამომავალი სამდინარო ფლოტით სამხრეთისკენ გაემართა. შემოგარენის ტომების შეიხები სათითაოდ დაემორჩილნენ, ირანის ბასრის მცველმა დაუდ ხანმა ქალაქი დატოვა და ყურნა და ბასრა კვლავ ოსმალთა მმართველობაში შევიდა.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["მუსტაფა II-ის გარდაცვალება", "626c394d"], "d": ["მუსტაფა II, რომელმაც ედირნეს ამბოხის შედეგად ტახტი თავის ძმას, აჰმედ III-ს დაუთმო, ტახტიდან ჩამოგდებიდან დაახლოებით ხუთი თვის შემდეგ საყვარელ ედირნეში გარდაიცვალა. მის ავადმყოფობას ბოლო მოვლენებით გამოწვეული მწუხარებაც დაემატა. ზოგიერთი დასავლური წყარო წერს, რომ ხალხში გავრცელებული იყო აზრი, თითქოს ის მოწამლეს.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["ბაღდადში მამლუქური (ქოლემენების) მმართველობის დაწყება", "abe52618"], "d": ["ქართული წარმოშობის ჰასან-ფაშას ბაღდადის მმართველად დანიშვნით ერაყში დაიწყო პერიოდი, როცა ცენტრიდან დანიშნული მმართველების ნაცვლად საკუთარი მონებისგან აღზრდილი მმართველი ფენა ბატონობდა. 1749 წელს სულეიმან-ფაშას მმართველობით სისტემა საბოლოოდ დამკვიდრდა და ბაბიალი იძულებული გახდა, დაენიშნა არა ვისაც სურდა, არამედ გავლენის ხელში ჩამგდები ერთ-ერთი ქოლემენი. ამ ნახევრად ავტონომიურმა სტრუქტურამ, მართალია, ირანის საზღვრის დაცვაში გამოადგა, მაგრამ საუკუნენახევრის განმავლობაში ერაყზე ცენტრალური ხელისუფლების კონტროლი შეასუსტა.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["ტუნისში ჰუსეინიანთა დინასტიის დაარსება", "cb1a98f9"], "d": ["ალჟირული ძალების მიერ ტუნისის შემოსევის შედეგად გაჩენილ ხელისუფლების ვაკუუმში თურქული წარმოშობის სიპაჰების აღა ჰუსეინ ბ. ალიმ ბეილიქი ხელში ჩაიგდო და ოსმალეთის ფადიშაჰისადმი ერთგულების გამოცხადებით ლეგიტიმაცია მოიპოვა. მის მიერ დაარსებული დინასტია ტუნისს 1705-1735 და 1756-1957 წლებში მართავდა; ოჯაღის მმართველობის ადგილი მამიდან შვილზე გადამავალმა ბეილიქის წესრიგმა დაიკავა. ამგვარად, მაღრიბის ოჯაღებში ცენტრზე მიბმული, მაგრამ ფაქტობრივად ავტონომიური დინასტიური სტრუქტურების პირველი ნიმუში გაჩნდა.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["ორანისა და მერს-ელ-ქებირის აღება ესპანელებისგან", "b67ce06a"], "d": ["ალჟირის ოჯაღის ბეგლარბეგის ძალებმა ორი საუკუნის განმავლობაში ესპანური გარნიზონის ხელში მყოფი ორანი და მისი ნავსადგური მერს-ელ-ქებირი ხანგრძლივი ალყის შემდეგ აიღეს. ეს დასავლეთ ხმელთაშუა ზღვაში ოსმალთა მფარველობაში მყოფი მაღრიბის ოჯაღების მიერ ესპანეთის წინააღმდეგ მოპოვებული უდიდესი წარმატება იყო და ალჟირის დასავლეთ ფრთა უზრუნველყო. ქალაქი 1732 წელს კვლავ ესპანურ ოკუპაციაში მოექცეოდა, საბოლოოდ კი 1792 წელს დაიბრუნეს.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["პრუთის ზავი — აზოვისა და ტაგანის დაბრუნება", "bac5d2a1"], "d": ["პრუთის ნაპირას ალყაში მოქცეული რუსული ჯარის დანებების შემდეგ ხელმოწერილმა შვიდმუხლიანმა ზავმა გაითვალისწინა აზოვის ციხის მიწებითა და საბრძოლო მასალით ოსმალებისთვის დაბრუნება. ტაგანის, კამენკისა და იენიქალეს სიმაგრეები უნდა დანგრეულიყო, მხარეები კი ამ მხარეში ახალ ციხეებს არ ააგებდნენ. პეტრე I-ის მიერ ვორონეჟსა და აზოვში თექვსმეტი წლის განმავლობაში შექმნილი ფლოტისა და ბაზების სისტემა ჩამოიშალა; რუსეთის შავ ზღვამდე ჩასვლა დაახლოებით ორმოცდაათი წლით დაყოვნდა.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["ტრიპოლიში ყარამანლის დინასტიის დაარსება", "e1105d4a"], "d": ["ოჯაღის აღების ქიშპით შეწუხებულ ტრიპოლიში (ლიბია) ცხენოსანი ოფიცერი აჰმედ ყარამანლი ხელისუფლებას დაეუფლა და სტამბოლიდან მიღებული ბეგლარბეგის ბერათით თავისი მდგომარეობა ოფიციალურად გააფორმა. აჰმედ-ფაშას, მისი ვაჟის მეჰმედ-ფაშასა და შვილიშვილის იუსუფ-ფაშას ხელით 1711-1835 წლებში არსებული დინასტია გაჩნდა; ჩამოყალიბდა ნახევრად დამოუკიდებელი სტრუქტურა, რომელმაც საკუთარი ფლოტი შექმნა და ევროპულ სახელმწიფოებთან პირდაპირ ხელშეკრულებებს დებდა. ეს პერიოდი მხოლოდ 1835 წელს, ეიალეთის ცენტრზე პირდაპირ მიბმით, დასრულდებოდა.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["რუსეთთან ედირნეს ზავი", "14901a70"], "d": ["პრუთთან მიცემული დაპირებების შეუსრულებლობის გამო კიდევ ორჯერ გამოცხადდა ომი, ბოლოს კი, რუსების მიერ ვალდებულებების მიღების შემდეგ, ედირნეში მუდმივი ზავი დაიდო. ზავმა პრუთის პირობები დაადასტურა; რუსეთი პოლონეთის საქმეებში აღარ ჩაერეოდა, კაზაკთა მიწებიდან გავიდოდა და შვედეთის მეფის, „დემირბაშ“ კარლის, სამშობლოში დაბრუნებას ხელს არ შეუშლიდა. ჩრდილოეთის ფრონტის ასე დახურვამ ოსმალეთის სახელმწიფოს საშუალება მისცა, ყურადღება მორეისა და ვენეციის ფრონტისკენ მიემართა. იმავე თარიღს შემოერთებული სხვა ადგილები: ხოტინი.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["ვენეციისთვის ომის გამოცხადება — მორეის ლაშქრობის მზადება", "d970b122"], "d": ["საბაბად იმის დასახელებით, რომ ვენეცია მხარს უჭერდა მონტენეგროელ მეამბოხეებს, ოსმალურ სავაჭრო ხომალდებს იტაცებდა და კარლოვიცაზე მიღებულ მორეას მძიმე გადასახადებით ჩაგრავდა, დივანში ომის გადაწყვეტილება მიიღეს. დიდი ვეზირ სილაჰდარ დამად ალი-ფაშას მიერ მომზადებული ლაშქრობა მომდევნო წელს ას დღეზე ნაკლებ დროში მთელი მორეის ნახევარკუნძულის დაბრუნებით დასრულდებოდა. თუმცა ეს წარმატება ავსტრიას აამოქმედებდა და 1716 წელს გაცილებით მძიმე ომის კარს გააღებდა.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["ტინოსის (ისტენდილის): ეგეოსში ვენეციის უკანასკნელი კუნძულის ჩაბარება", "4abec891"], "d": ["მორეის ლაშქრობაში გასულმა ფლოტმა გზად ტინოსის, ეგეოსში ვენეციის ხელში დარჩენილი ერთადერთი კუნძულის, წინ ღუზა ჩაუშვა. მიუხედავად იმისა, რომ ნაქსოსის საჰერცოგო 1566 წელს დაეცა, ლათინური მოსახლეობის წყალობით კუნძული კიდევ ას ორმოცდაათი წელი ვენეციურ დროშას ატარებდა და ხანმოკლე ალყის შემდეგ სისხლისღვრის გარეშე დანებდა. ამგვარად, ეგეოსის ზღვაში ვენეციის უკანასკნელი ნაფეხური წაიშალა და ზღვა მთლიანად ოსმალურ შიდა ზღვად იქცა.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["ნაფპლიონის (ანაბოლუს) აღება — მორეის საკვანძო ციხე", "62a5808a"], "d": ["მორეაში ვენეციის დედაქალაქი და უძლიერესი სიმაგრე ნაფპლიონი დაეცა, როცა პალამიდის რედუტი ცხრადღიანი დაბომბვის შემდეგ აიღეს. ციხის ასე სწრაფად აღებამ ნახევარკუნძულის დანარჩენ ნაწილში წინააღმდეგობა გატეხა. კარლოვიცაზე დაკარგული მორეის დაბრუნება ფაქტობრივად აქ დასრულდა. იმავე თარიღს ატლასში ვენეციიდან ოსმალებზე გადასული სხვა დასახლება: არგოსი — ის ნაფპლიონის „უფროსი ცენტრის“ ჯაჭვს მიჰყვება (TDV anabolu; დეკლარირებული მიახლოება).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["მოდონის ჩაბარება", "43faa909"], "d": ["ნაფპლიონის დაცემის შემდეგ მორეის სამხრეთ-დასავლეთ კიდეზე მდებარე მოდონის ციხეს ხმელეთიდან ჯარმა, ზღვიდან კი ფლოტმა ალყა შემოარტყა და მალე დანებდა. ეს ნავსადგური, რომელსაც ვენეცია აღმოსავლეთ ხმელთაშუა ზღვის ლაშქრობებში ორასი წელი იყენებდა, ხომალდებისთვის წყლისა და სურსათის ასაღები სავალდებულო გაჩერების პუნქტი იყო. მისმა დაკარგვამ ეგეოსში ვენეციური ფლოტის მოძრაობის უნარი დაასრულა.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["კორონის ჩაბარება — მორეის ლაშქრობის დასრულება", "e4b9c8a4"], "d": ["მესენიის ყურის შესასვლელის მაკონტროლებელი კორონის ციხის დანებებით მორეის ნახევარკუნძულზე ვენეციური მმართველობა სრულად დასრულდა. კარლოვიცაზე დაკარგული ნახევარკუნძული ლაშქრობის დაწყებიდან მხოლოდ სამი თვის შემდეგ მთლიანად დაბრუნდა. იმავე ლაშქრობის გაგრძელებაში, 1715 წლის სექტემბერში, იონიის ზღვაში მდებარე ლეფკადის (აია-მავრას) კუნძულიც ვენეციას წაართვეს. ამ სისწრაფემ ვენეცია აიძულა, ავსტრია ომში ჩაერთო, და სამი წლის შემდეგ პოჟარევაცისკენ მიმავალი გზა გაიხსნა.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["კუნძულ კითერას (Çuha) აღება", "494de6c6"], "d": ["მორეის სამხრეთ კიდეზე მდებარე კუნძული კითერა ნახევარკუნძულის სრული აღების შემდეგ ფლოტმა ჩაიბარა. იონიისა და ეგეოსის ზღვებს შორის გადასასვლელის დამკვირვებელი კუნძული იყო ის წინა ფორპოსტი, რომელსაც ვენეცია ამ წყლების საკონტროლებლად იყენებდა. მაგრამ ის ხელში შენარჩუნებულ ერთადერთ ოსმალურ კუნძულად არ დარჩენილა: სამი წლის შემდეგ პოჟარევაცში ვენეციას დაუბრუნეს.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["ავსტრიამ და ვენეციამ კავშირი დადეს — 1716-1718 წლების ოსმალეთ-ავსტრიის ომის კარი", "99511ca2"], "d": ["ოსმალების მიერ მორეის ვენეციისგან დაბრუნების შემდეგ ავსტრიამ, კარლოვიცის ზავის დარღვევის საბაბით, ვენეციასთან სამოკავშირეო ხელშეკრულება დადო; პრინც ევგენმა დიდ ვეზირს გაგზავნილ წერილში ვენეციისთვის წართმეული ადგილების დაბრუნება მოითხოვა. დავუთფაშას ბანაკში გამართულ თათბირზე დიდი ვეზირ ალი-ფაშას ზეწოლით ავსტრიას ომი გამოუცხადეს და ამისთვის შეიხულისლამისგან ფეთვა მიიღეს.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["დიდი ვეზირი ალი-ფაშა ავსტრიის ლაშქრობაში გაემართა", "2fbdce42"], "d": ["ავსტრიისთვის ომის გამოცხადების შემდეგ სერდარ-ი ექრემმა ალი-ფაშამ 100.000-ზე მეტი კაცისგან შემდგარი ჯარით ავსტრიის ლაშქრობაში გაილაშქრა; ფლოტი კი იმავე ზაფხულს კორფუსკენ გაემართა. ჯარი ბელგრადიდან ვარადინისკენ წავიდოდა და აგვისტოს დასაწყისში მარცხისას დიდი ვეზირი შაჰიდად დაიღუპებოდა.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["ვარადინის (პეტროვარადინის) მარცხი — დამად ალი-ფაშას დაღუპვა", "265c1d81"], "d": ["ბელგრადის გავლით დუნაის გადამლახველი ოსმალური ჯარი პრინც ევგენის სარდლობით ავსტრიულ ძალებს ვარადინის მისადგომებთან შეხვდა; მიუხედავად იმისა, რომ პირველ შეტევაზე იანიჩართა იერიშმა მტრის სანგრები შეავიწროვა, ცხენოსანი ფრთის ნგრევით რიგები დაიშალა. დიდი ვეზირი სილაჰდარ დამად ალი-ფაშა შუბლში მოხვედრილი ტყვიით შაჰიდად დაიღუპა; ბანაკი და მთელი საარტილერიო ტექნიკა მტრის ხელში გადავიდა. ეს მარცხი, რომელსაც ოსმალური ქრონიკები „ვარადინის წელს“ უწოდებენ, ტიმიშოარასა და მომდევნო წელს ბელგრადის დაკარგვამდე მიმავალი ჯაჭვის პირველი რგოლი იყო.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["კორფუს ალყის მარცხით დასრულება", "b2aa7011"], "d": ["მორეის სერასქერი ყარა მუსტაფა-ფაშა ხმელეთიდან, კაპუდან-ფაშა ჯანიმ ხოჯა მეჰმედ-ფაშა კი ფლოტით ზღვიდან დაეძგერა კორფუს; კუნძული ადრიატიკაში ვენეციის საკვანძო ბაზა იყო. თუმცა ციხის უკიდურესად ძლიერმა სიმაგრეებმა, ვენეციური ფლოტის მოყვანილმა გამაგრებამ და დუნაის ფრონტიდან მოსულმა მარცხის ამბებმა ალყის მოხსნა გამოიწვია. კორფუს ვერაღებამ მორეის ხელახალი დაპყრობით ამაღლებული განწყობა ჩააქრო და ომის სიმძიმის ცენტრი უნგრეთზე გადაინაცვლა.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["ტიმიშოარას (თემეშვარის) დაკარგვა ავსტრიის სასარგებლოდ", "27fe1365"], "d": ["ვარადინის მარცხის შემდეგ პრინცი ევგენი პირდაპირ ტიმიშოარასკენ გაემართა და ციხე ორმოც დღეზე მეტხანს გაგრძელებული ალყის ბოლოს კაპიტულაციით ჩაბარდა. ამგვარად ხელიდან გავიდა ქალაქი, რომელიც 1552 წელს კანუნის ეპოქაში აიღეს და 164 წლის განმავლობაში, როგორც საბეგლარბეგოს ცენტრი, უნგრეთის თავდაცვის აღმოსავლეთ ბურჯად ითვლებოდა. ტიმიშოარას დაცემით მთელი ბანატის მხარე ავსტრიაზე გადავიდა და ოსმალური საზღვარი დუნაის სამხრეთით გადაიწია. იმავე თარიღს ატლასში ოსმალებიდან ჰაბსბურგებზე გადასული სხვა დასახლებები: ჩაკოვარი (Csákóvár), ფაჩეტი (Facset) და კარანშებეში (Caransebeş) — ტიმიშოარას ეიალეთის გადაცემასთან ერთად (TDV timisvar; ადგილობრივ დონეზე დღე წყაროში არ არის, „უფროსი ცენტრის“ ჯაჭვი, დეკლარირებული მიახლოება).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["ჰარამის (იენი-პალანკის) ციხის ავსტრიისთვის ჩაბარება — ბანატის დუნაის ნაპირი ხელიდან გავიდა", "38ee4c6d"], "d": ["ტიმიშოარას დაცემის შემდეგ ბანატის დანარჩენი ნაწილის აღება დავალებული ავსტრიელი ცხენოსანი გენერალი მერსი 14 ნოემბერს დუნაის ნაპირას მდებარე ჰარამს (იენი-პალანკას) შეუტია; 16 ნოემბერს ციხესთან მისვლისას 200-კაციანმა ოსმალურმა გარნიზონმა თეთრი დროშა აღმართა და თავისუფლად გასვლის პირობით დანებდა. ამგვარად, 1552 წლიდან ოსმალთა ხელში მყოფი სამხრეთ ბანატის დუნაის ხაზიც ავსტრიაზე გადავიდა. იმავე თარიღს ატლასში ოსმალებიდან ჰაბსბურგებზე გადასული სხვა დასახლება: ვერშეცი — ის ჰარამის „უფროსი ცენტრის“ ჯაჭვს მიჰყვება (Bánlaky 0019/1703; დეკლარირებული მიახლოება).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["პოჟარევაცის ზავი — მორეა მოიგეს, ბელგრადი და ბანატი დაკარგეს", "d46aa216"], "d": ["მორეა ვენეციისგან დაბრუნებული იყო, მაგრამ ომში ჩართული ავსტრია პეტროვარადინსა და ბელგრადში მოპოვებული გამარჯვებებით მოლაპარაკების მაგიდასთან უპირატესი მივიდა. ინგლისისა და ჰოლანდიის შუამავლობით ხელმოწერილმა ზავმა მორეა ოსმალებს დაუტოვა, სამაგიეროდ ბელგრადთან ერთად ჩრდილოეთ სერბეთი, ბანატი და მცირე ვლახეთი ავსტრიას დაუთმეს; TDV-ის გამოთქმით, „ჩრდილოეთ ბოსნია მთლიანად ავსტრიას დაეთმო“ — სავას გასწვრივ მდებარე ისეთი ციხეები, როგორიცაა ბოსნიის დუბიცა და ბოსნიის ბროდი, რუკაზე ამ დღიდან ავსტრიაზე გადადის (ზუსტი საზღვარი კომისრებმა სათითაოდ გაავლეს, TDV ამ ციხეებს სახელებით არ ჩამოთვლის); ვენეციამ კი იონიის სანაპიროზე ისეთი პოზიციები შეინარჩუნა, როგორიცაა პრევეზა და კითერა. იმავე დღეს ხელმოწერილი სავაჭრო აჰდნამეთი ავსტრიული საქონლის საბაჟო გადასახადი ხუთი პროცენტიდან სამამდე შემცირდა. ზავმა ცენტრალურ ევროპაში ოსმალეთის სახელმწიფოს უკანდახევა დააფიქსირა, მაგრამ მის მიერ გახსნილმა ოცდაშვიდწლიანმა მშვიდობამ ტიტების ეპოქის (1718-1730) საფუძველი შექმნა: ნევშეჰირლი დამად იბრაჰიმ-ფაშას მმართველობისას პირველი ოსმალური სტამბა (1727, იბრაჰიმ მუთეფერიქა), სათარგმნო კომისიები, ყვავილის აცრის დაკვირვებები და სასახლის ახალი კულტურული ცხოვრება ამ სამშვიდობო წლების ნაყოფია. იმავე დღეს ატლასში ხელიდან ხელში გადასული სხვა დასახლებები: კრაიოვა (Craiova), რიმნიკი (Râmnicu Vâlcea) და ტურნუ-სევერინი (მცირე ვლახეთი/ოლტენია, ოსმალებიდან ავსტრიაზე) და ლეფკადა (აია-მავრა) (ოსმალებიდან ვენეციაზე; TDV ayamavra: 1718 წელს პოჟარევაცის ზავით კუნძული ვენეციას დაეთმო). მცირე ვლახეთში ასევე თარგუ-ჯიუ ავსტრიაზე; ვონიცა (Voniçe, TDV pasarofca-antlasmasi) და კუნძული კითერა (TDV cuka-adasi: პოჟარევაცის მე-3 მუხლი) ვენეციაზე გადადის.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["აღმოსავლური ლაშქრობა: თბილისის აღება და ირანთან ომის დაწყება", "78343dc2"], "d": ["ავღანელთა შემოსევით სეფიანთა სახელმწიფოს ნგრევისა და რუსეთის კასპიის სანაპიროებამდე ჩამოსვლის გამო, ოსმალეთის სახელმწიფომ აღმოსავლეთში ჯარი გაგზავნა, რათა გაჩენილი სიცარიელე სრულად რუსული გავლენის ქვეშ არ დარჩენილიყო. თბილისი აიღეს და საქართველო ოსმალთა მმართველობას დაუქვემდებარეს; შემდეგ წინსვლა განჯის, ერევნისა და ნახიჭევანის მიმართულებით გაგრძელდა. ტიტების ეპოქის მშვიდობიანი იმიჯის უკან წარმოებული ეს ლაშქრობა იყო იმ ხანგრძლივი აღმოსავლური თავგადასავლის დასაწყისი, რომელიც ცამეტი წელი გაგრძელდებოდა და ბოლოს ყველა აღებული ადგილის დაბრუნებით დასრულდებოდა.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723 წლის ირანული ლაშქრობა: შესვლა შირვანსა და საქართველოში", "c81189fc"], "d": ["ავღანელთა შემოსევით სეფიანთა სახელმწიფოს ნგრევის გამო, რუსეთის კასპიის სანაპიროებამდე ჩამოსვლის თავიდან ასაცილებლად აღმოსავლეთისკენ ლაშქრობა გაიხსნა. ერზურუმის ჯარი საქართველოს გავლით თბილისში, შირვანის ფრთა კი შამახიაში შევიდა და ას ოცდაათი წლის წინ დაკარგული მიწები დაიბრუნა. ეს ლაშქრობა კავკასიაში ოსმალთა უკანასკნელი დიდი წინსვლა გახდა.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["ქერმანშაჰის აღება — ზაგროსის კარი", "ad14799f"], "d": ["ბაღდადის ჯარმა ზაგროსის გადასასვლელები გადალახა და ირანის დასავლეთ კარად მიჩნეული ქერმანშაჰი აიღო. ქალაქი ბაღდადიდან ისპაჰანისკენ მიმავალი ქარავნისა და ჯარის გზაზე მდებარეობდა და მისი აღება ერაყის ეიალეთის აღმოსავლეთ უსაფრთხოებას უზრუნველყოფდა. ამ წინსვლამ დაშლილ სეფიანთა ქვეყანაში ოსმალებსა და რუსეთს შორის გაყოფის რბოლა დაიწყო.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["სტამბოლის გაყოფის ხელშეკრულება — ირანის გაყოფა რუსეთთან", "fce8eec2"], "d": ["დამხობილი სეფიანთა ქვეყნის საკითხზე ოსმალებისა და რუსეთის დაპირისპირების თავიდან ასაცილებლად ფრანგი ელჩის შუამავლობით გაყოფის ხელშეკრულება დაიდო. კასპიის ზღვის დასავლეთი და სამხრეთი სანაპიროები რუსეთს, საქართველო, შირვანი, აზერბაიჯანი და დასავლეთ ირანის ქალაქები კი ოსმალეთის სახელმწიფოს დარჩა. ქაღალდზე დიდ შენაძენად გამოჩენილი ეს გაყოფა მალე, ნადირ შაჰის აღზევებით, ფაქტობრივად ძალადაკარგული გახდებოდა. ხელშეკრულების მიხედვით, შირვანის ისეთი ნაყოფიერი მიწები, როგორიცაა შაბრანი და მუშქური, რუსეთის მხარეს დარჩა (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["ნახიჭევანის აღება", "bdf14d0a"], "d": ["არაქსის გასწვრივ წინ მიმავალმა ოსმალურმა ძალებმა ნახიჭევანი და ორდუბადი აიღეს; ჯულფაც ნახიჭევანის ლივას შეუერთდა. ქალაქი, ირანის ჩრდილო-დასავლეთი კარის სახით, ახლად დაარსებულ ერევნის ეიალეთს დაუქვემდებარეს. ამგვარად, ოსმალური საზღვარი კანუნის ეპოქის ყველაზე აღმოსავლურ ხაზს კვლავ მიაღწია.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["ჰამადანის დაპყრობა", "e1339a97"], "d": ["ქერმანშაჰიდან აღმოსავლეთისკენ მიმავალმა ჯარმა ირანის პლატოს დასავლეთ ზღურბლზე მდებარე ჰამადანი ხანგრძლივი ალყის შემდეგ აიღო. ქალაქი ისპაჰანის გზაზე უკანასკნელი დიდი გაჩერება იყო; ეს გზა ორი ერაყის ლაშქრობის შემდეგ ოსმალური ჯარებისთვის ყველაზე აღმოსავლური მისაღწევი მიმართულება იყო. იმავე წელს რუსეთთან ხელმოწერილმა სტამბოლის ხელშეკრულებამ დაშლილი ირანის ოსმალებსა და რუსეთს შორის გაყოფა ქაღალდზე გადაიტანა.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["ერევნის ხელახალი აღება", "88acabef"], "d": ["ოთხმოცდაათდღიანი მძიმე ალყის შემდეგ არაქსის ხეობის საკვანძო ციხე ერევანი კვლავ ოსმალურ მმართველობაში შევიდა. 1583 წელს აშენებული და 1604 წელს დაკარგული ციხე ამჯერად უფრო ძლიერი გარნიზონით გაამაგრეს. ალყის ხანგრძლივობა იმის მაჩვენებელი იყო, რომ ოსმალური ჯარი უკვე ადვილად ვეღარ მიიწევდა. კარპის (უჩქილისე), შარურის, მაკუსა და შურაგელის ნაჰიეებიც ერევნის ეიალეთს დაუქვემდებარეს.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["თავრიზის აღება — აზერბაიჯანის დაკავება", "e502a4f7"], "d": ["ერთი წლის წინ წარუმატებელი მცდელობის შემდეგ კვლავ ალყაში მოქცეული თავრიზი ქუჩა-ქუჩა გაგრძელებული მძიმე ბრძოლის შემდეგ ოსმალურ ჯარს დანებდა. თავრიზის ეიალეთზე დაქვემდებარებული მერენდი, მარაღა და სოვუყბულაყი (მაჰაბადი) ასევე ოსმალთა მმართველობაში შევიდა. იმავე წელს ლორი, განჯა, არდებილი და ხორემაბადიც აიღეს და სტამბოლის გაყოფის ხელშეკრულებით ოსმალთა წილად მოხვედრილი მხარეები ფაქტობრივად ოკუპირებული იქნა. აღმოსავლეთში მიღწეული ეს სივრცე ფერჰად-ფაშას ზავის ხანის შემდეგ ყველაზე წინ წაწეული საზღვარი იყო; მაგრამ მისი შენარჩუნება ჯარსა და ხაზინას მძიმე ტვირთად დააწვა.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["განჯის აღება — კავკასიის ლაშქრობის დასასრული", "875bca7a"], "d": ["კავკასიის ოპერაციის უკანასკნელი სამიზნე განჯა, მტკვარსა და არაქსს შორის მდებარე ყარაბაღის ცენტრი, ჩაიბარეს. შირვანის, ერევნის, ნახიჭევანისა და განჯის ხაზის დასრულებით ოსმალეთის სახელმწიფომ კავკასიაში 1590 წლის სიდიდეს მიაღწია. თუმცა ეს შენაძენი ხანმოკლე გამოდგა: ნადირ შაჰის აღზევება ათ წელიწადში მთელ მხარეს დაიბრუნებდა.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["ჰამადანის ზავი — დასავლეთ ირანის ოსმალეთთან შეერთება", "94a29dc3"], "d": ["ავღანელ მმართველ აშრაფ შაჰთან ხელმოწერილი ზავით ოთხწლიანი ომი დასრულდა და ოსმალეთის სახელმწიფოს მიერ ოკუპირებული დასავლეთ ირანის მიწები სამართლებრივად აღიარეს. სანაცვლოდ აშრაფ შაჰმა ოსმალო ფადიშაჰის ხალიფობა აღიარა და ირანში ხუტბის ფადიშაჰის სახელით წაკითხვა იკისრა. ეს დიპლომატიური გამარჯვება ხანმოკლე გამოდგა; ნადირ შაჰის მიერ 1730 წელს წამოწყებული კონტრშეტევა რამდენიმე წელიწადში ზავის მონაპოვარს გააქრობდა.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["ჰექიმოღლუ ალი-ფაშამ რუმიე აიღო", "eac7f64d"], "d": ["ირანის ლაშქრობისას ჰექიმოღლუ ალი-ფაშამ ჯერ ურმია (რუმიე) აიღო, შემდეგ კი, 1731 წლის 15 ნოემბერს, ოსმალებისთვის დაცლილი თავრიზი. TDV ურმიის აღების დღეს არ ასახელებს; ცნობილია მხოლოდ წელი და ის, რომ ეს თავრიზის აღებამდე მოხდა.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["აჰმედ-ფაშას ზავი — დასავლეთ ირანის დიდი ნაწილის დაბრუნება", "590d839f"], "d": ["ნადირ შაჰის მელაიერთან მოპოვებული გამარჯვებისა და ერთმანეთის მიყოლებით ირანული შეტევების შემდეგ ბაღდადის მმართველმა აჰმედ-ფაშამ ცენტრთან შეუთანხმებლად სამშვიდობო ტექსტს მოაწერა ხელი. ზავის მიხედვით საზღვრად მდინარე არაქსი აღიარეს; დასავლეთ ირანის ისეთი ქალაქები, როგორიცაა ჰამადანი, ქერმანშაჰი, არდალანი, არდებილი და თავრიზი, ირანს დაუბრუნდა, განჯა და თბილისი კი ოსმალებს დარჩა. სტამბოლში უკმაყოფილებით მიღებული ეს ტექსტი ნადირ შაჰმაც არასაკმარისად მიიჩნია და 1732 წლის ამოწურვამდე ომი კვლავ გაჩაღდა. ატლასი ხოის ჯაჭვის მიმყოლ ქოთურსაც ამ დღეს ოსმალებიდან სეფიანებზე გადასულად თვლის (TDV hoy; ქოთურისთვის კონკრეტული დღე წყაროში არ არის — დეკლარირებული მიახლოება).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["ორანის ხელახალი დაკარგვა ესპანეთის სასარგებლოდ", "20485027"], "d": ["ესპანეთის მეფე ფელიპე V-ის მიერ გაგზავნილი დიდი სადესანტო ესკადრა კონტ მონტემარის სარდლობით ორანის მისადგომებთან მივიდა, ალჟირის ოჯაღის ძალები დაამარცხა და ქალაქი დაიბრუნა. ოცდაოთხი წლის წინ აღებული ნავსადგური სამოცი წლის განმავლობაში კვლავ ესპანური გარნიზონის ხელში დარჩებოდა. დასავლეთ ხმელთაშუა ზღვაში მაღრიბის ოჯაღების ძალის საზღვრების მაჩვენებელი ეს დანაკარგი მხოლოდ 1792 წელს ორანის საბოლოო აღებით ანაზღაურდა.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["ხუმბარაჯების კორპუსის ევროპული წესით რეფორმა და ხუმბარაჰანეს დაარსება", "d980cf2a"], "d": ["ოსმალთა სამსახურში შესულმა ფრანგული წარმოშობის ხუმბარაჯი აჰმედ-ფაშამ დიდი ვეზირ ჰექიმოღლუ ალი-ფაშას მხარდაჭერით ხუმბარაჯების (ყუმბარმტყორცნელთა) კორპუსი ხელფასიან და ევროპულ ყაიდაზე მოწყობილ ნაწილად აქცია. ბოსნიიდან აყვანილ სამას ჯარისკაცს არითმეტიკასა და გეომეტრიაზე დაფუძნებული რეგულარული განათლება მისცეს; ორგანიზაციის, აღჭურვილობისა და პენსიისთვის ახალი ნიზამნამეები მოამზადეს, თანამედროვე ტექნიკით ასი ყუმბარმტყორცნი და ორმოცდაათი ათასი ყუმბარა დაამზადეს. გეომეტრიის სასწავლებელი ხუმბარაჰანე ოსმალეთში თანამედროვე სამხედრო-საინჟინრო განათლების პირველ ბირთვად ითვლება.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["აჰმედ III-ის გარდაცვალება", "455f7fba"], "d": ["1730 წელს პატრონა ხალილის აჯანყებით ტახტიდან ჩამოგდებულმა აჰმედ III-მ სიცოცხლის ბოლო ექვსი წელი თოფკაფის სასახლის ტახტიდან ჩამოგდებული ფადიშაჰებისთვის განკუთვნილ სადგომში გაატარა და სამოცდასამი წლის ასაკში გარდაიცვალა. ის ბაჰჩეკაფიში, იენიჯამის გვერდით, თავისი ბებიის, ტურჰან სულთანის, აკლდამაში დაკრძალეს.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["სტამბოლის ზავი — სამხრეთ კავკასიის ირანისთვის დათმობა", "8c205aab"], "d": ["ოთხწლიანი მეორე ირანული ომი არფაჩაის მარცხისა და განჯისა და თბილისის დაკარგვის შემდეგ ხელმოწერილი ზავით დასრულდა. ოსმალეთის სახელმწიფო 1723 წლიდან აღებული სამხრეთ კავკასიისა და დასავლეთ ირანის ყველა მიწიდან გავიდა, საზღვარი კი 1639 წლის ყასრ-ი შირინის ხაზს დაუბრუნდა. ცამეტწლიანი აღმოსავლური ლაშქრობებიდან დარჩა მძიმე ფინანსური ტვირთი და დაცარიელებული ხაზინა; ამის საპირისპიროდ, რუსეთთან დაწყებული ახალი ომისთვის აღმოსავლეთის ფრონტის დახურვა სასიცოცხლო მონაპოვარი იყო.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["ოჩაკოვის (ოზის) ციხის რუსების ხელში ჩავარდნა", "f93e61f3"], "d": ["ფელდმარშალ მიუნიხის სარდლობით რუსულმა ჯარმა დნეპრის შესართავთან მდებარე ოჩაკოვის ციხეს ალყა შემოარტყა; საბრძოლო მასალის საწყობის აფეთქებით თავდაცვა ჩამოიშალა და ციხე დიდი ადამიანური დანაკარგებით დაეცა. შავი ზღვის ჩრდილო-დასავლეთ სანაპიროს საკეტად მიჩნეული ოჩაკოვის დაკარგვამ რუსებს ყირიმისკენ გზა გაუხსნა და სტამბოლში დიდი პანიკა გამოიწვია. ციხე მომდევნო წელს ეპიდემიისა და მომარაგების სირთულის გამო რუსებმა დაცალეს და კვლავ ოსმალებზე გადავიდოდა.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["ბანია-ლუკის გამარჯვება — ბოსნიის გადარჩენა", "f603865a"], "d": ["როცა ავსტრიული ძალები ბოსნიაში შევიდნენ და ბანია-ლუკას ალყა შემოარტყეს, ბოსნიის მმართველი ჰექიმოღლუ ალი-ფაშა ადგილობრივი მოსახლეობიდან შეკრებილი ძალებით საშველად მივიდა და რიცხვით უპირატეს მტერს მძიმე მარცხი აგემა. ამ გამარჯვებამ ავსტრიის ბოსნიის ოკუპაციის გეგმა პირველივე ნაბიჯზე ჩაშალა და ეიალეთის ჩრდილოეთი მთლიანად დაბრუნდა. ბანია-ლუკა ერთ-ერთი გარდამტეხი მომენტი გახდა, რომელმაც 1683 წლის შემდეგ ავსტრიის წინაშე გამუდმებით უკან დახეული ოსმალური ჯარის სულისკვეთება აღადგინა.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["გროცკას (ჰისარჯიქის) გამარჯვება — ბელგრადის გზის გახსნა", "2101cdff"], "d": ["ბელგრადის დასაცავად წინ წაწეული ავსტრიული ჯარი დუნაის ნაპირას ვიწრო ხეობაში ჩასაფრებაში მოხვდა და მთელი დღის ბრძოლაში მძიმე დანაკარგები განიცადა. ფელდმარშალ ვალისის ძალები უწესრიგოდ იხევდნენ ბელგრადისკენ, ოსმალური ჯარი კი ციხის მისადგომებს მიადგა და ალყა დაიწყო. გროცკა კარლოვიციდან მოყოლებული ავსტრიის წინააღმდეგ მოპოვებული ყველაზე გადამწყვეტი საველე გამარჯვება იყო და პირდაპირ ბელგრადის დაბრუნება უზრუნველყო.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["ნიშის ზავი — ზავი რუსეთთან, აზოვის ნეიტრალიზება და ყირიმელთა თავდასხმების შეჩერება", "674f974e"], "d": ["ავსტრიის ბელგრადთან ზავზე დათანხმების შემდეგ მარტო დარჩენილი რუსეთი ფრანგი ელჩის ვილნევის შუამავლობით იძულებული გახდა ომი დაესრულებინა. აზოვის ციხის სიმაგრეები დაანგრიეს და მხარე ორ სახელმწიფოს შორის ნეიტრალურ ტერიტორიად გამოაცხადეს; რუსეთმა მიიღო პირობა, რომ შავ ზღვაში საბრძოლო და სავაჭრო ხომალდები არ ეყოლებოდა. ამგვარად, რუსეთის ზღვაზე გასვლის მიზანი კიდევ ერთი თაობით გადაიდო და ოსმალეთის სახელმწიფო XVIII საუკუნეში უკანასკნელად წამოდგა მოლაპარაკების მაგიდიდან მოგებული.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["ოჩაკოვი რუსული ოკუპაციიდან დაბრუნდა: 1739 წლის ზავით ციხე დანგრევის შემდეგ ჩააბარეს", "7ecc2bef"], "d": ["რუსებმა ოჩაკოვი 1737 წლის 11 ივლისს აიღეს. 1739 წელს რუსეთთან დადებული ზავის თანახმად, ციხის სიმაგრეების დანგრევის შემდეგ იგი კვლავ ოსმალებს ჩააბარეს; ოსმალებს ოჩაკოვი იასის ზავის წინა 1788 წლამდე ეპყრათ.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["მოსულის თავდაცვა — ნადირ შაჰის მოგერიება", "c03ffbc1"], "d": ["ქირქუქისა და ერბილის აღების შემდეგ მოსულის მისადგომებთან მისულმა ნადირ შაჰმა ორმოცი დღის განმავლობაში ქალაქი ზარბაზნებით დაბომბა და ერთმანეთის მიყოლებით საერთო იერიშები მოაწყო. ვალი ჰუსეინ-ფაშა ალ-ჯალილის მიერ ქალაქის მოსახლეობის შეიარაღებითაც წარმოებულმა თავდაცვამ ირანული ჯარი მძიმე დანაკარგებით ალყის მოხსნაზე აიძულა. მოსულის გამაგრებამ მთელი ერაყის ხელიდან გასვლა აღკვეთა და ჯალილის ოჯახის გავლენა ქალაქში ერთი საუკუნით განამტკიცა.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["დირიას კავშირი — ნეჯდში პირველი საუდის საამიროს დაარსება", "188751bf"], "d": ["უიაინადან გაძევებული ღვთისმეტყველი მუჰამად იბნ აბდ ალ-ვაჰაბი დირიაში მფარველობაში მიიღო ამირმა მუჰამად იბნ საუდმა და მასთან კავშირი შეკრა, რომლითაც პოლიტიკური ხელისუფლება რელიგიური ქადაგების სამსახურში ჩააყენა. ამ შეთანხმებამ საუდის ოჯახისთვის ახალი ისტორია დაიწყო და ნეჯდის დაქსაქსული ოაზისების საამიროები ერთი მოძრაობის გარშემო გააერთიანა. ნახევარ საუკუნეში ქერბალამდე, მექასა და მედინამდე მიმავალი ეს ძალა ოსმალეთის სახელმწიფოს აიძულებდა ჰიჯაზში თავისი ბატონობის დაცვას.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["ქერდანის ზავი — ოსმალეთ-ირანის ომების დასასრული", "1d3a919e"], "d": ["ოთხწლიანი უკანასკნელი ომის შემდეგ ხელმოწერილი ზავით 1639 წლის ყასრ-ი შირინის საზღვარი უცვლელად განახლდა; ვერც ერთმა მხარემ ტერიტორიული შენაძენი ვერ მიიღო. ნადირ შაჰის დაჟინებული მოთხოვნა ჯაფარიზმის მეხუთე მაზჰაბად აღიარების შესახებ უპასუხოდ დარჩა; სამაგიეროდ გადაწყდა, რომ ირანელ მომლოცველებს ჰაჯის თავისუფლად აღსრულება შეეძლებოდათ და მხარეები ელჩებს გაცვლიდნენ. ამგვარად, ორ საუკუნეზე მეტხანს გაგრძელებული ოსმალეთ-ირანის ომები ფაქტობრივად დასრულდა; ეს საზღვარი დღემდე დიდწილად შენარჩუნებულია.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["მაჰმუდ I-ის გარდაცვალება და ოსმან III-ის ტახტზე ასვლა", "30203700"], "d": ["ოცდაოთხწლიან მმართველობაში ბელგრადის ზავით დაკარგული მიწების დამბრუნებელი და ხუმბარაჯების კორპუსის რეფორმის მხარდამჭერი მაჰმუდ I პარასკევის სალამიდან დაბრუნებისას გარდაიცვალა. მის ადგილზე ავიდა ძმა ოსმან III, რომელმაც ორმოცდათვრამეტ წლამდე გალიაში იცხოვრა. დაიწყო ხანმოკლე და შფოთიანი მმართველობა; ოსმან III-ის ეპოქაში, რომელმაც სამ წელიწადში ექვსი დიდი ვეზირი შეცვალა, სახელმწიფო საქმეებში შესამჩნევი უძრაობა სუფევდა.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["ოსმან III-ის გარდაცვალება და მუსტაფა III-ის ტახტზე ასვლა", "3ac10f85"], "d": ["სამწლიანი მმართველობის შემდეგ ოსმან III-ის გარდაცვალებით ტახტზე ავიდა მუსტაფა III, რომელიც რეფორმის იდეებისთვის ღია იყო და სახელმწიფო საქმეებით ახლოს ინტერესდებოდა. ახალმა ფადიშაჰმა, დიდი ვეზირ ქოჯა რაღიბ-ფაშას გამოცდილებაზე დაყრდნობით, ფინანსების გამოსწორება და ჯარის განახლება სცადა; ბარონ დე ტოტის სწრაფმსროლელი არტილერისტები ამ ეპოქაში შეიქმნა. თუმცა 1768 წელს დაწყებული რუსეთთან ომი ჩვიდმეტწლიანი მმართველობის ყველა მონაპოვარს დაჩრდილავდა.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["რუსეთისთვის ომის გამოცხადება — ბალტას ინციდენტი და 1768-1774 წლების ომის დაწყება", "9c6aabe0"], "d": ["პოლონეთში ბარის კონფედერაციის მდევნელი რუსული და კაზაკური ნაწილები ოსმალურ საზღვარზე მდებარე ქალაქ ბალტას თავს დაესხნენ და გადაწვეს; ამის გამო დივანმა ომის გადაწყვეტილება მიიღო, რუსი ელჩი კი იედიკულეში ჩასვეს. სერიოზული სამხედრო მზადების გარეშე და ექვსი თვით ადრე გამოცხადებული ომი თავიდანვე ცუდად წარიმართა. ექვსი წლის განმავლობაში გაგრძელებული ეს ბრძოლა ჩესმის თავდასხმით, კაგულის მარცხითა და ყირიმის ოკუპაციით ოსმალეთის ისტორიის უმძიმეს მარცხთა ერთ-ერთ ჯაჭვად გადაიქცეოდა.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["ხოტინის ციხის დაკარგვა რუსების სასარგებლოდ", "66d43ea4"], "d": ["პრინც გოლიცინის სარდლობით რუსული ჯარის ორი მცდელობა მოგერიებული იყო, მაგრამ კამენეცსა და ხოტინს შორის დიდი ვეზირის განცდილი მარცხის გამო ჯარმა უკან დაიხია და მცველებმა ციხე დაცალეს. დუნაის ჩრდილოეთით ოსმალთა ყველაზე ძლიერი სიმაგრის წინააღმდეგობის გარეშე ხელიდან გასვლამ ვლახეთისა და მოლდოვის კარი რუსებს გაუღო. ორივე სამთავრო იმავე წელს ოკუპირებული იქნა; ხოტინის დაბრუნება მხოლოდ 1774 წელს ქუჩუკ-ქაინარჯის ზავით გახდა შესაძლებელი.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["კაგულის (ქართალის) ველის მარცხი", "6f408eaf"], "d": ["ჩესმეში ფლოტის დაწვიდან სამი კვირის შემდეგ დუნაის ნაპირზე მდგარი ოსმალთა მთავარი ჯარი კაგულის ველზე ფელდმარშალ რუმიანცევის რიცხვით გაცილებით მცირე, მაგრამ დისციპლინირებული ნაწილების წინაშე დაიშალა. ბანაკი, ტვირთი და ასობით ქვემეხი მტრის ხელში ჩავარდა; გაქცეულმა ნაწილებმა დუნაის გადალახვისას დიდი დანაკარგი განიცადეს. იმავე ზაფხულს ფლოტისა და სახმელეთო ჯარის განადგურებამ ქილიის, აკერმანის, იზმაილისა და ბენდერის მიყოლებით დაცემა და ყირიმის ოკუპაცია გამოიწვია.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["ყირიმის ნახევარკუნძულის რუსული ოკუპაცია", "217837b0"], "d": ["ერთი წლის წინ ბუჯაკის დამკავებელმა რუსულმა ჯარებმა, პრინც დოლგორუკოვის სარდლობით, ორ ყაფის (პერეკოპის) გადალახვით მთელი ყირიმის ნახევარკუნძული შეიპყრეს. ხანი ტახტიდან ჩამოაგდეს, რუსეთის მომხრე საჰიბ გირაი სათავეში დააყენეს და სახანოს ოსმალეთისგან მოწყვეტისკენ პირველი ნაბიჯი გადაიდგა. სამი საუკუნის განმავლობაში ოსმალეთის ჩრდილოეთის ფარად მყოფი ყირიმის ხელიდან გასვლა 1774 წელს დამოუკიდებლობის, 1783 წელს კი პირდაპირი ანექსიის პროცესის დასაწყისი იყო.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["მუსტაფა III-ის გარდაცვალება და აბდულჰამიდ I-ის ტახტზე ასვლა", "42cba8e2"], "d": ["რუსეთთან ომის ყველაზე კრიზისულ მომენტში გარდაცვლილი მუსტაფა III-ის ადგილზე ძმა აბდულჰამიდ I, რომელმაც ორმოცდასამი წელი სასახლის გალიაში გაატარა, ორმოცდაცხრა წლის ასაკში ავიდა ტახტზე. სახელმწიფოს ერთ-ერთი ყველაზე რთული პერიოდის ჩამბარებელი ახალი ფადიშაჰი იმავე წელს ხელმოსაწერი ქუჩუკ-ქაინარჯის ზავის მძიმე პირობებს შეეჯახა. მისი თხუთმეტწლიანი მმართველობა ყირიმის დაკარგვითა და ახალი რუსულ ომით გაივლის და 1789 წელს ოჩაკოვის დაცემის ცნობის კითხვისას მომხდარი ინსულტით დასრულდება.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["კოზლუჯის მარცხი — ქუჩუკ-ქაინარჯამდე მიმყვანი დამარცხება", "8e0542f9"], "d": ["შუმენთან შეკრებილი ოსმალური ძალები კოზლუჯასთან სუვოროვისა და კამენსკის გაერთიანებულ კოლონებთან დამარცხდნენ და ჯარის დიდი ნაწილი დაიშალა. ამ მარცხის შემდეგ ბალკანეთში წინააღმდეგობის გასაწევი ძალა აღარ დარჩა; რუსულმა ავანგარდებმა შუმენს ალყა შემოარტყეს და დიდი ვეზირის შტაბი საფრთხის ქვეშ აღმოჩნდა. ერთი თვის გასვლამდე ქუჩუკ-ქაინარჯაში მოლაპარაკების მაგიდასთან დაჯდომა და არაჩვეულებრივად მძიმე პირობების მიღება პირდაპირ ამ მარცხის შედეგია.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["ბუკოვინის (ჩრდილოეთ მოლდოვის) ავსტრიისთვის დათმობა", "190f9caa"], "d": ["ქუჩუკ-ქაინარჯის გამოწვეული სისუსტით ისარგებლა ავსტრიამ, მოლდოვასა და ტრანსილვანიას შორის კავშირის მამყარებელი ბუკოვინის მხარე მოითხოვა და ომში ჩართვის გარეშე, მუქარითა და ქრთამით, ეს მიწა მიიღო. ხოტინის სამხრეთ-დასავლეთით მდებარე ამ ნაყოფიერი და სტრატეგიული მხარის დაკარგვამ მოლდოვის სავოევოდო ფაქტობრივად ორად გაყო. ერთი ტყვიის გასროლის გარეშე განხორციელებული ეს დათმობა ერთ-ერთ ყველაზე აშკარა მაჩვენებლად ჩაითვალა იმისა, რომ ოსმალეთის სახელმწიფომ შემაკავებელი ძალა დაკარგა. 1775 წელს ბუკოვინის დათმობით სუჩავა და ჩერნოვცი ავსტრიაზე გადავიდა (დღე დაუდასტურებელია).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["ბასრის ირანული ოკუპაციის ქვეშ მოქცევა", "0161e709"], "d": ["ზანდელი მმართველის ქერიმ ხანის ძმა სადიყ ხანმა ერთწლიანი ალყის შემდეგ ბასრა აიღო და ოსმალეთის სახელმწიფომ სპარსეთის ყურეში უმნიშვნელოვანესი ნავსადგური დაკარგა. ოკუპაციამ პირდაპირ შეარყია ინდოეთის სავაჭრო გზა, ფინიკისა და მარგალიტის შემოსავლები და ერაყის სამხრეთის თავდაცვა. ქალაქის დაბრუნება მხოლოდ 1779 წელს, ქერიმ ხანის გარდაცვალების შემდეგ ირანში ატეხილი ტახტისთვის ბრძოლების დროს, გახდა შესაძლებელი.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["აინალიყავაქის დამატებითი ხელშეკრულება — დროებითი შეთანხმება ყირიმზე", "9b3b0468"], "d": ["ყირიმის სახანოს სათავეში ვინ ჩადგებოდა, ამის გამო ომის ზღვარზე მისულმა ორმა სახელმწიფომ საფრანგეთის შუამავლობით აინალიყავაქის კოშკში განმარტებითი ტექსტი ხელმოაწერეს. რუსეთმა ყირიმიდან ჯარის გაყვანაზე, ოსმალეთის სახელმწიფომ კი რუსეთის მომხრე შაჰინ გირაის ხანობის აღიარებაზე დათანხმდა; ფადიშაჰის რელიგიური, ხალიფის უფლება ყირიმზე დადასტურდა. ოთხი წლის განმავლობაში გაგრძელებული ეს მყიფე ბალანსი 1783 წელს რუსეთის მიერ ნახევარკუნძულის პირდაპირი ანექსიით სრულად ჩამოიშლებოდა.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["ანაპის ციხის აშენება — კავკასიის თავდაცვითი ხაზი", "be92a80f"], "d": ["ქუჩუკ-ქაინარჯით ყირიმის ხელიდან გასვლისას კავკასიაში ოსმალური გავლენის შესანარჩუნებლად ყუბანის შესართავთან ახალი ციხის აშენება დაიწყეს. გენუური კოლონიის ნაშთებზე აგებული ანაპა თავისი ბაზრით, აბანოებითა და ორას ორმოცდაათზე მეტი დუქნით მალე ჩერქეზ ტომებთან კავშირის უზრუნველმყოფ ქალაქად იქცა. ციხე ორმოცდარვა წლის განმავლობაში კავკასიაში რუსეთის ჩამოსვლის წინააღმდეგ ოსმალთა ყველაზე მოწინავე ფორპოსტად დარჩა.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["დიდი ვეზირის ჰალილ ჰამიდ-ფაშას გადაყენება და სიკვდილით დასჯა", "c44001ca"], "d": ["რეფორმატორი დიდი ვეზირი ჰალილ ჰამიდ-ფაშა, რომლის სამსახურითაც აბდულჰამიდ I არაერთხელ გამოხატავდა კმაყოფილებას, 1785 წლის 31 მარტს, გამთენიისას, მოულოდნელად გადააყენეს, გალიპოლში გადაასახლეს და მთელი ქონება ჩამოართვეს. ჯერ მას ჰაბეშის ეიალეთი, ჯიდის სანჯაყი და მექის შეიხულჰარემობა მისცეს; 1785 წლის აპრილში, როცა ბოზჯაადაზე გზისთვის ემზადებოდა, ამ გამგებლობიდანაც გადააყენეს და გამოცემული სასიკვდილო ფირმანით ჯეზაირლი ღაზი ჰასან-ფაშას ერთ-ერთმა კაცმა, ყარაქეთხუდაზადე ალიმ მოკლა. მოკვეთილი თავი სტამბოლში გაგზავნეს და ორთაკაფიზე გამოფინეს. TDV-ის თანახმად, ეს მოულოდნელი დაცემა ზოგჯერ იმ ბრალდებით აიხსნება, თითქოს ის ფადიშაჰის ტახტიდან ჩამოგდებასა და მის ნაცვლად შეჰზადე სელიმის დასმას გეგმავდა, მაგრამ ნამდვილი მიზეზები, როგორც ჩანს, იყო აღშფოთება ყირიმის ანექსიაზე მისი დუმილის გამო, მისი რეფორმებით დაზარალებული წრეების მტრობა და ღაზი ჰასან-ფაშას წინააღმდეგობა.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["რუსეთისთვის ომის გამოცხადება — დაიწყო 1787-1792 წლების ოსმალეთ-რუსეთის ომი", "3bfb870c"], "d": ["ეკატერინე II-ის საზეიმო ყირიმული მოგზაურობისა და საქართველოს მის მფარველობაში აყვანის გამო დივანმა ანექსიის უკან დაბრუნების მიზნით ომის გადაწყვეტილება მიიღო და რუსი ელჩი კვლავ იედიკულეში ჩაკეტეს. თუმცა ჯარი მზად არ იყო, ხაზინა ცარიელი იყო და მოკავშირის ძიება უშედეგო აღმოჩნდა. ხუთი წლის განმავლობაში გაგრძელებული ომი ოჩაკოვის ხოცვა-ჟლეტით დაცემით, იზმაილის დაკარგვითა და იასის ზავის მძიმე პირობებით დასრულდებოდა.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["ავსტრიის ომში ჩართვა — ბრძოლა ორ ფრონტზე", "ae912290"], "d": ["რუსეთთან 1781 წელს დადებული საიდუმლო კავშირის თანახმად, ავსტრიის იმპერატორმა იოსებ II-მ ოსმალეთის სახელმწიფოს ომი გამოუცხადა და ბელგრადისა და ბოსნიის მიმართულებით დაიძრა. ოსმალური ჯარი ერთბაშად იძულებული გახდა ორ ფრონტზე ებრძოლა: ჩრდილოეთში რუსეთს, დასავლეთში ავსტრიას. ლაზარეთთან, მეჰადიასთან და შებეშთან ავსტრიელებზე მოპოვებული გამარჯვებების მიუხედავად, 1789 წელს ბელგრადის დაკარგვით დასავლეთის ფრონტიც ჩამოიშლებოდა.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["ოსმალეთ-პრუსიის კავშირი", "03b88e51"], "d": ["ტახტზე ასვლისთანავე ევროპაში მოკავშირის მძებნელმა სელიმ III-მ პრუსიასთან ურთიერთდახმარების გამთვალისწინებელი სამოკავშირეო ხელშეკრულება დადო; პრუსიამ რუსეთისა და ავსტრიისთვის ომის გამოცხადება, ოსმალეთის სახელმწიფომ კი ყირიმის დაბრუნებამდე ზავის არდადება იკისრა. ეს ოსმალეთის ისტორიაში ევროპულ სახელმწიფოსთან ხელმოწერილი პირველი ნამდვილი ურთიერთკავშირის ტექსტი იყო და აჩვენებდა, რომ კლასიკური შეხედულება „ურწმუნოებთან კავშირი არ შეიძლება“ მიტოვებული იყო. პრუსია ომში არ ჩაერთო, მაგრამ ავსტრია ზავზე აიძულა და სვიშტოვის ზავის გზა გაუხსნა.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["იზმაილის ციხის დაცემა და ხოცვა-ჟლეტა", "6a296b0c"], "d": ["დუნაის დელტის ყველაზე ძლიერ სიმაგრედ მიჩნეული იზმაილის ციხე გენერალ სუვოროვის მიერ მოწყობილი სისხლიანი საერთო იერიშით ერთ დღეში აიღეს; გარნიზონი და ქალაქის მოსახლეობა დიდწილად ხმლით ამოწყვიტეს. ევროპაში ფართო გამოძახილის მქონე ამ ხოცვა-ჟლეტამ ოსმალურ საზოგადოებაში ღრმა შოკი გამოიწვია და დუნაის თავდაცვითი ხაზის ხერხემალი გადატეხა. ციხე ერთი წლის შემდეგ იასის ზავით დაბრუნდებოდა, მაგრამ ომის ბედი უკვე დიდი ხნის გადაწყვეტილი იქნებოდა.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["სვიშტოვის ზავი — ავსტრიის ფრონტის დახურვა", "58741f1d"], "d": ["პრუსიის ზეწოლისა და იმის წყალობით, რომ საფრანგეთის რევოლუციამ ავსტრია დასავლეთში დაკავებული შეინარჩუნა, ორმა სახელმწიფომ ომამდელი საზღვრების საფუძველზე ზავს მიაღწია. ავსტრიამ მის მიერ ოკუპირებული ყველა ადგილი, ბელგრადის ჩათვლით, დააბრუნა; ოსმალეთის სახელმწიფომ მხოლოდ ხორვატიის საზღვარზე მცირე შესწორებები მიიღო. დასავლეთის ფრონტის ამ პირობებით დახურვამ ოსმალეთის სახელმწიფოს საშუალება მისცა, მთელი ძალა რუსეთის წინააღმდეგ შეეკრიბა და იასის ზავის დანაკარგი შეზღუდა. ხორვატიის საზღვრის ამ შესწორებებით ცეტინი (ცეტინგრადი) და დრეჟნიკ-გრადი ოსმალებიდან ჰაბსბურგებზე გადადის (TDV zistovi-antlasmasi; Korić 2016, n. 118, მე-4 მუხლი). ორშოვა (ძველი ორშოვა) კი ერთადერთი ადგილია, რომელიც არ დაბრუნებულა (Bánlaky 0019/1796); ატლასი სამართლებრივ გადაცემას ამ დღეს წერს (ფაქტობრივი ოკუპაცია 1790 წლის 16 აპრილს).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["იასის ზავი — ყირიმის საბოლოო დაკარგვა და დნესტრის საზღვარი", "a56fd194"], "d": ["ხუთწლიანი ომის ბოლოს ხელმოწერილი ზავით საზღვრად მდინარე დნესტრი (თურლა) აღიარეს; მდინარის მარცხენა ნაპირი რუსეთს, მარჯვენა კი ოსმალებს დარჩა, ოჩაკოვი და მისი შემოგარენი საბოლოოდ ხელიდან გავიდა. ოსმალეთის სახელმწიფომ ყირიმის დაბრუნების იმედზე სრულად აიღო ხელი და 1783 წლის ანექსია სამართლებრივად აღიარა; ვლახეთი და მოლდოვა ორწლიანი საგადასახადო შეღავათით დაბრუნდა. თორმეტი მილიონი ყურუშის საომარი კონტრიბუციის ვალდებულებაც მიიღეს და შავი ზღვის ჩრდილოეთი მუდმივად რუსეთს დაეთმო. იმავე თარიღს შემოერთებული სხვა ადგილები: იზმაილი.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["ორანის (ვაჰრანის) ესპანელების მიერ დაცლა და ალჟირისთვის გადაცემა", "9f95cee6"], "d": ["1790 წლის მიწისძვრით ციხე და ქალაქი დიდწილად დაინგრა და სამი საუკუნის განმავლობაში შენარჩუნებული ძვირადღირებული გარნიზონის ტარება აღარ შეეძლო ესპანეთს, ამიტომ ალჟირის ოჯაღთან შეთანხმებით ორანი და მერს-ელ-ქებირი უბრძოლველად გადასცა. ამგვარად, ჩრდილოეთ აფრიკის სანაპიროზე ევროპის უკანასკნელი პოზიციაც მოისპო. ოსმალური ალჟირი საფრანგეთის ოკუპაციამდე დარჩენილი ოცდათვრამეტი წლის განმავლობაში მთელ სანაპიროზე ბატონობდა.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["ფაზვანდოღლუ ოსმანის ფაქტობრივი მმართველობა ვიდინში", "0ce70361"], "d": ["ნიზამ-ი ჯედიდის რეგლამენტაციების წინააღმდეგ აჯანყებულმა ფაზვანდოღლუ ოსმანმა ვიდინის ვალი გააქცია, ქალაქი ხელში ჩაიგდო და დუნაის გასწვრივ ღრმა თხრილებით გაამაგრა. 1797 წელს, ძალაუფლების მწვერვალზე, ოთხმოც ათასამდე ძალა შეკრიბა და ნიკოპოლი, სვიშტოვი, რუსე, სოფია და ნიში თავის კონტროლქვეშ მოაქცია; თავს მეამბოხედ კი არა, რეფორმატორად წარმოაჩენდა. 1798-1799 წლებში ბაბიალის თვეების განმავლობაში გაგრძელებული ალყა უშედეგო აღმოჩნდა და იგი 1807 წელს გარდაცვალებამდე ჩრდილოეთ ბულგარეთში ნახევრად დამოუკიდებლად ბატონობდა.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["საიმპერატორო სახმელეთო საინჟინრო სკოლის (Mühendishâne-i Berrî-i Hümâyun) გახსნა", "e9a3a34b"], "d": ["ნიზამ-ი ჯედიდის ჯარისთვის არტილერისტი, საფორტიფიკაციო და კარტოგრაფი ოფიცრების აღსაზრდელად ხასქოიში სახმელეთო საინჟინრო სკოლა გაიხსნა; იგი 1773 წელს დაარსებული საზღვაო საინჟინრო სკოლის სახმელეთო ჯარში შესატყვისი იყო. პროგრამაში ასწავლიდნენ ალგებრას, გეომეტრიას, მექანიკას, ფორტიფიკაციასა და ბალისტიკას; ევროპული ენებიდან მათემატიკისა და საარტილერიო საქმის წიგნები თარგმნეს. თურქეთში თანამედროვე საინჟინრო განათლების ფესვად მიჩნეული ეს სკოლა დღევანდელი სტამბოლის ტექნიკური უნივერსიტეტის დასაწყისად ითვლება.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["საფრანგეთისთვის ომის გამოცხადება და კავშირი რუსეთთან და ინგლისთან", "80e95bd7"], "d": ["ნაპოლეონის მიერ ეგვიპტის ოკუპაციის გამო ოსმალეთის სახელმწიფომ საფრანგეთთან ორსაუკუნენახევრიანი ტრადიციული მეგობრობა დაარღვია და საფრანგეთს ომი გამოუცხადა. იმავე პროცესში თავის ისტორიაში პირველად რუსეთთან კავშირი შეკრა და რუსულ ფლოტს სრუტეებით ხმელთაშუა ზღვაში გასვლის ნება დართო; შემდეგ ინგლისთანაც დაიდო კავშირი. ამ კავშირების წყალობით იონიის კუნძულები ფრანგებს წაართვეს, მაგრამ სრუტეების უცხო ფლოტისთვის გახსნამ მომავალში ძვირად დასაჯდომი პრეცედენტი შექმნა.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["პრევეზის აღება ფრანგებისგან — ნიკოპოლისის ბრძოლა", "d8e5e892"], "d": ["1797 წელს ვენეციის რესპუბლიკის დაცემისას იონიის კუნძულები და ხმელეთზე პრევეზა, პარგა და ვონიცა საფრანგეთის ხელში გადავიდა. იანინის ვალი თეფედელენლი ალი-ფაშამ, საფრანგეთის მიერ ეგვიპტის ოკუპაციის გამო გაჩაღებული ომით ისარგებლა, პრევეზისკენ გაემართა და ქალაქის გარეთ, ნიკოპოლისის ნანგრევებთან, ფრანგულ გარნიზონს მძიმე მარცხი აგემა. ამგვარად, პოჟარევაცში ვენეციისთვის დატოვებული ეს ნავსადგური ოთხმოცი წლის შემდეგ ოსმალურ მმართველობაში შევიდა. ბუტრინტი (Butrinto) 25 ოქტომბერს დაეცა, როცა ფრანგულმა გარნიზონმა სიმაგრეები ააფეთქა და კორფუზე დაიხია (Curlin, Preveza B, 2010; ატლასი დღეს პრევეზიდან იღებს), და ოსმალურ მმართველობაში შევიდა.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["აკრის თავდაცვა — ნაპოლეონის მოგერიება", "56b5c45b"], "d": ["ეგვიპტიდან სირიისკენ მიმავალმა ნაპოლეონმა აკრს ალყა შემოარტყა და ორი თვის განმავლობაში ერთმანეთის მიყოლებით იერიშები მოაწყო; ქალაქს ჯეზარ აჰმედ-ფაშა ინგლისური ფლოტის მხარდაჭერითა და სტამბოლიდან გაგზავნილი ნიზამ-ი ჯედიდის ნაწილებით იცავდა. ალყის მოხსნითა და ეგვიპტეში უკან დახევაზე იძულებულმა ნაპოლეონმა აღმოსავლეთისკენ გაფართოების ოცნება ამ გალავნის წინ დამარხა. ცნობა სტამბოლში დიდი სიხარულით მიიღეს და ის ახლად შექმნილი გაწვრთნილი ჯარის მიერ პირველი სერიოზული გამოცდის ჩაბარების მტკიცებულებად ჩაითვალა.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["ვაჰაბიტების თავდასხმა ქერბალაზე", "522341ed"], "d": ["ნეჯდიდან დაძრული ვაჰაბიტური ძალები ქერბალაში შეიჭრნენ, ქალაქი გაძარცვეს, ჰაზრათ ჰუსეინის აკლდამა დააზიანეს და სამი ათასზე მეტი ადამიანი მოკლეს. ოსმალეთის სახელმწიფოს ერაყელმა ქოლემენმა მმართველებმა თავდასხმა ვერ აღკვეთეს; მოვლენამ დიდი რეაქცია გამოიწვია როგორც ირანში, ისე სტამბოლში. ეს თავდასხმა იმის გამოცხადება იყო, რომ საუდის მოძრაობა ოაზისის საამირო აღარ იყო და ოსმალეთის წმინდა ქალაქებისთვის მუქარის შემცველ რეგიონულ ძალად გადაქცეულიყო.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["ქართლ-კახეთი (აღმოსავლეთ საქართველო) რუსეთს შეუერთეს ანექსიით", "3b650c5e"], "d": ["1783 წელს რუსეთის მფარველობის მიმღები და 1795 წელს ირანის დამანგრეველი ლაშქრობით დაზარალებული ქართლ-კახეთის სამეფო გაუქმდა; 1801 წლის 12 სექტემბრის ბრძანებულებით ის რუსეთის პროვინციად გამოცხადდა და რუსული მმართველობის სისტემის დანერგვა დაიწყო. საქართველომ ამ დროიდან დამოუკიდებლობა დაკარგა; რამდენიმე წელში რუსეთის ბატონობის ქვეშ მოექცა სამეგრელოც (1803), იმერეთი და გურიაც (1804), და რუსეთი ოსმალეთის კავკასიურ საზღვარს მიადგა. ამ მოვლენით გორი, დუშეთი (ქართლი) და თელავი (კახეთი) რუსეთს გადაეცა.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["ეგვიპტის ფრანგებისგან დაცლა", "00cfdc8c"], "d": ["ოსმალური და ინგლისური ძალების ხმელეთიდან და ზღვიდან ერთობლივი ოპერაციის შედეგად ჯერ კაირო, შემდეგ კი ალექსანდრია ჩაიბარეს და ფრანგული ძალები ხომალდებით სამშობლოში გაგზავნეს. სამწლიანი ოკუპაციის დასრულებისას ეგვიპტე ქაღალდზე ოსმალურ მმართველობას დაუბრუნდა, მაგრამ ქოლემენ ბეებსა და ალბანურ ნაწილებს შორის ბატონობისთვის ბრძოლამ ქვეყანა ქაოსში ჩააგდო. ეს ვაკუუმი რამდენიმე წელიწადში ქავალალი მეჰმედ ალის აღზევებისთვის ნიადაგს მოამზადებდა.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["პარიზის ზავი — საფრანგეთთან მშვიდობის აღდგენა", "1b76991f"], "d": ["ეგვიპტის დაცლის შემდეგ ხელმოწერილი ზავით ოსმალეთის სახელმწიფოსა და საფრანგეთს შორის საომარი მდგომარეობა ოფიციალურად დასრულდა და ძველი კაპიტულაციები განახლდა. ფრანგულ სავაჭრო ხომალდებს შავ ზღვაში შესვლის ნება დართეს; სანაცვლოდ საფრანგეთმა ოსმალეთის ტერიტორიული მთლიანობა აღიარა. მშვიდობის დამყარებამ სელიმ III-ის რუსეთისა და ინგლისის გვერდით შევიწროებულ საგარეო პოლიტიკას კვლავ მანევრის სივრცე დაუბრუნა.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["ვაჰაბიტების მიერ ტაიფის აღება", "7b791359"], "d": ["საუდ ბ. აბდულაზიზის სარდლობით ვაჰაბიტურმა ძალებმა ჰიჯაზისკენ მიმართულ პირველ ნაბიჯზე ტაიფს ალყა შემოარტყეს და გაძარცვეს; ქალაქი წმინდა მიწებისკენ გახსნილი პირველი კარის სახით დაეცა. ორი წმინდა ქალაქის მფარველის წოდების მატარებელი ოსმალო ფადიშაჰისთვის ეს მმართველობის ლეგიტიმურობის პირდაპირ შემრყევი დარტყმა იყო. ორთვენახევრის შემდეგ იგივე ჯარი მექაზე გაილაშქრებდა.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["ვაჰაბიტების მიერ მექის პირველად აღება", "21157c05"], "d": ["ტაიფის დაცემიდან ორთვენახევრის შემდეგ ვაჰაბიტური ძალები მექაში შევიდნენ, აკლდამები დაანგრიეს და თავიანთი შეხედულების მიხედვით წესრიგი დაამყარეს; შარიფი ღალიბი იძულებული გახდა ჯიდაში უკან დაეხია. ჰაჯის გზების ჩაკეტვამ მთელ ისლამურ სამყაროში გამოძახილი ჰპოვა და სტამბოლი იძულებული გახდა ეგვიპტის ვალი მეჰმედ ალის სამხედრო დახმარება ეთხოვა. ეს პირველი ბატონობა მხოლოდ სამ თვეს გაგრძელდებოდა.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["შარიფ ღალიბის მიერ მექის დაბრუნება", "83d08dff"], "d": ["ჯიდაში უკან დახეულმა შარიფმა ღალიბმა შეკრებილი ძალებით მექას ალყა შემოარტყა და ოცდახუთდღიანი ალყის შემდეგ ქალაქი ვაჰაბიტებს წაართვა; ოსმალთა სახელით ხუტბა კვლავ წაიკითხეს. ეს მეორე ბატონობაც მუდმივი არ იქნებოდა: საუდის ძალები 1806 წელს ქალაქს ხელახლა აიღებდნენ.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["სერბთა პირველი აჯანყების დაწყება", "0f6e8767"], "d": ["ბელგრადში მმართველობის ხელში ჩამგდები მეამბოხე იანიჩარი დაჰების მიერ სერბი წარჩინებულების მასობრივი ხოცვის გამო, ყარა გიორგის (კარაგეორგის) ხელმძღვანელობით შეიარაღებული წინააღმდეგობა დაიწყო. თავდაპირველად ფადიშაჰის ერთგული და მხოლოდ დაჰების წინააღმდეგ მიმართული მოძრაობა მალე ავტონომიისა და დამოუკიდებლობის მომთხოვნ ეროვნულ აჯანყებად გადაიქცა. სერბულმა ძალებმა 1806 წელს ბელგრადი აიღეს; ეს აჯანყება ბალკანეთში ნაციონალისტური დამოუკიდებლობის მოძრაობების პირველი რგოლი გახდა.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["ვაჰაბიტების მიერ მედინის ოკუპაცია", "84e310d7"], "d": ["მექის შემდეგ მედინაც ვაჰაბიტური ძალების ხელში გადავიდა; რაუდა-ი მუთაჰარას ხაზინა გაანაწილეს და ქალაქში გუმბათიანი აკლდამები დაანგრიეს. ამგვარად, ორივე წმინდა ქალაქი ერთად გამოვიდა ოსმალური კონტროლიდან და დამასკოდან და ეგვიპტიდან მომავალი ჰაჯის ქარავნები წლების განმავლობაში გზას ვეღარ გაუდგნენ. მედინის დაბრუნება მხოლოდ შვიდი წლის შემდეგ, 1812 წელს, მეჰმედ ალი-ფაშას ვაჟის, თოსუნ-ფაშას სარდლობით ეგვიპტურმა ჯარმა შეძლო.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["რუსეთთან ომის დაწყება (1806-1812 წლების ოსმალეთ-რუსეთის ომი) და სრუტეების ჩაკეტვა", "ea170804"], "d": ["ნაპოლეონის აუსტერლიცის გამარჯვების შემდეგ საფრანგეთთან დაახლოებულმა სელიმ III-მ რუსეთის ზეწოლის მიუხედავად ვლახეთისა და მოლდოვის ვოევოდები გადააყენა; ამის გამო რუსულმა ჯარებმა ორივე სამთავრო დაიკავეს და ომი დაიწყო. ოსმალეთის სახელმწიფომ სრუტეები რუსული ფლოტისთვის ჩაკეტა; სანაცვლოდ ინგლისმაც რუსეთის მხარე დაიჭირა და სტამბოლში ესკადრა გაგზავნა. ექვსი წლის განმავლობაში გაგრძელებული ეს ომი, ყაბაქჩის აჯანყებასა და სელიმ III-ის ტახტიდან ჩამოგდებასთან გადაჯაჭვული, 1812 წლის ბუქარესტის ზავით ბესარაბიის დაკარგვით დასრულდებოდა.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["ინგლისური ფლოტის სტამბოლის მისადგომებთან მისვლა (დაკუორთის ოპერაცია)", "195bb58f"], "d": ["ოსმალეთის სახელმწიფოსთვის საფრანგეთთან კავშირის გაწყვეტის ძალდატანების მსურველმა ინგლისმა ადმირალ დაკუორთის სარდლობით ესკადრა დარდანელის გავლით გაატარა და სტამბოლის მისადგომებთან ღუზა ჩააშვებინა. ფრანგი ელჩის სებასტიანის წარმართვით სტამბოლის მოსახლეობა მობილიზებული გახდა, სანაპირო ბატარეები რამდენიმე დღეში გააძლიერეს და ქალაქის ზარბაზნებით დაბომბვის გარეშე ესკადრა იძულებული გახდა უკან დაეხია; დაბრუნებისას დარდანელში მძიმე დანაკარგი განიცადა. დედაქალაქის უცხო ფლოტის მიერ პირველად ასე ახლოდან დამუქრებამ სრუტეების საკითხი ევროპული დიპლომატიის ცენტრში მოაქცია.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["მუსტაფა IV-ის დახრჩობით მოკვლა", "eeb75c20"], "d": ["ალემდარ მუსტაფა-ფაშაზე თავდასხმისა და მისი დაღუპვის შემდეგ, როცა აჯანყებულებმა სასახლეზე მსვლელობა მოინდომეს, ტახტიდან ჩამოგდებული მუსტაფა IV მისი ძმის, მაჰმუდ II-ის ბრძანებით დაახრჩვეს. ცხედარი ბაჰჩეკაფიში, მამის, აბდულჰამიდ I-ის, აკლდამაში დაკრძალეს; აჯანყებულებს შორის ჭორი გავრცელდა, რომ კუბო ცარიელი იყო.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["ყალა-ი სულთანიეს ზავი — მშვიდობა ინგლისთან და სრუტეების წესი", "fe282117"], "d": ["დაკუორთის ოპერაციის მარცხის შემდეგ ინგლისთან ხელმოწერილი ზავით ორ სახელმწიფოს შორის ომი დასრულდა და ინგლისელ ვაჭრებს ძველი პრივილეგიები დაუბრუნდა. ტექსტში შეტანილმა დებულებამ, რომელსაც „ძველ წესს“ უწოდებენ, დააფიქსირა, რომ მშვიდობის დროს არც ერთი უცხო საბრძოლო ხომალდი სრუტეებს ვერ გაივლის. ეს პრინციპი XIX საუკუნის განმავლობაში სრუტეების რეჟიმის ჩამომყალიბებელი ყველა საერთაშორისო რეგულაციის სამართლებრივი საფუძველი გახდა.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["სლობოძიის მარცხი — დუნაის ჯარის ალყაში მოქცევა", "54b60fd1"], "d": ["რუსეს მისადგომებთან დუნაის გადამლახველი ოსმალური ჯარის დიდი ნაწილი კუტუზოვის მიერ მდინარის მოპირდაპირე ნაპირიდან განხორციელებული ალყის მანევრით სლობოძიასთან მოიმწყვდია და შიმშილისთვის განწირა. ათასობით ჯარისკაცი იძულებული გახდა დანებებულიყო; დიდი ვეზირის ხელში არსებული ძალა ფაქტობრივად დადნა და ბაბიალი ერთი თვის შემდეგ ზავის თხოვნაზე იძულებული გახდა. ეს მარცხი პირდაპირი მიზეზია იმისა, რომ 1812 წლის ბუქარესტის ზავში ბესარაბიის დათმობას დათანხმდნენ.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["ბელგრადის დაბრუნება და სერბთა პირველი აჯანყების ჩახშობა", "06f56f52"], "d": ["ბუქარესტის ზავით რუსულ მხარდაჭერას მოკლებულმა სერბმა მეამბოხეებმა ბოსნიიდან და რუმელიიდან მოსული ძალების ერთობლივ ოპერაციას ვერ გაუძლეს; ხურშიდ აჰმედ-ფაშა ბელგრადში შევიდა და ცხრაწლიანი აჯანყება სრულად ჩაახშეს. ყარა გიორგი ავსტრიაში გაიქცა, სმედერევოს სანჯაყი კვლავ პირდაპირ ოსმალურ მმართველობაზე მიაბეს. თუმცა გატარებული მკაცრი ზომები ორი წლის შემდეგ მილოშ ობრენოვიჩის ხელმძღვანელობით მეორე და მდგრად აჯანყებას გამოიწვევდა.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["სერბთა მეორე აჯანყება და მილოშ ობრენოვიჩის უმაღლესი კნეზობა", "e6e82ad2"], "d": ["პირველი აჯანყების ჩახშობის შემდეგ გატარებული მძიმე ზომების წინააღმდეგ მილოშ ობრენოვიჩის ხელმძღვანელობით ახალი აჯანყება იფეთქა; ამჯერად ბაბიალიმ ძალის ნაცვლად შეთანხმება ამჯობინა. დადებული შეთანხმებით მილოში „უმაღლეს კნეზად“ აღიარეს და გადასახადების აკრეფისა და შიდა საქმეების წარმართვის უფლებამოსილება სერბ კნეზებს დაუტოვეს. ფაქტობრივი ავტონომიის ეს პირველი ბირთვი 1830 წლის ფირმანისა და 1878 წლის დამოუკიდებლობისკენ მიმავალი პროცესის ამოსავალი წერტილი გახდა.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["ვლახეთის აჯანყება — იფსილანტის პრუთის გადალახვა და ვლადიმირესკუს აჯანყება", "67d46a98"], "d": ["რუსული ჯარის გენერალმა ალექსანდრე იფსილანტიმ ფილიკი ეტერიას სახელით პრუთი გადალახა და ვლახეთსა და მოლდოვაში ბერძენთა საერთო აჯანყების დაწყება სცადა; იმავე დღეებში ტუდორ ვლადიმირესკუმაც ადგილობრივი გლეხები აამოქმედა. ორი მოძრაობა ვერ გაერთიანდა: ვლადიმირესკუმ იფსილანტის თურქების წინააღმდეგ ერთად ბრძოლის მოწოდებას უპასუხა „მე თურქების კი არა, ბერძნების წინააღმდეგ ავჯანყდი“, და მალე იფსილანტის ხალხმა მოკლა. აჯანყება ოსმალურმა ძალებმა მაისში ჩაახშეს, მაგრამ ფანარიოტთა ვოევოდობის წესრიგი დასრულდა და აჯანყების ცეცხლი მორეაზე გადავარდა.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["საუდის მეორე სახელმწიფოს დაარსება ერ-რიადში", "34dad3bd"], "d": ["1818 წელს დირიას დაცემისა და საუდის პირველი სახელმწიფოს ნგრევიდან ექვსი წლის შემდეგ თურქი ბ. აბდულაჰმა ეგვიპტური გარნიზონები ნეჯდიდან განდევნა და ერ-რიადის ცენტრის მქონე ახალი საუდის საამირო დააარსა. ახალმა სტრუქტურამ ჰიჯაზისკენ გაფართოებას მოერიდა, ნეჯდში დარჩენა ამჯობინა და ოსმალურ-ეგვიპტურ ძალებთან პირდაპირი შეტაკებისგან შორს იდგა. ეს მეორე სახელმწიფო საუკუნის ბოლომდე გაგრძელდებოდა და დღევანდელი საუდის არაბეთის დაარსებამდე მიმავალი ჯაჭვის მეორე რგოლს შეადგენდა. იმავე თარიღს ხელიდან გასული სხვა დასახლებები: დირია (ნეჯდი).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["აკერმანის ზავი — დათმობები სერბეთისა და სამთავროებისთვის", "c75f15d0"], "d": ["იანიჩართა კორპუსის გაუქმებისთანავე ჯარის გარეშე დარჩენილი ოსმალეთის სახელმწიფო რუსეთის ულტიმატუმის წინაშე იძულებული გახდა მძიმე პირობების მქონე ზავი მიეღო. სერბეთისთვის დაპირებული ავტონომია დადასტურდა, აღიარეს, რომ ვლახეთისა და მოლდოვის ვოევოდები რუსეთის თანხმობის გარეშე ვერ გადაყენდებოდნენ, ხოლო რუსულ სავაჭრო ხომალდებს სრუტეებში სრული თავისუფლება მიენიჭათ. როცა ბაბიალიმ ორი წლის შემდეგ საბერძნეთის საკითხის გამო ზავის აღიარებაზე უარი განაცხადა, რუსეთმა ეს ომის საბაბად ჩათვალა.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["თიმარის სისტემის ლიკვიდაცია", "84d5d1d6"], "d": ["იანიჩართა კორპუსის გაუქმებიდან ერთი წლის შემდეგ რუმელიისა და ანატოლიის ორმოცდაცამეტ სანჯაყში მყოფი დაახლოებით 5.200 თიმარიანი სიპაჰი, თიმარის შემოსავლებთან ერთად, ასაქირ-ი მანსურეს ცხენოსნებად გადააქციეს. ამგვარად, ოსმალური მიწის, გადასახადისა და ჯარის წესრიგის ოთხსაუკუნოვანი ხერხემალი, თიმარის რეჟიმი, ფაქტობრივად დასრულდა. გამოთავისუფლებული თიმარები ხაზინას გადაეცა და ცენტრალიზებულ ხელფასიან ჯარსა და ფულად საგადასახადო სისტემაზე გადასვლის გზა გაიხსნა.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["საიმპერატორო სამედიცინო სკოლის (Tıphâne-i Âmire) დაარსება — თანამედროვე სამედიცინო განათლების დასაწყისი", "ac3e57c0"], "d": ["ახლად შექმნილი ასაქირ-ი მანსურეს ჯარისთვის ექიმებისა და ქირურგების აღსაზრდელად მთავარი ექიმის მუსტაფა ბეჰჯეთ ეფენდის წინადადებით შეჰზადებაშიში საიმპერატორო სამედიცინო სკოლა გაიხსნა. გაკვეთილები ევროპული სასწავლო პროგრამის მიხედვით მოეწყო და სწავლება თავდაპირველად ფრანგულად მიმდინარეობდა; რამდენიმე წლის შემდეგ საქირურგიო სკოლაც (Cerrahhâne-i Âmire) დაარსდა და ორივე დაწესებულება გაერთიანდა. თურქეთში თანამედროვე სამედიცინო სწავლების დასაწყისად მიჩნეული ეს სკოლა დღევანდელი სტამბოლის სამედიცინო ფაკულტეტის სათავედ ითვლება.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828-1829 წლების ოსმალეთ-რუსეთის ომის დაწყება", "9dff4e05"], "d": ["ნავარინოსთან ფლოტის დაწვისა და ბაბიალის მიერ აკერმანის ზავის არაღიარების გამოცხადების შემდეგ რუსეთმა ორ ფრონტზე ერთდროულად დაიწყო ომი. რადგან იანიჩართა კორპუსი ახლახან გაუქმებული იყო, ახალი ჯარი კი ჯერ ჩამოყალიბების ეტაპზე იმყოფებოდა, ოსმალური თავდაცვა თავიდანვე სუსტი იყო; რუსებმა დუნაის გადალახვისას აღმოსავლეთში ყარსი და ახალციხე აიღეს. ერთი წლის განმავლობაში ედირნემდე წინ წასული რუსული ჯარი 1829 წლის ედირნეს ზავის მძიმე პირობებსა და საბერძნეთის დამოუკიდებლობას თავს მოახვევდა.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["პირველი ხელშეკრულება ამერიკის შეერთებულ შტატებთან", "d737516f"], "d": ["წლების განმავლობაში გაგრძელებული კონტაქტების შემდეგ ხელმოწერილი სავაჭრო და ნაოსნობის ხელშეკრულებით აშშ-მა ოსმალეთის ქვეყანაში უმაღლესი ხელშეწყობის ერის სტატუსი და სრუტეებში სავაჭრო გავლის უფლება მოიპოვა. ცალკე საიდუმლო მუხლი ითვალისწინებდა, რომ ოსმალეთს, სურვილისამებრ, ამერიკულ გემთსაშენებში ხომალდების აშენება და მზა ხომალდებისა და ხე-ტყის შეძენა შეეძლებოდა; აშშ-ის სენატმა ხელშეკრულება დაამტკიცა, მაგრამ ეს საიდუმლო მუხლი 27 ხმით 18-ის წინააღმდეგ უარყო. ხომალდების გზა მაინც არ ჩაიკეტა: ჰენრი ეკფორდმა 1831 წელს ჩამოყვანილი ხომალდი ოსმალებს მიჰყიდა, აინალიყავაქში მომუშავე ამერიკელმა ოსტატებმა კი ფლოტს ახალი ტიპის ხომალდები შესძინეს. ეს ხელშეკრულება ოსმალეთის სახელმწიფოს მიერ ევროპის გარეთ მდებარე სახელმწიფოსთან დამყარებული პირველი ყოვლისმომცველი ურთიერთობის დოკუმენტი გახდა.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["ბაღდადში ქოლემენების მმართველობის ბოლოს მოღება", "7e1d38a3"], "d": ["ცენტრალიზაციის პოლიტიკის გამტარებელმა მაჰმუდ II-მ ბაღდადის ვალი დაუდ-ფაშა, რომელიც მოთხოვნილ ფულს არ აგზავნიდა და ცენტრიდან ჩასული მოხელე მოაკვლევინა, მეამბოხედ გამოაცხადა. ალი რიზა-ფაშას სარდლობით ძალამ ოთხმოცდაათდღიანი ალყის შემდეგ ქალაქი აიღო და ქოლემენები თითქმის მთლიანად მოსპეს. ამგვარად, 1704 წლიდან მიმდინარე ნახევრად დამოუკიდებელი ქოლემენური მმართველობა დასრულდა და ერაყი კვლავ პირდაპირ ცენტრზე მიაბეს.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["სამხედრო სასწავლებლის (Mekteb-i Harbiye) დაარსება მაჩქას ყაზარმაში", "bf31c7d9"], "d": ["ასაქირ-ი მანსურე-ი მუჰამადიესთვის ევროპული წესით აღზრდილი ოფიცრების უზრუნველსაყოფად მაჩქას ყაზარმაში სამხედრო მეცნიერებათა სასწავლებელი გაიხსნა. სტუდენტებს ასწავლიდნენ მათემატიკას, კარტოგრაფიას, ფორტიფიკაციასა და უცხო ენას; მალე ვენასა და პარიზში სტუდენტების გაგზავნით კადრები გააძლიერეს. ეს სასწავლებელი ოსმალურ ჯარში სწავლამიღებული ოფიცრის ტრადიციისა და, შესაბამისად, XIX საუკუნის ბოლოს გაჩენილი ახალი სამხედრო-ინტელიგენტი თაობის დაბადების ადგილი გახდა.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["ტრიპოლის (ლიბია) ცენტრზე პირდაპირ მიბმა — ყარამანლის დინასტიის დასასრული", "faabcb96"], "d": ["ყარამანლის ოჯახის შიდა ტახტისთვის ბრძოლებისა და 1830 წელს საფრანგეთის მიერ ალჟირის ოკუპაციის შემდეგ გაზრდილი ევროპული ზეწოლის გამო ბაბიალი ტრიპოლში პირდაპირ ჩაერია. სტამბოლიდან გაგზავნილი ფლოტი ქალაქში შევიდა, უკანასკნელი ყარამანლი ბეი გადააყენეს და სტამბოლში ჩაიყვანეს, ეიალეთი კი ცენტრიდან დანიშნულ ვალის ჩააბარეს. 124-წლიანი დინასტიის ეპოქის დასრულებისას განმტკიცდა ჩრდილოეთ აფრიკაში ოსმალეთის სახელმწიფოს მიერ პირდაპირ მართული უკანასკნელი ტერიტორია.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["დეფთერდარობის გაუქმება და ფინანსთა სამინისტროს დაარსება", "89f8125e"], "d": ["კლასიკური ოსმალური ფინანსური წესრიგის სათავე, დეფთერდარის თანამდებობა, გაუქმდა და ევროპულ ყაიდაზე სამინისტრო — ფინანსთა სამინისტრო — დაარსდა; დაქსაქსული ხაზინები ერთ ხელში თავმოიყარა. იმავე წელს ბაბიალის სხვა განყოფილებებიც სამინისტროს სახელით ხელახლა მოეწყო და თანამედროვე მინისტრთა საბჭოს სტრუქტურაზე გადავიდნენ. ეს რეგულაცია იყო ერთ-ერთი უმნიშვნელოვანესი ნაბიჯი, რომელმაც ერთი წლის შემდეგ გამოსაცხადებელი თანზიმათის ფირმანის ადმინისტრაციული ინფრასტრუქტურა მოამზადა.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["ინგლისელების დამკვიდრება ადენში", "ddbd556b"], "d": ["ინგლისმა, 1802 წელს ლეჰიჯის სულთან აჰმად ბ. აბდ ალ-ქარიმთან დადებულ სავაჭრო-სამეგობრო შეთანხმებაზე დაყრდნობით, ადენის ნავსადგურში ჯარი გადასხა და ქალაქი თავის კონტროლქვეშ მოაქცია. წითელი ზღვის შესასვლელის მაკონტროლებელი ეს ნავსადგური, ინდოეთის გზის ქვანახშირის მომარაგების ბაზის სახით, ინგლისური იმპერიული სტრატეგიის საკვანძო წერტილად იქცა. მიუხედავად იმისა, რომ ოსმალეთის სახელმწიფოს პრეტენზია იემენზე ქაღალდზე გაგრძელდა, სამხრეთ სანაპიროზე მისი ფაქტობრივი ბატონობა ამ თარიღის შემდეგ აღარასოდეს დაბრუნებულა.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["დაბრუნება თიჰამას სანაპიროზე: ჰუდაიდას, ზებიდისა და მოხას აღება", "353982d2"], "d": ["1840 წელს ეგვიპტური ჯარის გასვლის შემდეგ უპატრონოდ დარჩენილ იემენის სანაპიროზე მექის შარიფის ზედამხედველობით თევფიქ-ფაშას სარდლობით ძალები გადმოსხდნენ და ჰუდაიდას, ზებიდისა და მოხას ნავსადგურები ოსმალურ მმართველობაზე მიაბეს. მიუხედავად იმისა, რომ სანაამდე წინსვლა სურდათ, მოსახლეობის წინააღმდეგობის გამო ჰუდაიდაში დაბრუნდნენ; ამგვარად, მთიანეთი ზეიდიტ იმამებს დარჩა და ოსმალთა ბატონობა ოცდასამი წელი მხოლოდ თიჰამას ზოლში გაგრძელდა. შიდა იემენი მხოლოდ 1872 წელს აჰმედ მუხთარ-ფაშას ლაშქრობით დაბრუნდებოდა.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["ბალტა-ლიმანის კონვენცია: ოსმალეთ-რუსეთის ერთობლივი მფარველობა ვლახეთსა და მოლდოვაში", "d3bb22e9"], "d": ["1848 წლის რევოლუციების ვლახეთსა და მოლდოვაზე გადავარდნის გამო ოსმალურმა და რუსულმა ძალებმა სამთავროები ერთად დაიკავეს. ბალტა-ლიმანში ხელმოწერილი კონვენციით გადაწყდა, რომ ვოევოდები არა არჩევით, არამედ ფადიშაჰის მიერ შვიდი წლით დაინიშნებოდნენ და ორი სახელმწიფო მხარეში ერთობლივ კონტროლს დაამყარებდა. შეთანხმებამ, ოსმალთა ქაღალდზე არსებული სუვერენიტეტის შენარჩუნებით, რუსეთს ფაქტობრივი პარტნიორობის უფლება აღუარა და დუნაის სამთავროების ოსმალეთისგან მოწყვეტა დააჩქარა.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["უნგრელ ლტოლვილთა საკითხი: კოშუტისა და მისი მეგობრების ოსმალეთისთვის შეფარება", "1c7d7ef4"], "d": ["1848-1849 წლების უნგრეთის რევოლუციის რუსულ-ავსტრიული ინტერვენციით ჩახშობის გამო ლაიოშ კოშუტმა და ათასობით უნგრელმა და პოლონელმა ლტოლვილმა ოსმალეთის მიწებს შეაფარა თავი. ავსტრიამ და რუსეთმა ლტოლვილების გადაცემა მკაცრად მოითხოვეს; ბაბიალიმ ინგლისისა და საფრანგეთის მხარდაჭერით გადაცემაზე უარი თქვა და ჯგუფი ქუთაჰიაში დაასახლა. კოშუტის წრე აქ დაახლოებით თვრამეტი თვე დარჩა; ასობით ლტოლვილი გამუსლიმდა და ოსმალთა სამსახურში შევიდა. მოვლენა ევროპულ საზოგადოებრივ აზრში თანზიმათის ოსმალეთის რეპუტაციის ამამაღლებელ იშვიათ დიპლომატიურ გამარჯვებად ჩაითვალა.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["ენჯუმენ-ი დანიშის დაარსება: პირველი ოსმალური აკადემია სტამბოლში", "6fda1365"], "d": ["განათლების საყოველთაო საბჭოს გადაწყვეტილებით დაარსებული ენჯუმენ-ი დანიში თურქულ ენაზე სამეცნიერო და სასწავლო წიგნების მოსამზადებლად შექმნილი პირველი ოსმალური სამეცნიერო აკადემიაა. 1851 წლის 18 ივლისს დარულმაარიფის შენობაში ცერემონიით გაიხსნა; მის ადგილობრივ და უცხოელ წევრებს შორის აჰმედ ჯევდეთ-ფაშაც იყო. მიუხედავად ხანმოკლე არსებობისა, ჯევდეთ-ფაშას „თარიხი“ და „ყავაიდ-ი ოსმანიე“ ამ დაწესებულების პროდუქტი გახდა და თურქული ენის სამეცნიერო ენად ჩამოყალიბების ქვაკუთხედად ჩაითვალა.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["ოლტენიცის გამარჯვება: პირველი ოსმალური წარმატება დუნაის ფრონტზე", "a660ad2f"], "d": ["ყირიმის ომის საწყის ეტაპზე სერდარ-ი ექრემმა ომერ ლუთფი-ფაშამ დუნაი გადალახა და ოლტენიცასთან რუსული ძალები მძიმე დანაკარგებით უკუაგდო. გამარჯვებამ ომის დასაწყისშივე რუსთა წინსვლა შეაჩერა და ევროპას აჩვენა თანზიმათის შემდგომი წვრთნით ოსმალური ჯარის მიერ მოპოვებული ძალა. ამ წარმატებამ მოამზადა ფსიქოლოგიური ნიადაგი, რომელმაც გააადვილა ინგლისისა და საფრანგეთის გადაწყვეტილება ოსმალთა მხარეს ომში ჩართვის შესახებ.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["ინგლისსა და საფრანგეთთან სამოკავშირეო ხელშეკრულება სტამბოლში", "04809278"], "d": ["ყირიმის ომში რუსეთის წინააღმდეგ ოსმალეთის სახელმწიფოსა და ინგლისსა და საფრანგეთს შორის ხელმოწერილმა სამოკავშირეო ხელშეკრულებამ დაადგინა, რომ სამი სახელმწიფო ერთობლივ ოპერაციებს აწარმოებდა და მოკავშირეები ომის დასრულებამდე ცალკე ზავს არ დადებდნენ. ამგვარად, ოსმალეთის სახელმწიფო თავის ისტორიაში პირველად ევროპის დიდ სახელმწიფოებთან თანასწორი მხარის სტატუსით შევიდა სამხედრო კავშირში. ამ ხელშეკრულებამ ორი წლის შემდეგ პარიზში ოსმალეთის ევროპულ სახელმწიფოთა სისტემაში ოფიციალურად მიღების სამართლებრივი საფუძველიც შექმნა.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["სტამბოლის ქალაქის მმართველობის (Şehremaneti) დაარსება: პირველი თანამედროვე მუნიციპალური ორგანიზაცია", "be4af27f"], "d": ["ყირიმის ომის დროს სტამბოლში თავმოყრილმა მოკავშირე ჯარისკაცებმა და გაზრდილმა მოსახლეობამ გამოწვეული ინფრასტრუქტურული კრიზისი გამოააშკარავა ყადიზე დამყარებული კლასიკური ქალაქის მმართველობის არასაკმარისობა. ევროპული ნიმუშების მიხედვით დაარსებული ქალაქის მმართველობით სისუფთავის, ფასების დადგენის, ბაზრის კონტროლისა და მშენებლობის საქმეები ერთ ხელში თავმოიყარა; მომდევნო წელს ბეიოღლუ-გალათაში საპილოტე ზონად მეექვსე მუნიციპალური ოლქი შეიქმნა. ეს ნაბიჯი ოსმალეთში თანამედროვე მუნიციპალური მმართველობის დასაწყისად ითვლება.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["პარიზის ზავი: ყირიმის ომის დასასრული და ოსმალეთის ევროპულ სახელმწიფოთა სისტემაში მიღება", "4aee0e2a"], "d": ["ყირიმის ომის დამსრულებელი პარიზის ზავით ოსმალეთის სახელმწიფო ევროპული სახელმწიფოთაშორისი სამართლის თანასწორ წევრად გამოცხადდა და მისი ტერიტორიული მთლიანობა დიდი სახელმწიფოების საერთო გარანტიის ქვეშ მოექცა. შავი ზღვა ნეიტრალიზებული გახდა, რუსეთის მიერ ქუჩუკ-ქაინარჯიდან მოპოვებული მართლმადიდებელ ქვეშევრდომებზე მფარველობის პრეტენზია ძალადაკარგული გახდა, ხოლო ბესარაბიის სამხრეთი (ქილიის, კაჰულის, იზმაილისა და ბოლგრადის კაზები) მოლდოვას გადაეცა. თუმცა იგივე ზავმა ისლაჰათის (რეფორმების) ფირმანი საერთაშორისო ვალდებულებად აქცია და შიდა საქმეებში ჩარევის კარიც შეაღო.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["დოლმაბაჰჩეს სასახლის გახსნა: მმართველობის ცენტრის გადატანა თოფქაფიდან", "71ad26d0"], "d": ["აბდულმეჯიდის მიერ 1842 წელს ბალიანების ოჯახისთვის შეკვეთილი სასახლე თოთხმეტწლიანი მშენებლობის შემდეგ გაიხსნა და სახელმწიფოს მმართველობის ცენტრი ოთხსაუკუნოვანი თოფქაფიდან სრუტის ნაპირას გადავიდა. ევროპული სტილით, ბროლის კიბითა და საზეიმო მილოცვის დარბაზით სასახლე თანზიმათის დასავლური ყაიდით განვითარების პრეტენზიის ქვაში გამოხატულება გახდა. მისი უზარმაზარი ღირებულება კი ოსმალური ფინანსების საგარეო ვალის სპირალში შესვლის წლების ერთ-ერთი ყველაზე გაკრიტიკებული ხარჯი გახდა.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["ვლახეთისა და მოლდოვის გაერთიანება კუზას მმართველობით: რუმინეთის დაბადება", "baef4da5"], "d": ["პარიზის ზავის შემდეგ ჩატარებულ არჩევნებში ორივე სამთავრომ ვოევოდად პოლკოვნიკი ალექსანდრუ იოან კუზა აირჩია და ფაქტობრივი გაერთიანება განახორციელა. მიუხედავად იმისა, რომ ბაბიალი და ავსტრია ამას ეწინააღმდეგებოდნენ, საფრანგეთის მიერ მხარდაჭერილი მომხდარი ფაქტი იძულებული გახდნენ ეღიარებინათ. ქაღალდზე ოსმალეთზე დაქვემდებარებულად დარჩენილი ეს გაერთიანება 1862 წელს რუმინეთის სახელს მიიღებდა, 1877 წელს კი ცალმხრივად დამოუკიდებლობას გამოაცხადებდა; ეს გარდამტეხი მომენტია დუნაის ნაპირას ოსმალთა ბატონობის რღვევაში.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["ქულელის ინციდენტი: აბდულმეჯიდის წინააღმდეგ გადატრიალების პირველი მცდელობა სტამბოლში", "e3653b21"], "d": ["თანზიმათის პოლიტიკითა და ისლაჰათის ფირმანით არამუსლიმთათვის მინიჭებული თანასწორობით უკმაყოფილო სამხედრო-სამოქალაქო შერეული ფარული საზოგადოება, ფადიშაჰის ტახტიდან ჩამოგდების დაგეგმვისას, ქილიჩ ალი-ფაშას მეჩეთში შეკრებისას დააკავეს. რადგან ბრალდებულები ქულელის ყაზარმაში გაასამართლეს, მოვლენა ამ სახელით მოიხსენიეს; სასიკვდილო განაჩენები გადასახლებით შეიცვალა. იგი ოსმალეთის ისტორიაში იდეოლოგიური მოტივით შექმნილი ორგანიზაციის მიერ სასახლის გადატრიალების პირველ მცდელობად მიიჩნევა.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["დრუზთა და მარონიტთა სამოქალაქო ომი ლიბანის მთაში და დამასკოს მოვლენები", "5595fdd6"], "d": ["1860 წლის მაისში საიდის მახლობლად ორი დრუზის მოკვლით აფეთქებული შეტაკებები ლიბანის მთაში დრუზებსა და მარონიტებს შორის ყველაზე სისხლიან სამოქალაქო ომად იქცა და ივლისში დამასკოზე გადავარდა; იგი ათასობით ქრისტიანის სიკვდილით დასრულდა. საფრანგეთის მიერ ჯარის გადმოსხმის გამო ბაბიალიმ ფუად-ფაშა საგანგებო უფლებამოსილებით რეგიონში გაგზავნა; ჩატარდა მკაცრი დამსჯელი ოპერაცია. მოვლენებმა ევროპულ ინტერვენციას საბაბი შეუქმნა და ლიბანისთვის სპეციალური სტატუსის მინიჭების პირდაპირი მიზეზი გახდა.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["„თერჯუმან-ი აჰვალის“ გამოცემის დაწყება: პირველი კერძო თურქული გაზეთი სტამბოლში", "24792957"], "d": ["აგაჰ ეფენდის მიერ გამოცემული „თერჯუმან-ი აჰვალი“, რომლის სარედაქციო საქმიანობა შინასიმ იკისრა, სახელმწიფო მხარდაჭერის გარეშე გამოსული პირველი თურქული გაზეთია. პირველი ნომრის წინასიტყვაობაში დაცული იყო ხალხის უფლება, საკუთარ საქმეებზე ეთქვა სიტყვა; გაზეთმა შინასის „პოეტის ქორწინება“ ნაწილ-ნაწილ გამოაქვეყნა და თანამედროვე თურქული ლიტერატურის კარიც შეაღო. ოსმალეთში საზოგადოებრივი აზრის ცნებისა და ოპოზიციური პრესის დაბადებას ამ თარიღს უკავშირებენ.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["ლიბანის მთის ნიზამნამე: ლიბანისთვის პრივილეგირებული მუთასარიფობის სტატუსი", "bf375603"], "d": ["1860 წლის ხოცვა-ჟლეტების შემდეგ დიდი სახელმწიფოების ზეწოლით მომზადებულმა ნიზამნამემ ლიბანის მთა პირდაპირ ბაბიალიზე დაქვემდებარებულ, აღმსარებლობათაშორის ბალანსზე აგებული ადმინისტრაციული საბჭოთი მართულ პრივილეგირებულ მუთასარიფობად აქცია. პირობად დაიდო, რომ მუთასარიფი ოსმალეთის ქვეშევრდომი კათოლიკე ქრისტიანი უნდა ყოფილიყო და მისი დანიშვნა დიდი სახელმწიფოების დამტკიცებაზე უნდა წარდგენილიყო; პირველი მუთასარიფი დაუდ-ფაშა გახდა. ეს წესრიგი 1915 წლამდე გაგრძელდებოდა და თანამედროვე ლიბანის სახელმწიფოს ბირთვს შექმნიდა.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["აბდულმეჯიდის გარდაცვალება და სულთან აბდულაზიზის ტახტზე ასვლა", "27204d7c"], "d": ["ოცდაორწლიან მმართველობაში თანზიმათისა და ისლაჰათის ფირმანების ხელმომწერი აბდულმეჯიდის ტუბერკულოზით გარდაცვალების შემდეგ ძმა აბდულაზიზი ავიდა ტახტზე. ახალმა ფადიშაჰმა პირველ წლებში ეკონომიის ზომებითა და უბრალო ცხოვრების წესით იმედი გააჩინა; ფლოტი მსოფლიოს ერთ-ერთ გამორჩეულ ძალად აქცია. თუმცა მისი მმართველობის ბოლოს მძიმე საგარეო ვალი, 1875 წლის გაკოტრება და ბალკანეთის აჯანყებები დაგროვდა და 1876 წლის გადაყენების მოძრაობისთვის ნიადაგი მოამზადა.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["გაერთიანებული სამთავროების მიერ რუმინეთის სახელის მიღება", "d960e3fc"], "d": ["1859 წელს კუზას ორმაგი არჩევით ფაქტობრივად გაერთიანებულმა ვლახეთმა და მოლდოვამ 1862 წელს თავიანთი პარლამენტები და მთავრობები ბუქარესტში ერთ ჭერქვეშ გააერთიანეს და ოფიციალურად რუმინეთის სახელი მიიღეს. მიუხედავად იმისა, რომ ოსმალეთის სახელმწიფომ სამართლებრივად სიუზერენის წოდება და ყოველწლიური ხარკი შეინარჩუნა, სამთავროზე კონტროლი ფაქტობრივად დაკარგა. დუნაის ჩრდილოეთით ოსმალთა ოთხსაუკუნოვანი გავლენის დასასრული ამ თარიღით სიმბოლიზდება.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["სუაკინის, მასავასა და დაჰლაქის ეგვიპტეზე მიბმა", "a0924860"], "d": ["1846 წელს სულთან აბდულმეჯიდის მიერ ეგვიპტის ხედივ მეჰმედ ალი-ფაშასთვის სუაკინთან ერთად სალიანეს (შემოსავლის გამოყოფის) სახით გადაცემული მასავა ხედივ ისმაილ-ფაშას დროს დაჰლაქთან და სუაკინთან ერთად ეგვიპტის საკუთრებაში შეიტანეს და ქაიმაყამობის სტატუსით მოაწყვეს. ამგვარად, წითელი ზღვის აფრიკულ სანაპიროზე მდებარე ეს სამი ნავსადგური, სამართლებრივად ოსმალურ მიწად დარჩენის მიუხედავად, ადმინისტრაციულად პირდაპირ ბაბიალიდან კაიროზე გადავიდა — მეზობელ ეგვიპტესა და სუდანთან იმავე ვასალურ ფენაში შევიდა.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["კრეტის აჯანყების დაწყება (1866-1869)", "3679b861"], "d": ["საბერძნეთის აშკარა მხარდაჭერით კუნძულზე იფეთქა ფართომასშტაბიანმა აჯანყებამ, რომელმაც კრეტელი ბერძნების ენოსისის (საბერძნეთთან შეერთების) მოთხოვნა პირველად საერთაშორისო საკითხად აქცია. სამწლიანმა მძიმე მთის ომმა ოსმალურ ჯარს მძიმე დანაკარგები მიაყენა და ევროპულ საზოგადოებრივ აზრში დიდი გამოძახილი გამოიწვია. აჯანყების ჩაქრობა მხოლოდ 1868 წელს გახდა შესაძლებელი, როცა ალი-ფაშა კუნძულზე ჩავიდა და ფართო პრივილეგიების მიმნიჭებელი ნიზამნამე აამოქმედა.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["ბელგრადიდან და სერბეთის ციხეებიდან უკანასკნელი ოსმალური გარნიზონების გასვლა", "b34217db"], "d": ["დიდი სახელმწიფოების ზეწოლისა და პრინც მიხაილოს დაჟინებული მოთხოვნის გამო ბაბიალი დათანხმდა სერბეთში მის ხელში დარჩენილი უკანასკნელი სამხედრო ბაზების დაცლაზე; 1867 წლის 18 აპრილს ბელგრადის ციხეში ოსმალური სანჯაყი (დროშა) ჩამოუშვეს და გასაღებები მთავარს გადასცეს. ამგვარად, 1521 წლიდან არსებული ოსმალთა ფაქტობრივი სამხედრო ყოფნა დასრულდა და სერბეთის დამოუკიდებლობისკენ მიმავალ გზაზე უკანასკნელი დიდი დაბრკოლება მოიხსნა. ფადიშაჰის სიუზერენობა მხოლოდ სიმბოლურ დროშისა და ხარკის საკითხზე დაიყვანეს.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["ეგვიპტის მმართველებისთვის ხედივის ტიტულის მინიჭება", "09e10c12"], "d": ["ქავალალის დინასტიის მესამე თაობის წარმომადგენლის ისმაილ-ფაშას ინტენსიური ლობირებისა და სტამბოლში ჩადინებული ფულის შედეგად ეგვიპტის ვალის მიენიჭა ხედივის ტიტული, რომელიც ხაზს უსვამდა მის უპირატესობას სხვა ვალიებზე. იმავე წლებში მემკვიდრეობის წესიც ისე შეიცვალა, რომ მამიდან შვილზე გადასულიყო, და ეგვიპტეს სუვერენული ხასიათის უფლებამოსილებები მიენიჭა: საგარეო სესხის აღება, მედლების გაცემა, საკონსულოების ყოლა. ეს ნაბიჯები ეგვიპტის ოსმალეთისგან სამართლებრივი მოწყვეტის დამაჩქარებელი ჯაჭვის პირველი რგოლია.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["კრეტის ნიზამნამე: კუნძულისთვის ფართო ადმინისტრაციული პრივილეგიები", "12052262"], "d": ["სამწლიანი აჯანყების დასასრულებლად დიდი ვეზირი ალი-ფაშა პირადად გადავიდა კუნძულზე და ფადიშაჰის დამტკიცებით გამოქვეყნებული ნიზამნამეთი კრეტელებს შერეული ადმინისტრაციული საბჭოები, ადგილობრივი სასამართლოები, ოფიციალურ საქმეებში ბერძნული ენის გამოყენება და საგადასახადო შეღავათები მიანიჭა. ამ რეგულაციამ კუნძულზე ოსმალთა ბატონობა კიდევ ოცდაათი წელი შეინარჩუნა. თუმცა ქრისტიან მოსახლეობისთვის მინიჭებულმა პრივილეგიებმა მუსლიმი კრეტელების მდგომარეობა შეასუსტა და 1896-1898 წლების კრიზისის თესლი ჩათესა.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["შურა-ი დევლეთის გახსნა: ოსმალური სახელმწიფო საბჭოს დაარსება", "70b16497"], "d": ["1868 წლის 5 მარტის ირადეთი სასამართლო დადგენილებათა საბჭო ორად გაიყო: ადმინისტრაციულ-საკანონმდებლო საქმეები შურა-ი დევლეთს (სახელმწიფო საბჭოს), სასამართლო საქმეები კი სამართლის დადგენილებათა დივანს გადაეცა; დაწესებულება ბაბიალიში ცერემონიით გაიხსნა და მის პირველ თავმჯდომარედ მიდჰათ-ფაშა დაინიშნა. მას დაევალა კანონპროექტების მომზადება, ადმინისტრაციული დავების გადაწყვეტა და მოხელეთა სასამართლო საქმეების წარმოება. მუსლიმთა და არამუსლიმთა შერეული წევრობის სტრუქტურით იგი ოსმალეთში ხელისუფლების დანაწილების იდეის პირველ ინსტიტუციურ განხორციელებად მიიჩნევა.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["სუეცის არხის გახსნა: ეგვიპტის გავლით ინდოეთის გზის დამოკლება", "377ccd04"], "d": ["1859 წელს დაწყებული მშენებლობა ათი წელი გაგრძელდა და ხმელთაშუა ზღვის წითელ ზღვასთან დამაკავშირებელი 163-კილომეტრიანი არხი ბრწყინვალე ცერემონიით ამოქმედდა. რადგან ევროპის ინდოეთთან დამაკავშირებელი გზა ათასობით მილით დამოკლდა, ეგვიპტე ერთბაშად მსოფლიო ვაჭრობის საკვანძო წერტილად იქცა. სწორედ ეს გეოსტრატეგიული ღირებულება გახდა მთავარი მიზეზი იმისა, რომ არხის გახსნიდან ცამეტი წლის შემდეგ ინგლისმა ეგვიპტე დაიკავა; არხის მიერ ეგვიპტისთვის დაკისრებული ვალი კი ხედივობას გაკოტრებამდე მიიყვანდა.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["ბულგარეთის საეგზარქოსოს დაარსება: ბულგარული ეკლესიის ფანარისგან გამოყოფა", "33a8272c"], "d": ["ფადიშაჰის ფირმანით ბერძნული საპატრიარქოსგან ცალკე, დამოუკიდებელი ბულგარული ეკლესია (საეგზარქოსო) დაარსდა, ხოლო თუ რომელი კაზები დაუქვემდებარდებოდა საეგზარქოსოს, სახალხო კენჭისყრას მიანდეს. მიუხედავად იმისა, რომ ბაბიალიმ ეს ნაბიჯი ბერძნული გავლენის გასატეხად გადადგა, შედეგი საპირისპირო გამოდგა: ეკლესია ბულგარული ეროვნული იდენტობისა და მაკედონიაზე ბულგარული პრეტენზიის ორგანიზებულ ცენტრად იქცა. ამგვარად ჩაეყარა ბალკანეთში ბულგარულ-ბერძნულ-სერბული მეტოქეობისა და 1876 წლის აჯანყებების ინსტიტუციური საფუძველი.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["ასირის პირდაპირ მმართველობაში აყვანა", "4559e099"], "d": ["სუეცის არხის გახსნით წითელი ზღვის სტრატეგიული მნიშვნელობის გაზრდის შემდეგ ცხადი გახდა, რომ იემენისკენ მიმავალი სახმელეთო გზის შუაში მდებარე ასირის მთების უკონტროლოდ დატოვება არ შეიძლებოდა. იემენის ლაშქრობაში გასული რედიფ-ფაშას ძალები ებჰაში შევიდნენ, მხარე პირდაპირ ოსმალურ მმართველობას დაუქვემდებარეს და ასირის სანჯაყი დაარსეს. მთიანი გეოგრაფიისა და იდრისიანთა გავლენის გამო ეს ბატონობა არასოდეს დამკვიდრებულა სრულად.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["მიდჰათ-ფაშას ნეჯდის ლაშქრობა: ლაჰსაში ოსმალთა ბატონობის აღდგენა", "7db51461"], "d": ["ბაღდადის ვალი მიდჰათ-ფაშამ საუდის ოჯახის შიდა ტახტისთვის ბრძოლით ისარგებლა, სპარსეთის ყურის დასავლეთ სანაპიროზე ჯარი გაგზავნა და ლაჰსას მხარე ნეჯდის სანჯაყის სახელით ბასრის ვილაიეთზე მიაბა. აბდულაჰ ბ. ფაისალი მუთასარიფად დანიშნეს და ოსმალთა ბატონობა ქაღალდზე დამყარდა. ლაშქრობა მიზნად ისახავდა ყურეში ინგლისური გავლენის გავრცელების შეჩერებას და იმავე წელს ყატარის ოსმალთა კონტროლქვეშ მოქცევაც გამოიწვია.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["დიდი ვეზირ ალი-ფაშას გარდაცვალება: თანზიმათის კადრის დასასრული", "1cf0141c"], "d": ["1869 წელს ფუად-ფაშას გარდაცვალების შემდეგ თანზიმათის პოლიტიკის მარტოდმარტო მტვირთველი ალი-ფაშას გარდაცვალებით ამოიწურა იმ გამოცდილი დიპლომატების თაობა, რომელიც ოცდაათი წელი სახელმწიფოს საგარეო პოლიტიკას წარმართავდა. მის ადგილზე მოსული მაჰმუდ ნედიმ-ფაშას რუსეთის მომხრე და თვითნებურმა მმართველობამ აბდულაზიზის პირადი მმართველობა განამტკიცა. ალი-ფაშას გარდაცვალებიდან ხუთი წლის განმავლობაში ფინანსები გაკოტრდა, ბალკანეთი აჯანყდა და მმართველის შეცვლა გარდაუვალი გახდა.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["ყატარში ოსმალური კონტროლის დამყარება", "3b453165"], "d": ["ინგლისური ზეწოლის ქვეშ მყოფი შეიხ ყასიმ ბ. სანის მოწვევით ოსმალური ძალები ყატარის ნახევარკუნძულზე გადმოსხდნენ და 1871 წლის შემოდგომაზე რეგიონში ოსმალური კონტროლი დამყარდა. ყატარი ნეჯდის სანჯაყზე დაქვემდებარებულ კაზად მოეწყო და შეიხი ქაიმაყამად დანიშნეს. ეს ნაბიჯი ყურეში ინგლისის წინააღმდეგ მიდჰათ-ფაშას მიერ გატარებული აქტიური პოლიტიკის ყველაზე კონკრეტული მონაპოვარი გახდა; ოსმალური დროშა ნახევარკუნძულზე 1913 წლამდე ფრიალებდა.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["ტუნისის მემკვიდრეობის ფირმანი — საბეო მეჰმედ სადიყ-ფაშას ოჯახს", "1509ebb0"], "d": ["ტუნისის ბეიმ მეჰმედ სადიყ-ფაშამ პრუსიასთან საფრანგეთის დამარცხებით ისარგებლა და სტამბოლში ჰაირედინ-ფაშა გაგზავნა; მისი ძალისხმევით გამოცემული ფირმანით ტუნისი, რომელიც უშუალოდ სტამბოლს უნდა დაქვემდებარებოდა, მემკვიდრეობითი წესით მეჰმედ სადიყ-ფაშასა და მის შთამომავლებს გადაეცა. ფადიშაჰის ნებართვის გარეშე საომარი და საზავო მოლაპარაკებები არ უნდა გამართულიყო, ქვეყნიდან არავითარი მიწა სხვას არ უნდა გადასცემოდა და ოსმალეთის ჯარის მოთხოვნა უნდა დაკმაყოფილებულიყო. საფრანგეთმა ფირმანი არ ცნო; ათი წლის შემდეგ ტუნისი დაიკავა.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["სანას აღება: იემენში ოსმალური ავტორიტეტის აღდგენა", "978e20a0"], "d": ["სუეცის არხის გახსნით წითელი ზღვის სტრატეგიული მნიშვნელობის გაზრდის შემდეგ ბაბიალიმ იემენში აჰმედ მუხთარ-ფაშას სარდლობით სარეზერვო დივიზიის ჯარი გაგზავნა. სანას აღებით ორი საუკუნის განმავლობაში ფაქტობრივად დაკარგულ შიდა იემენში სახელმწიფო ავტორიტეტი აღდგა და მხარე ვილაიეთად აქციეს. თუმცა ზეიდიტ იმამებთან ბრძოლა არასოდეს დასრულებულა; 1891, 1898 და 1904 წლების აჯანყებებმა ოსმალეთის ყველაზე ძვირი და ყველაზე ხანგრძლივი შიდა ფრონტი შექმნა. იმავე თარიღს შემოერთებული სხვა ადგილები: სანა, ტაიზი.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["ჰერცეგოვინის აჯანყების დაწყება: აღმოსავლური საკითხის ხელახალი გაღვივება", "571b18ec"], "d": ["მძიმე გადასახადებისა და აიანების ზეწოლის გამო ნევესინიეს მიდამოებში ქრისტიანი გლეხების აჯანყება მალე მთელ ჰერცეგოვინაში გავრცელდა და სერბეთიდან და მონტენეგროდან მოსული მოხალისეებით იკვებებოდა. ავსტრიისა და რუსეთის რეფორმების თავსმოხვევის გამომწვევმა აჯანყებამ მომდევნო წელს ბულგარელთა აჯანყებები და სერბეთ-მონტენეგროს ომის გამოცხადებები გამოიწვია. ამგვარად გატყდა 93 წლის ომამდე და ბერლინის ტრაქტატით ბალკანეთის დაკარგვამდე მიმავალი დიდი ჯაჭვის პირველი რგოლი.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["ოსმალური ფინანსების გაკოტრება: საგარეო ვალის გადახდების ნახევრამდე შემცირება", "2cac2fa5"], "d": ["1854 წლიდან ერთმანეთის მიყოლებით აღებულმა სესხებმა, ყირიმის ომის ხარჯებმა, სასახლეთა მშენებლობამ და 1873-74 წლების ანატოლიის შიმშილობამ ბიუჯეტის დეფიციტი ხუთ მილიონ ლირაზე მეტ უფსკრულად აქცია. მაჰმუდ ნედიმ-ფაშას მთავრობამ გამოაცხადა, რომ ვალის პროცენტისა და ძირითადი თანხის გადახდები ხუთი წლის განმავლობაში ნახევრამდე შემცირდებოდა, და ფაქტობრივად მორატორიუმი გამოაცხადა. ევროპულ ბირჟებზე დიდი რეაქციის გამომწვევმა ამ გადაწყვეტილებამ დაიწყო პროცესი, რომელიც ექვსი წლის შემდეგ მუჰარამის დეკრეტითა და ოსმალური სახელმწიფო ვალის ადმინისტრაციის (Düyûn-ı Umûmiyye) დაარსებით დასრულდებოდა.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["მურად V-ის გადაყენება და აბდულჰამიდ II-ის ტახტზე ასვლა", "cffb2271"], "d": ["აბდულაზიზის ტახტიდან ჩამოგდების შემდეგ ტახტზე ასული მურად V ბიძის სიკვდილითა და ჩერქეზ ჰასანის ინციდენტით შერყეული ფსიქიკური ჯანმრთელობის გამო მოვალეობის შესრულებას ვეღარ ახერხებდა; ოთხმოცდაცამეტდღიანი მმართველობიდან მხოლოდ შვიდი დღე იყო გონებით საღი. შეიხულისლამის ფეთვით გადააყენეს და მის ადგილზე ძმა აბდულჰამიდ II მოიყვანეს. ახალი ფადიშაჰი ტახტზე მიდჰათ-ფაშასთვის კონსტიტუციური წყობის (მეშრუთიეთის) გამოცხადების დაპირებით ავიდა; იწყებოდა ეპოქა, რომელიც ოცდაცამეტი წელი გაგრძელდებოდა.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["საზღვაო არსენალის (თერსანეს) კონფერენცია: დიდი სახელმწიფოების ბალკანეთის რეფორმის თავსმოხვევა", "b5006a2c"], "d": ["ბალკანეთის კრიზისის მოსაგვარებლად დიდი სახელმწიფოების მიერ სტამბოლში მოწვეულმა კონფერენციამ მოითხოვა ბულგარეთის ორ ავტონომიურ ვილაიეთად გაყოფა და ბოსნია-ჰერცეგოვინაში საერთაშორისო კონტროლქვეშ მყოფი რეფორმის გატარება. ბაბიალიმ კონფერენციის გახსნის დღეს ზარბაზნების გასროლით ძირითადი კანონის (ყანუნ-ი ესასის) გამოცხადება აუწყა და თავსმოხვეულ მოთხოვნებს კონსტიტუციური რეფორმით უპასუხა. დელეგატებმა ეს დროის გაწელვად ჩათვალეს და 1877 წლის 20 იანვარს დაიშალნენ; ოთხი თვის შემდეგ რუსეთმა ომი გამოაცხადა.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["დეპუტატთა პირველი პალატის (მეჯლის-ი მებუსანის) გახსნა დოლმაბაჰჩეში", "429bb279"], "d": ["ძირითადი კანონის თანახმად არჩეული 115 დეპუტატი 1877 წლის 19 მარტს დოლმაბაჰჩეს სასახლის საზეიმო მილოცვის დარბაზში გამართულ ცერემონიაზე პირველად შეიკრიბა; ამგვარად, ოსმალეთის ისტორიაში წარმომადგენლობითი პარლამენტის ეპოქა დაიწყო. მუსლიმმა და არამუსლიმმა დეპუტატებმა მთავრობა მკაცრად დაკითხეს, ომის მართვა და მინისტრების პასუხისმგებლობა განიხილეს. ეს გაბედული ოპოზიცია პარლამენტის სიცოცხლის შემამოკლებელი მთავარი მიზეზი გახდებოდა.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["პლევნის თავდაცვის დაწყება: გაზი ოსმან-ფაშას წინააღმდეგობა", "0e04a878"], "d": ["93 წლის ომში დუნაის გადამლახველი რუსული ჯარის სტამბოლის გზის მოსაჭრელად ვიდინიდან პლევნისკენ მიმავალმა ოსმან-ფაშამ ქალაქი რედუტებითა და სანგრებით გაამაგრა და ხუთთვიანი ლეგენდარული თავდაცვა დაიწყო. ერთმანეთის მიყოლებით სამი დიდი რუსულ-რუმინული შეტევა მძიმე დანაკარგებით მოიგერიეს და ცარ ალექსანდრე II-ის პირადად მართული ჯარი იძულებული გახდა ალყაზე გადასულიყო. პლევნა ისტორიაში XIX საუკუნის ოსმალური ჯარის ყველაზე ბრწყინვალე თავდაცვით წარმატებად შევიდა.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["პლევნის დაცემა: დუნაის ფრონტის ჩამოშლა", "185e7602"], "d": ["ხუთთვიანი ალყის განმავლობაში სურსათამოწურულმა ოსმან-ფაშამ მდინარე ვიდის გასწვრივ გამოხტომის ოპერაცია წამოიწყო; დაჭრილი რომ ტყვედ ჩავარდა, ქალაქი დანებდა. რუსმა სარდლებმა დატყვევებულ ფაშას ხმალი დაუბრუნეს და მიესალმნენ, ოსმან-ფაშას კი „გაზის“ ტიტული მიენიჭა. პლევნის დაცემით რუსულ ჯარს გზა გაეხსნა; ორი თვის განმავლობაში სოფია, ფილიპოპოლი და ედირნე დაეცა და რუსული ავანგარდები იეშილქოის მიაღწიეს.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["სოფიის ოკუპაცია რუსული ძალების მიერ", "ef369d22"], "d": ["პლევნის დაცემის შემდეგ ბალკანეთის მთების გადამლახველი რუსული ჯარი უმწეოდ დარჩენილ სოფიაში შევიდა. ქალაქი ოსმალურ მმართველობას აღარასოდეს დაუბრუნდება: 1878 წლის ბოლოს ავტონომიური ბულგარეთის სამთავროს, 1879 წელს კი ფაქტობრივად მისი დედაქალაქი გახდება. რუკაზე სოფია ამ თარიღიდან ოსმალთა პირდაპირი მმართველობიდან გადის და დროებით რუსულ ოკუპაციაში, შემდეგ კი ავტონომიურ ბულგარულ მმართველობაში გადადის.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["ედირნეს დროებითი ზავი: იარაღის გაჩუმება 93 წლის ომში", "1f899180"], "d": ["სოფიის, ფილიპოპოლისა და ედირნეს ერთმანეთის მიყოლებით დაცემისა და რუსული ჯარის მარმარილოს ზღვის სანაპიროებს მიდგომის გამო ბაბიალი იძულებული გახდა დროებითი ზავი ეთხოვა. ედირნეში ხელმოწერილმა ცეცხლის შეწყვეტამ ოსმალეთს მიაღებინა წინასწარი ზავის ისეთი პირობები, როგორიცაა ბულგარეთისთვის ავტონომია, მონტენეგროს, სერბეთისა და რუმინეთის დამოუკიდებლობა და მძიმე საომარი კონტრიბუცია. ეს პირობები ერთი თვის შემდეგ სან-სტეფანოში ხელშეკრულების ტექსტად იქცეოდა.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["აბდულჰამიდ II-ის მიერ დეპუტატთა პალატის უვადოდ დათხოვნა", "e770b540"], "d": ["ომის კატასტროფით დასრულებისთვის მთავრობისა და სასახლის პასუხისმგებლად ჩამთვლელი დეპუტატების მკაცრი კრიტიკის გამო აბდულჰამიდ II-მ ძირითადი კანონით მისთვის მინიჭებულ უფლებამოსილებაზე დაყრდნობით პარლამენტი უვადოდ დაითხოვა. დაახლოებით თერთმეტი თვე მომუშავე პირველი ოსმალური პარლამენტი ამგვარად დაიხურა და დაიწყო ტირანიის (ისთიბდადის) ეპოქა, რომელიც ოცდაათი წელი გაგრძელდებოდა. პარლამენტის ხელახლა შეკრება მხოლოდ 1908 წლის რევოლუციის შემდეგ გახდა შესაძლებელი.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["სან-სტეფანოს ზავი: დიდი ბულგარეთის პროექტი", "2c7cc611"], "d": ["93 წლის ომის დამსრულებელი სან-სტეფანოს ზავი ქმნიდა ეგეოსამდე გადაჭიმულ და მაკედონიის მომცველ უზარმაზარ ავტონომიურ ბულგარეთს; აღიარებდა სერბეთის, მონტენეგროსა და რუმინეთის დამოუკიდებლობას; ყარსს, არდაჰანს, ბათუმსა და დოღუბაიაზითს რუსეთს უთმობდა და ამასთან გადაუხდელ საომარ კონტრიბუციას აკისრებდა. რუსეთის ხმელთაშუა ზღვამდე ჩამყვანმა ამ ტექსტმა ინგლისისა და ავსტრიის მკაცრი რეაქცია გამოიწვია. განუხორციელებლად, ოთხ თვეში, ბერლინის კონგრესმა ხელახლა მოაწყო; მაინც დარჩა ოსმალური რუმელიის დასასრულის გამომცხადებელ დოკუმენტად.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["ყარსი, არტაანი და ბათუმი რუსეთს გადაეცა — ელვიეი სელასე", "99bdfad2"], "d": ["ბერლინის ტრაქტატით ოსმალეთის სახელმწიფომ ყარსი, არტაანი და ბათუმი საომარი კონტრიბუციის ნაწილის სანაცვლოდ რუსეთს დაუთმო; სან-სტეფანოში რუსეთისთვის მიცემული დოღუბაიაზითი და ელეშკირტის ხეობა კი ოსმალეთს დარჩა. ბათუმი თავისუფალ ნავსადგურად გადაეცა, მაგრამ ეს სტატუსი მხოლოდ 1886 წლამდე შეინარჩუნა. რუსებმა ყარსი ოლქად აქციეს, რომელიც თბილისში ცენტრის მქონე ამიერკავკასიის გენერალ-გუბერნატორობას ექვემდებარებოდა; ელვიეი სელასედან 100 000-მდე ადამიანი იძულებული გახდა ერზურუმის მხარეში გადასახლებულიყო. იმავე ტრაქტატით სამხრეთ ბესარაბია (კილია, კაჰული, ბოლგრადი) რუმინეთიდან რუსეთს დაუბრუნდა.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["ბოსნია-ჰერცეგოვინისა და ნოვი-პაზარის ოკუპაცია ავსტრია-უნგრეთის მიერ", "e5f901df"], "d": ["ბერლინის ტრაქტატით მინიჭებულ უფლებამოსილებაზე დაყრდნობით ავსტრია-უნგრეთის ჯარები ბოსნიაში შევიდა; მიუხედავად იმისა, რომ ოსმალეთის მთავრობა წინააღმდეგობის არგაწევაზე დათანხმდა, სარაევოსა და მოსტარის ადგილობრივმა მუსლიმმა და მართლმადიდებელმა მოსახლეობამ იარაღს ხელი მოჰკიდა და სამი თვის განმავლობაში მძიმე წინააღმდეგობა გაუწია. ოკუპაციის დასრულება მხოლოდ 1878 წლის 20 ოქტომბერს გახდა შესაძლებელი. ფადიშაჰის სამართლებრივი სუვერენიტეტი ქაღალდზე 1908 წლამდე გაგრძელდა, მაგრამ ოთხსაუკუნოვანი ოსმალური ბოსნია ფაქტობრივად ხელიდან გავიდა და მუსლიმთა დიდი მიგრაციული ტალღა დაიწყო. იმავე თარიღს ხელიდან გასული სხვა დასახლებები: ბანია-ლუკა.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["მუჰარამის დეკრეტი და ოსმალური სახელმწიფო ვალის ადმინისტრაციის დაარსება", "02b7cc03"], "d": ["1875 წლის გაკოტრების შემდეგ კრედიტორი სახელმწიფოების წარმომადგენლებთან გამართული მოლაპარაკებები ჰიჯრის 1299 წლის 28 მუჰარამის (1881 წლის 20 დეკემბრის) დეკრეტით დასრულდა: ვალის ძირითადი თანხა ნახევარზე მეტით შემცირდა, სამაგიეროდ ისეთი ყველაზე შემოსავლიანი მუხლები, როგორიცაა მარილის, თამბაქოს, აბრეშუმის, საგერბო და თევზის გადასახადები, პირდაპირ კრედიტორების მიერ მართულ ოსმალური სახელმწიფო ვალის ადმინისტრაციას გადაეცა. ათასობით მოხელის დამსაქმებელი ეს ადმინისტრაცია სახელმწიფოს შიგნით ცალკე საფინანსო ორგანიზაციად იქცა. ეს თარიღი ოსმალური ფინანსური დამოუკიდებლობის ფაქტობრივ დასასრულად მიიჩნევა.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["სუაკინი — ერთადერთი ნავსადგური, რომელიც მაჰდის ხელში არ ჩავარდა", "5a37b198"], "d": ["1884 წლის თებერვლიდან, როცა სუაკინის გარდა აღმოსავლეთ სუდანის ყველა მხარე მუჰამად აჰმად ალ-მაჰდის ბატონობის ქვეშ გადავიდა, ნავსადგური გენერალ გრეჰემის სარდლობით სამბატალიონიანი ინგლისური ძალის სამხედრო დაცვით გაძლო. ეს იყო ფაქტობრივი და სამართლებრივი მდგომარეობის გამიჯვნის პერიოდის დასაწყისი: მიუხედავად იმისა, რომ სანაპირო ფაქტობრივად ინგლისური სამხედრო კონტროლის ქვეშ იყო, ადმინისტრაციული კავშირი 1885 წელს ეგვიპტეს ჩამოართვეს და პირდაპირ იემენის ვილაიეთს, ანუ ბაბიალის, მიაბეს — ეს წესრიგი 1888 წელს საფრანგეთის მიერ ზეილას ოკუპაციით დასრულებამდე გაგრძელდა.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["მიდჰათ-ფაშას მკვლელობა ტაიფის დილეგში", "f4562261"], "d": ["ძირითადი კანონის არქიტექტორი და პირველი კონსტიტუციური ეპოქის სიმბოლური ფიგურა მიდჰათ-ფაშა აბდულაზიზის სიკვდილთან დაკავშირებით ილდიზის სასამართლოზე დამნაშავედ ცნეს, სიკვდილით დასჯა გადასახლებით შეუცვალეს და ტაიფში გაგზავნეს. TDV-ის ჩანაწერის თანახმად, 1884 წლის 7-8 მაისის ღამეს საკანში დახრჩობით მოკლეს, ოფიციალურ მიზეზად კი „შირფენჩე“ (ანთრაქსის კარბუნკული) დაასახელეს. მისი სიკვდილი აბდულჰამიდ II-ის ეპოქაში კონსტიტუციური ოპოზიციის ლიკვიდაციის სიმბოლოდ იქცა.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["ჰაიდარფაშა-ანკარის რკინიგზის კონცესიის გერმანელებისთვის მინიჭება", "5705b163"], "d": ["ფადიშაჰის ირადეთი ჰაიდარფაშა-ანკარის ხაზის მშენებლობისა და ექსპლუატაციის კონცესია Deutsche Bank-ის წარმომადგენელ ბანკირს ალფრედ ფონ კაულას მიენიჭა და ანატოლიის რკინიგზის კომპანია დაარსდა. ეს კონცესია გარდამტეხი მომენტი გახდა, რომელმაც ოსმალურ ტრანსპორტსა და საგარეო პოლიტიკაში ინგლისურ-ფრანგული მონოპოლია გატეხა და გერმანული გავლენა დაამკვიდრა. თერთმეტი წლის შემდეგ იმავე კომპანიისთვის მინიჭებული ბაღდადის ხაზის კონცესიასთან ერთად „ბერლინ-ბაღდადის“ ოცნება გაჩნდა, რაც პირველ მსოფლიო ომამდე დიდ სახელმწიფოთა მეტოქეობის ერთ-ერთ მთავარ ღერძად იქცა.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["ოსმალური ერთობის საზოგადოების (İttihâd-ı Osmânî) დაარსება სტამბოლში", "b7187939"], "d": ["სამხედრო სამედიცინო სკოლის ოთხმა სტუდენტმა ტირანიული მმართველობის წინააღმდეგ ფარული ორგანიზაციის სახით ოსმალური ერთობის საზოგადოება დააარსა; ეს სტრუქტურა მალე „ერთობისა და პროგრესის“ კომიტეტად გადაიქცა, რომელიც ახალგაზრდა თურქთა მოძრაობის ყველა ოპოზიციურ ელემენტს თავის ქვეშ მოაქცევდა. უჯრედულ პრინციპზე აგებული ორგანიზაცია ევროპაში გადასახლებულებსა და სალონიკელ ოფიცრებს შეუერთდა. კადრი, რომელმაც 1908 წელს მეორე კონსტიტუციური ეპოქა გამოაცხადებინა და 1913 წლის შემდეგ სახელმწიფო მარტომ მართა, ამ პატარა სტუდენტური უჯრედიდან გამოვიდა.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["ოსმალეთის ბანკის დარბევა: დაშნაკთა აქცია გალათაში", "08b3095f"], "d": ["სომხური დაშნაკცუთიუნის ორგანიზაციის შეიარაღებული ჯგუფი, ევროპის ყურადღების სომხური საკითხისკენ მიპყრობის მიზნით, გალათაში ოსმალეთის ბანკის სათავო ოფისში შეიჭრა, მძევლები აიყვანა და შენობის აფეთქებით იმუქრებოდა. კრიზისი ელჩების ჩარევით დასრულდა იმის სანაცვლოდ, რომ მოქმედები გემით ქვეყნიდან გაიყვანეს. თავდასხმის შემდგომ დღეებში სტამბოლში მომხდარმა სისხლიანმა მოვლენებმა გადამწყვეტი როლი ითამაშა სომხური საკითხის საერთაშორისო ჩარევის ბერკეტად ქცევაში.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897 წლის ოსმალეთ-საბერძნეთის ომის დაწყება: თესალიის ფრონტი", "33e490ab"], "d": ["საბერძნეთის მიერ კრეტაზე ფლოტისა და ჯარის გადმოსხმისა და რუმელიის საზღვარზე შეიარაღებული რაზმების თავდასხმების გამო ოსმალეთის სახელმწიფომ ომი გამოაცხადა. გერმანული რეფორმის მისიის მიერ გაწვრთნილი ოსმალური ჯარი თესალიაში სწრაფად წავიდა წინ და ერთ თვეში ლარისა, ფარსალა და დომოკოსი აიღო; ბერძნული ჯარი დაიშალა. დიდი სახელმწიფოების ჩარევით დაპყრობილი მიწები დააბრუნეს, მაგრამ ომი აბდულჰამიდ II-ის ეპოქის ერთადერთ გადამწყვეტ სამხედრო გამარჯვებად დარჩა და კრეტის ფაქტობრივი დაკარგვა ვერ აღკვეთა.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["კონია-ბაღდადის ხაზის კონცესიის გერმანელებისთვის მინიჭება", "fd8b6cbd"], "d": ["კაიზერ ვილჰელმ II-ის 1898 წელს სტამბოლსა და დამასკოში ვიზიტის შემდეგ ანატოლიის რკინიგზის კომპანიას კონიიდან ბაღდადამდე და ბასრამდე გასაყვანი ხაზის წინასწარი კონცესია მიენიჭა. ბაღდადის რკინიგზის პროექტი ოსმალეთისთვის არაბულ ვილაიეთებზე ცენტრალური კონტროლის გაძლიერებას ნიშნავდა, გერმანიისთვის კი სპარსეთის ყურემდე მიღწევას. ინგლისისა და რუსეთის მკაცრად ეწინააღმდეგებული ეს პროექტი პირველ მსოფლიო ომამდე მიმყვანი იმპერიალისტური მეტოქეობის ერთ-ერთი ყველაზე სადავო საქმე გახდა.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["ჰიჯაზის რკინიგზის მშენებლობის დაწყება დამასკოში", "62f58f68"], "d": ["აბდულჰამიდ II-ის 1900 წლის 2 მაისის ირადეთი ნაბრძანები ხაზის მშენებლობა 1900 წლის 1 სექტემბერს დამასკოში გამართული ოფიციალური ცერემონიით დაიწყო. მთლიანად ისლამური სამყაროდან შეგროვებული შემოწირულობებითა და ოსმალო ინჟინერ-ჯარისკაცების შრომით შესრულებულმა პროექტმა მომლოცველთა დამასკო-მედინის მგზავრობა ორმოცი დღიდან ხუთ დღემდე შეამცირა. ეს იყო როგორც ხალიფატის სულიერი ავტორიტეტის განმამტკიცებელი პრესტიჟული ნაგებობა, ისე ჰიჯაზზე სამხედრო კონტროლის გამაძლიერებელი სტრატეგიული ინვესტიცია.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["მიურცშტეგის პროგრამა: საერთაშორისო რეფორმული კონტროლი მაკედონიაში", "4c7464da"], "d": ["ილინდენის აჯანყების შემდეგ რუსეთისა და ავსტრიის იმპერატორები მიურცშტეგში შეხვდნენ და მაკედონიისთვის რეფორმების ახალი პაკეტი მოამზადეს. პროგრამა ითვალისწინებდა ოსმალო გენერალური ინსპექტორის გვერდით ორი უცხოელი სამოქალაქო აგენტის განთავსებას, ჟანდარმერიის ევროპელი ოფიცრების მიერ ხელახლა მოწყობას და ადმინისტრაციული საზღვრების ეროვნების პრინციპით შეცვლას. მიუხედავად იმისა, რომ ბაბიალი სუვერენული უფლებების შელახვის საბაბით ეწინააღმდეგებოდა, ერთობლივი ზეწოლის წინაშე იძულებული გახდა მიეღო; პროგრამა ახალგაზრდა ოფიცრებში იტიჰადისტური ორგანიზაციის დამაჩქარებელი ერთ-ერთი ძირითადი ფაქტორი გახდა.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["მურად V-ის გარდაცვალება", "396659a7"], "d": ["მურად V, რომელიც 1876 წელს დაახლოებით სამი თვე იჯდა ტახტზე და გადააყენეს, მისი ტახტზე დაბრუნების მცდელობების შემდეგ მკაცრი მეთვალყურეობის ქვეშ ოცდარვა წელი პატიმრობაში ცხოვრობდა და შაქრიანი დიაბეტით გარდაიცვალა. ის იენიჯამის ჯედიდ ჰავათინის აკლდამაში, დედის გვერდით დაკრძალეს. ისტორიაში შევიდა, როგორც ტახტზე ყველაზე ხანმოკლედ მყოფი ოსმალო ფადიშაჰი.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["სანას დაკარგვა იმამ იაჰიას სასარგებლოდ", "e7f876cb"], "d": ["ზეიდიტი იმამ იაჰია ჰამიდუდინის მიერ 1904 წელს წამოწყებული აჯანყება 1905 წლის აპრილში ალყის ბოლოს სანას დაცემით დასრულდა; ქალაქი ოსმალურ მმართველობას გამოეყო და ალყის განმავლობაში შიმშილმა და ეპიდემიამ იფეთქა. იემენის მთიანი გეოგრაფია, მომარაგების ხაზების სიგრძე და ზეიდიტური იმამობის ადგილობრივი ლეგიტიმაცია აქ ოსმალთა ბატონობას დაარსებიდანვე მყიფეს ხდიდა. ქალაქს ხუთი თვის შემდეგ მძიმე დანაკარგების ფასად დაიბრუნებდნენ, მაგრამ იემენის საკითხი 1918 წლამდე არ დაიხურებოდა.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["ილდიზის ატენტატი: ბომბიანი თავდასხმა აბდულჰამიდ II-ზე", "1ee2e1a6"], "d": ["დაშნაკცუთიუნის ორგანიზაციამ პარასკევის სალამიდან გამოსული ფადიშაჰის ეტლზე საათის მექანიზმიანი ბომბით დატვირთული ლანდოს აფეთქებით ატენტატი მოაწყო; ის, რომ აბდულჰამიდი შეიხულისლამთან საუბრისას რამდენიმე წუთით დაყოვნდა, სიცოცხლე გადაურჩინა. აფეთქებისას ოცდაექვსი ადამიანი დაიღუპა, ორმოცდაათზე მეტი დაშავდა. მოვლენამ ფადიშაჰის უსაფრთხოების აკვიატება და ფარული აგენტების სამსახურზე დაფუძნებული ტირანიული მმართველობა კიდევ უფრო გაამკაცრა; ის თევფიქ ფიქრეთის ლექსის „ერთწამიანი დაგვიანება“ თემაც გახდა.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["სანას დაბრუნება: იმამ იაჰიას აჯანყების ჩახშობა", "dec3b8f9"], "d": ["1904 წელს ზეიდიტი იმამ იაჰიას ხელმძღვანელობით დაწყებული აჯანყება 1905 წლის აპრილში სანას დაცემით დასრულდა და ქალაქში შიმშილი და ეპიდემია გაჩნდა. ალი რიზა-ფაშასა და აჰმედ ფეიზი-ფაშას სარდლობით გამაგრებულმა ჯარებმა 1905 წლის 15 ივლისიდან 1 სექტემბრამდე წარმოებული და ტაიზში მყოფი ძალების მხარდაჭერილი ოპერაციით მძიმე დანაკარგების ფასად ქალაქი დაიბრუნეს და აჯანყება ჩაახშეს. იემენის ოპერაციამ ოსმალურ ჯარს ათიათასობით დანაკარგი და უზარმაზარი ფინანსური ტვირთი მოუტანა; რუმელიაში მყოფ ოფიცრებში „იემენში გადასახლების“ შიში იტიჰადისტური ორგანიზაციის გამომკვებავ საჩივრებს შორის პირველ ადგილზე იდგა.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["მეორე კონსტიტუციური ეპოქის პირველი დეპუტატთა პალატის შეკრება", "e7fd2716"], "d": ["ოცდაათწლიანი შესვენების შემდეგ ჩატარებული ორსაფეხურიანი არჩევნებით შექმნილი პარლამენტი 1908 წლის 17 დეკემბერს ფადიშაჰის სიტყვით გაიხსნა და მის თავმჯდომარედ ახალგაზრდა თურქთა მოძრაობის ლიდერი აჰმედ რიზა ბეი აირჩიეს. თურქი, არაბი, ალბანელი, ბერძენი, სომეხი და ებრაელი დეპუტატებისგან შემდგარი პარლამენტი ოსმალიზმის იდეალის უკანასკნელი დიდი ცდა იყო. თუმცა ბულგარეთის დამოუკიდებლობამ, ბოსნიის ანექსიამ და კრეტის საბერძნეთთან შეერთების გამოცხადებამ პარლამენტის გახსნამდეც კი დაჩრდილა ეს ოპტიმიზმი.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["მოქმედების არმია და აბდულჰამიდ II-ის გადაყენება: მეჰმედ V რეშადის ტახტზე ასვლა", "6a65a704"], "d": ["31 მარტის ინციდენტის გამო სალონიკიდან გამოსული მოქმედების არმია 22-23 აპრილის ღამეს ოთხი მიმართულებით შევიდა სტამბოლში, 24 აპრილს კი ილდიზის სასახლე დანებდა. გაერთიანებულმა ეროვნულმა პარლამენტმა 27 აპრილს აბდულჰამიდ II-ის გადაყენების გადაწყვეტილება მიიღო; ფადიშაჰი სალონიკში გაგზავნეს და მის ადგილზე ძმა მეჰმედ V რეშადი აიყვანეს ტახტზე. ოცდაცამეტწლიანი პირადი მმართველობა ამგვარად დასრულდა, მაგრამ მისი ადგილი ახალმა ეპოქამ დაიკავა, რომელშიც ფადიშაჰი სიმბოლურ ფიგურად იქცა, ხოლო „ერთობა და პროგრესი“ ჯარის მხარდაჭერით მართავდა.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["ალბანეთის აჯანყება: შეიარაღებული წინააღმდეგობა კოსოვოსა და შკოდერში", "93ed30c6"], "d": ["იტიჰადისტური მთავრობის ცენტრალისტურმა საგადასახადო პოლიტიკამ, იარაღის ამოღების კამპანიამ და ლათინური ანბანის დისკუსიამ აჯანყებაზე აიძულა ალბანური ტომები, რომლებიც მანამდე სახელმწიფოს ყველაზე ერთგულ ელემენტებად ითვლებოდა. მაჰმუდ შევქეთ-ფაშას სარდლობით ჯარმა აჯანყება მკაცრად ჩაახშო, მაგრამ უკმაყოფილება 1911 და 1912 წლებში ხელახლა აფეთქდა. ამ აჯანყებებმა ბალკანეთის ომის წინა პერიოდში ოსმალური ჯარი გამოფიტა და ალბანური ეროვნული მოძრაობის დაბადებაც დააჩქარა.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["უშის ზავი: ტრიპოლისა და ბენღაზის იტალიისთვის დათმობა", "4ffa1fd2"], "d": ["ბალკანეთის სახელმწიფოების საომარი მზადების წინაშე ორფრონტიანი კონფლიქტის ვერგამბედავმა ბაბიალიმ შვეიცარიის ქალაქ უშიში იტალიასთან ფარული ზავი მოაწერა ხელი და ტრიპოლი და ბენღაზი დათმო. ამგვარად, ოსმალეთის სახელმწიფომ აფრიკაში თავისი უკანასკნელი მიწა დაკარგა; სანაცვლოდ დაპირდნენ იტალიის მიერ ოკუპირებული როდოსისა და დოდეკანესის დაბრუნებას, მაგრამ ეს დაპირება არასოდეს შესრულებულა. ზავის ხელმოწერისას ბალკანეთის ომი უკვე დიდი ხნის დაწყებული იყო. ამ მოვლენით მურზუქი (ფეზანი), ღათი, საბჰა, უბარი, თრაღანი (Traghan), ზავილა (Zawila) და ალ-ქათრუნი (ფეზანი (ტრიპოლის ვილაიეთის სანჯაყი)) იტალიის მმართველობაში გადავიდა.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["საბერძნეთის მიერ ლემნოსის ოკუპაცია", "9555af1d"], "d": ["ბალკანეთის პირველ ომში ბერძნულმა ფლოტმა ლემნოსი დაიკავა; კუნძულის მუდროსის ნავსადგური დარდანელის ბლოკადის ბაზა გახდა. კუნძული ლოზანში (1923 წლის 24 ივლისი) საბერძნეთს დარჩა.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["საბერძნეთის მიერ თასოსის ოკუპაცია", "6c03c7f0"], "d": ["ბალკანეთის პირველ ომში საბერძნეთმა თასოსი და სამოთრაკე დაიკავა.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["საბერძნეთის მიერ სამოთრაკეს ოკუპაცია", "911e82a3"], "d": ["ბალკანეთის პირველ ომში საბერძნეთმა სამოთრაკე დაიკავა.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["საბერძნეთის მიერ მიტილენეს ოკუპაცია", "6b2b07ba"], "d": ["ბერძნული ფლოტი მიტილენეზე ნაპირზე გადავიდა; კუნძული ბალკანეთის პირველი ომის ბოლოს ბერძნულმა ჯარმა და ფლოტმა დაიკავეს. ლონდონის კონფერენციამ (1913 წლის მაისი) მდგომარეობა დაადასტურა.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["ბერძნული დესანტი ქიოსზე", "901c6539"], "d": ["ბალკანეთის პირველ ომში 1912 წლის 7 აპრილს დაბომბილ ქიოსზე ბერძნებმა დესანტი გადასხეს; ოსმალური გარნიზონი 1913 წლის 3 იანვარს დანებდა. კუნძული ლოზანის ხელშეკრულებით (1923 წლის 24 ივლისი) საბერძნეთს დარჩა.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["დიდი ვეზირ მაჰმუდ შევქეთ-ფაშას მკვლელობა ატენტატით სტამბოლში", "68e60e63"], "d": ["ბაბიალიზე თავდასხმის შემდეგ დიდ ვეზირად დანიშნული მაჰმუდ შევქეთ-ფაშა სამხედრო სამინისტროში მიმავალი, ჩარშიქაფის მახლობლად, ეტლზე გახსნილი ცეცხლით მოკლეს. „ერთობამ და პროგრესმა“ ატენტატი ოპოზიციას დააბრალა და ფართო დაპატიმრებებისა და სიკვდილით დასჯის ტალღა დაიწყო; „თავისუფლებისა და შეთანხმების“ პარტია ფაქტობრივად მოსპეს. ამ მოვლენით საბოლოოდ დამყარდა იტიჰადისტების ენვერ-თალაათ-ჯემალის ტრიუმვირატზე დაფუძნებული ერთპარტიული დიქტატურა.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["მეორე ბალკანეთის ომის დაწყება: მოკავშირეთა გაყოფის ჩხუბი", "48d088a2"], "d": ["ლონდონის ზავით ოსმალებისგან აღებული მიწების გაყოფაში ვერშეთანხმებული ბალკანეთის მოკავშირეები ერთმანეთს დაერივნენ; ბულგარეთის მიერ სერბულ და ბერძნულ პოზიციებზე თავდასხმით დაიწყო მეორე ომი. როცა რუმინეთმა და მონტენეგრომაც ბულგარეთის წინააღმდეგ ფრონტზე შევიდნენ, ბულგარული ჯარი ჩამოიშალა. ოსმალეთის სახელმწიფომ ეს შესაძლებლობა გამოიყენა, ლონდონის ზავით გავლებული მიდია-ენოსის ხაზი გადალახა და აღმოსავლეთ თრაკია ედირნესთან ერთად დაიბრუნა.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["სტამბოლის ზავი: ზავი ბულგარეთთან და ედირნეს დადასტურება", "c8c18b2d"], "d": ["მეორე ბალკანეთის ომის შემდეგ ოსმალეთის სახელმწიფოსა და ბულგარეთს შორის ხელმოწერილმა ზავმა საზღვრად მდინარე მარიცა (მერიჩი) აღიარა და სამართლებრივად დაადასტურა ედირნეს, ქირქლარელის, დიმეტოკისა და აღმოსავლეთ თრაკიის ოსმალთა ხელში დარჩენა. დედეაღაჩი ბულგარეთს დარჩა (კავალა კი 1912 წლის შემოდგომის ბულგარული ოკუპაციის შემდეგ 1913 წლის ივლისში საბერძნეთზე გადასული იყო და 1913 წლის 10 აგვისტოს ბუქარესტის ზავით საბერძნეთის შემადგენლობაში დადასტურდა), ორ ქვეყანას შორის მოსახლეობის ურთიერთგაცვლა და ბულგარეთში მყოფი მუსლიმების უფლებები მოწესრიგდა. ეს ტექსტი ბალკანეთის კატასტროფიდან დაბრუნებული ერთადერთი ტერიტორიის გარანტიაა. იმავე თარიღს შემოერთებული სხვა ადგილები: გიუმიულჯინე.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["ბოზჯაადისა და იმბროსის დაბრუნება — ათენის ზავი", "ec084d09"], "d": ["ბალკანეთის ომში საბერძნეთის მიერ ოკუპირებული ჩრდილოეთ ეგეოსის კუნძულებიდან სრუტის შესასვლელის მაკონტროლებელი ბოზჯაადა და იმბროსი ათენის ზავის მოლაპარაკებებზე დარდანელის თავდაცვისთვის შეუცვლელად ჩაითვალა და ოსმალებს დაუბრუნდა. დანარჩენი კუნძულები საბერძნეთს დარჩა. ეს ორი კუნძული ეგეოსში იმპერიის ხელში დარჩენილი უკანასკნელი მიწა გახდა და ლოზანაშიც თურქეთს დაეტოვა.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["ათენის ზავი: ზავი საბერძნეთთან და სალონიკისა და იანინის გადაცემა", "8e94def7"], "d": ["ოსმალეთის სახელმწიფოსა და საბერძნეთს შორის ხელმოწერილმა ზავმა ოფიციალურად აღიარა ბალკანეთის ომში დაკარგული სალონიკის, იანინისა და სამხრეთ მაკედონიის საბერძნეთზე გადასვლა და კრეტაზე ოსმალთა უფლებებზე უარი ითქვა. საბერძნეთში დარჩენილი მუსლიმების რელიგიური და საკუთრების უფლებები, ვაყფების სტატუსი და მუფთების დანიშვნა დეტალურად მოწესრიგდა. ეგეოსის კუნძულების სტატუსი კი გადაუწყვეტელი დარჩა და ორ სახელმწიფოს შორის მუდმივი დაძაბულობის წყაროდ დარჩა.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["ოსმალურ-გერმანული ფარული სამოკავშირეო ხელშეკრულების ხელმოწერა სტამბოლში", "0472efb3"], "d": ["ევროპაში ომის აფეთქებისთანავე დიდი ვეზირ საიდ ჰალიმ-ფაშას სასახლეში ოსმალეთის სახელმწიფოსა და გერმანიას შორის ფარული სამოკავშირეო ხელშეკრულება დაიდო; ტექსტი ითვალისწინებდა, რომ რუსეთის გერმანიის წინააღმდეგ ომში ჩართვის შემთხვევაში ოსმალეთიც გერმანიის მხარეს დადგებოდა. ხელშეკრულება კაბინეტსაც კი დაუმალეს, მხოლოდ ოთხი ადამიანი იცოდა მის შესახებ. სამი თვის შემდეგ შავი ზღვის თავდასხმით ოსმალეთის სახელმწიფო ფაქტობრივად ომში ჩაითრიეს და იმპერიის ბედი ამ დოკუმენტს დაუკავშირდა.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["კაპიტულაციების ცალმხრივად გაუქმება", "ec773d18"], "d": ["ევროპის ომით დაკავების მომენტში ოსმალეთის მთავრობამ გამოაცხადა, რომ უცხოელებისთვის სასამართლო, ფინანსური და საბაჟო პრივილეგიების მიმნიჭებელ კაპიტულაციებს 1914 წლის 1 ოქტომბრიდან ცალმხრივად აუქმებდა. ამ ოთხსაუკუნოვანი პრივილეგიების წესრიგის დასრულებას ქვეყნის შიგნით დამოუკიდებლობის დიდი აღფრთოვანებით შეხვდნენ და სტამბოლში ზეიმები გაიმართა. მოკავშირე გერმანიის ჩათვლით ყველა სახელმწიფომ გადაწყვეტილება გააპროტესტა; კაპიტულაციები საბოლოოდ ისტორიას მხოლოდ 1923 წელს, ლოზანაში, ჩაბარდებოდა.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["შავი ზღვის თავდასხმა: ოსმალური ფლოტის მიერ რუსული ნავსადგურების დაბომბვა", "8ad4ef61"], "d": ["გერმანიიდან გაქცეული და ოსმალურ ფლოტს თითქოს „შესყიდული“ სახით შეერთებული „გებენი“ და „ბრესლაუ“ (იავუზი და მიდილი), ადმირალ სუშონის სარდლობით, შავ ზღვაში გავიდნენ, რუსული ნავსადგურები დაბომბეს და ხომალდები ჩაძირეს. ენვერ-ფაშას მიერ კაბინეტისგან ფარულად გაცემულმა ამ ბრძანებამ ნეიტრალიტეტი ფაქტობრივად დაასრულა. ერთ კვირაში რუსეთმა, ინგლისმა და საფრანგეთმა ომი გამოაცხადეს და ოსმალეთის სახელმწიფო შეუქცევადად შევიდა პირველ მსოფლიო ომში.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["ინგლისურ-ინდური ძალების მიერ ფაოს აღება — ერაყის ფრონტის გახსნა", "08663813"], "d": ["ანტანტის სახელმწიფოების მიერ ოსმალეთის სახელმწიფოსთვის ომის გამოცხადების მეორე დილას ბაჰრეინში მომლოდინე ინგლისურ-ინდური ბრიგადა შატ ალ-არაბის შესართავთან ფაოში გადმოსხდა. ნანგრევებად ქცეული ფაოს ციხეში მყოფი პატარა ოსმალური ნაწილი საბრძოლო ხომალდების ცეცხლის ქვეშ უკან დაიხია და ინდოეთის ტელეგრაფის ხაზის სადგური ინგლისელების ხელში გადავიდა. ამგვარად გაიხსნა ერაყის ფრონტი.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["დიდი ჯიჰადის (Cihâd-ı Ekber) გამოცხადება: ჯიჰადის ფეთვის წაკითხვა ფათიჰის მეჩეთში", "2a6174e8"], "d": ["შეიხულისლამ ურგუფლუ ჰაირი ეფენდის მიერ გაცემული ხუთი ფეთვა ხალიფა-ფადიშაჰის სახელით ფათიჰის მეჩეთში წაიკითხეს და ყველა მუსლიმი ანტანტის სახელმწიფოების წინააღმდეგ ჯიჰადისკენ მოუწოდეს. ამ ნაბიჯს, რომელზეც გერმანია დიდ იმედს ამყარებდა, მიზნად ჰქონდა ინგლისურ და ფრანგულ კოლონიებში მუსლიმების აჯანყება. მოსალოდნელი საყოველთაო აჯანყება არ მოხდა; პირიქით, ორი წლის შემდეგ მექის ამირ შარიფ ჰუსეინის ინგლისის მხარდაჭერით აჯანყებამ მწარედ აჩვენა ხალიფატის პოლიტიკური გავლენის საზღვრები.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["ყურნას ინგლისელებზე დანებება", "621d36b0"], "d": ["ბასრის დაცემის შემდეგ ტიგროსისა და ევფრატის შეერთების ადგილას, ყურნაში, უკანდახეული ბასრის ვალი სუბჰი ბეის ძალები 4-8 დეკემბრის შეტაკებების შემდეგ 1914 წლის 9 დეკემბრის დილას დანებდნენ.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["სარიყამიშის ოპერაცია: კატასტროფა კავკასიის ფრონტზე", "5cbde7f0"], "d": ["ენვერ-ფაშამ 1878 წელს დაკარგული ყარს-არდაჰან-ბათუმის დასაბრუნებლად და კავკასიაში თურქების ასაჯანყებლად III არმია ზამთარში ალაჰუექბერის მთების გავლით რუსული ძალების ალყაში მოსაქცევ მანევრზე გაუშვა. არასაკმარისი ზამთრის აღჭურვილობის, ამოწურული მომარაგებისა და მინუს ოცდაათ გრადუსამდე მისული ქარბუქის გამო ჯარი ბრძოლაში ჩართვამდე დადნა; ათიათასობით ჯარისკაცი გაყინვით დაიღუპა. ოპერაცია ომში ოსმალეთის ერთ-ერთი უმძიმესი კატასტროფა გახდა და აღმოსავლეთის ფრონტი ორი წელი დაუცველი დატოვა.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["არხის პირველი ოპერაცია: შეტევა სუეცზე სინას უდაბნოს გავლით", "02dd72f5"], "d": ["IV არმიის სარდალმა ჯემალ-ფაშამ, ეგვიპტის ინგლისური ოკუპაციისგან გასათავისუფლებლად და სუეცის არხის ნაოსნობისთვის ჩასაკეტად, სინას უდაბნოს გადამლახველი შეტევა მოაწყო. მიუხედავად იმისა, რომ ოსმალურმა ნაწილებმა არხის აღმოსავლეთ ნაპირს მიაღწიეს და ნაწილმა მეორე მხარეს გადასვლაც შეძლო, ინგლისური უპირატესობისა და მოსალოდნელი ეგვიპტელთა სახალხო აჯანყების არმოხდენის გამო უკან დაიხიეს. ოპერაციამ მიზანს ვერ მიაღწია, მაგრამ ინგლისი ეგვიპტეში დიდი ძალის შენარჩუნებაზე აიძულა და არაპირდაპირი სტრატეგიული ეფექტი შექმნა.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["გადაყვანისა და დასახლების (თეჰჯირის) კანონის გამოცემა", "2f2bc22c"], "d": ["ვანის აჯანყებისა და რუსთა წინსვლის შემდეგ მთავრობამ გამოსცა დროებითი კანონი, რომელიც ზურგში უსაფრთხოების დამრღვევად შეფასებული მოსახლეობის ჯარის სარდლების მიერ სხვა მხარეებში გადაყვანის ნებას იძლეოდა; ფადიშაჰმა ის 1915 წლის 27 მაისს დაამტკიცა. მისი განხორციელების შედეგად ანატოლიის აღმოსავლეთი და სამხრეთი ვილაიეთების სომხური მოსახლეობის დიდი ნაწილი სირიისა და მოსულის მიმართულებით გადაასახლეს; გადაყვანისას ავადმყოფობის, შიმშილისა და თავდასხმების გამო ადამიანთა ძალზე დიდი მსხვერპლი მოხდა. გადაწყვეტილება ოსმალეთის უკანასკნელი წლების უმძიმეს და დღესაც ყველაზე სადავო საკითხად რჩება.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["ოსმალურმა ნაწილებმა მუში რუსული ოკუპაციისგან დაიბრუნეს", "fb1be113"], "d": ["მუშის პირველი რუსული ოკუპაციიდან ექვსი თვის შემდეგ ოსმალეთის მე-16 კორპუსი ბითლის-მუშის კონტრშეტევისას დაბაში შევიდა.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["მუში ხელახლა რუსთა ხელში გადავიდა", "43ad8a03"], "d": ["რუსული კონტრშეტევის გამო ოსმალურმა რაზმმა მუში დაცალა; დაბა 1916 წლის 22-25 აგვისტოს შორის ხელახლა რუსულმა ჯარმა დაიკავა და 1917 წლის გაზაფხულამდე მის ხელში დარჩა.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["მუში საბოლოოდ გათავისუფლდა რუსული ოკუპაციისგან", "f0e89703"], "d": ["პირველ მსოფლიო ომში რუსული ოკუპაციის ქვეშ მოქცეული მუში 1917 წლის 1 მაისს ოსმალურმა ძალებმა საბოლოოდ დაიბრუნეს.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["აბდულჰამიდ II-ის გარდაცვალება ბეილერბეის სასახლეში", "c9662582"], "d": ["გარდაიცვალა აბდულჰამიდ II, რომელიც 1909 წელს ტახტიდან ჩამოაგდეს და ჯერ სალონიკში გაგზავნეს, ბალკანეთის ომში ქალაქის დაკარგვის შემდეგ კი სტამბოლში ჩამოიყვანეს და ბეილერბეის სასახლეში მეთვალყურეობის ქვეშ ჰყავდათ. ოცდაცამეტწლიანი მმართველობის განმავლობაში იგი ცდილობდა სახელმწიფო ომებისგან შორს შეენარჩუნებინა და დრო მოეგო, მაგრამ ტირანიული მმართველობითაც იხსენიებოდა. მისი ცხედარი დიდი ხალხმრავლობით დივანიოლუს მაჰმუდ I-ის აკლდამაში დაკრძალეს; მისი სიკვდილი ომის იმ წელს დაემთხვა, როცა მის მიერ დამყარებული წესრიგი უკვე დიდი ხნის მოსპობილი იყო.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["ბრესტ-ლიტოვსკის ზავი: ყარსის, არდაჰანისა და ბათუმის დაბრუნება", "da82636f"], "d": ["ბოლშევიკური გადატრიალების შემდეგ ომიდან გამოსულ რუსეთსა და ცენტრალურ სახელმწიფოებს შორის ხელმოწერილმა ზავმა აღმოსავლეთის ფრონტი დახურა და ოსმალეთის სახელმწიფოს 1878 წლის ბერლინის ტრაქტატით დაკარგული ყარსი, არდაჰანი და ბათუმი (სამი სანჯაყი — Elviye-i Selâse) დაუბრუნა. ეს ოსმალეთის ისტორიაში ორმოცი წლის შემდეგ მოპოვებული ერთადერთი ტერიტორიული შენაძენი იყო. თუმცა მუდროსის ზავის შემდეგ მხარე კვლავ ხელიდან გავიდა; საბოლოო გადაწყვეტა 1921 წლის ყარსის ხელშეკრულებით მოვიდა.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["ოსმალური ნაწილები ართვინში შევიდნენ", "ca7d1778"], "d": ["25 მარტს 1914 წლის საზღვრის გადამლახველმა ოსმალურმა ნაწილებმა ბრესტ-ლიტოვსკის მიერ 1878 წლამდელი საზღვრის დამბრუნებელი სამი სანჯაყისკენ გაილაშქრეს და 1918 წლის 28 მარტს ართვინში შევიდნენ. ართვინი, ბათუმის სანჯაყის ნაწილი, 1878 წელს რუსეთს დაეთმო; TDV-ის ართვინის სტატია დაბრუნებას მხოლოდ „1918 წლის მარტად“ წერს, დღეს კი მუსტაფა სარი ასახელებს.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["არტაანი თურქულმა ჯარმა დაიკავა", "7fd9e3db"], "d": ["ელვიეი სელასეს ოპერაციისას ოსმალეთის ჯარმა ართვინის შემდეგ 1918 წლის 3 აპრილს არტაანი აიღო; არტაანი 93-ის ომში, 1877 წელს დაეცა და 1878 წელს რუსეთს გადაეცა. ყარსი ერთი თვის შემდეგ, 25 აპრილს უნდა აეღოთ.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["ბათუმის დაბრუნება", "d37a1a0d"], "d": ["ბრესტ-ლიტოვსკის ზავით რუსეთის ომიდან გასვლის შემდეგ აღმოსავლეთისკენ მიმავალმა ოსმალურმა ჯარმა 1878 წელს დაკარგული ბათუმის ნავსადგური ორმოცი წლის შემდეგ დაიბრუნა. შავი ზღვის აღმოსავლეთ კიდეზე მდებარე ეს ნავსადგური ბაქოს ნავთობის საზღვაო გასასვლელი იყო. შენაძენი მხოლოდ შვიდი თვე გაგრძელდა; მუდროსის ზავის შემდეგ მხარეს დაცლიდნენ.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["სამი სანჯაყი (Elviye-i Selâse): ყარსი ოსმალთა მმართველობაში შევიდა", "02cbf0b3"], "d": ["ბრესტ-ლიტოვსკში 1878 წლის ბერლინის ტრაქტატით დაკარგული სამი სანჯაყის — ყარსის, არდაჰანისა და ბათუმის — დაბრუნება იყო გადაწყვეტილი; ოსმალური ჯარი 1918 წლის 3 აპრილს არდაჰანში, 14 აპრილს ბათუმში, 25 აპრილს კი ყარსში შევიდა და მმართველობა ფაქტობრივად დამყარდა. „სამი სანჯაყის“ (Elviye-i Selâse) სახელით ცნობილი ეს მიწები 93 წლის ომიდან გაგრძელებული დანაკარგის ანაზღაურებად ჩაითვალა. დროებითი ზავის შემდეგ კვლავ ხელიდან გავიდოდნენ და საბოლოოდ თურქეთს მხოლოდ 1921 წლის ყარსის ხელშეკრულებით შეუერთდებოდნენ.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["იგდირი დაიპყრეს — წინსვლა არაქსის ხეობაში", "87ebf4d3"], "d": ["1918 წლის თებერვალში დაწყებული წინსვლითი ოპერაციის ფარგლებში თურქულმა ნაწილებმა არაქსის ჩრდილოეთით, სარდარაბადთან, სომხური ნაწილები დაამარცხეს და 1918 წლის 20 მაისს იგდირი დაიპყრეს. იგდირი ელვიეი სელასეში არ შედიოდა; ის ერევნის გუბერნიის სურმალუს კაზა იყო; რეგიონში დაახლოებით 180 წლის შემდეგ პირველად დამყარდა ოსმალური მმართველობა.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["მეჰმედ V რეშადის გარდაცვალება და მეჰმედ VI ვაჰდედინის ტახტზე ასვლა", "d302ba07"], "d": ["ცხრაწლიანი მმართველობა, რომელმაც ტრიპოლის, ბალკანეთისა და მსოფლიო ომებში გაიარა, მეჰმედ V რეშადმა ომის ყველაზე კრიტიკულ პერიოდში დაასრულა გარდაცვალებით, და მის ადგილზე ძმა ვაჰდედინი მეჰმედ VI-ის სახელით ავიდა ტახტზე. ახალი ფადიშაჰი ცდილობდა იტიჰადისტური კადრის მეურვეობისგან გათავისუფლებას; ოთხი თვის შემდეგ, დროებითი ზავის ხელმოწერისას, იმპერიის ლიკვიდაციის მართვა მოუწევდა. იგი ოსმალური დინასტიის ოცდამეთექვსმეტე და უკანასკნელი ფადიშაჰი იყო.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["ანტანტის ფლოტის სტამბოლის მისადგომებთან მისვლა და ქალაქის ფაქტობრივი ოკუპაცია", "d10cb14d"], "d": ["მუდროსის ზავის შემდეგ ინგლისური, ფრანგული, იტალიური და ბერძნული ხომალდებისგან შემდგარმა სამოც ერთეულზე მეტმა მოკავშირეთა ფლოტმა დოლმაბაჰჩეს წინ ღუზა ჩაუშვა და სტამბოლი ფაქტობრივად ოკუპაციაში მოექცა. ოთხას სამოცდახუთი წლის შემდეგ დედაქალაქი პირველად გადავიდა უცხოელი ჯარისკაცების კონტროლქვეშ. იმავე დღეს ჰაიდარფაშაში ჩამოსული მუსტაფა ქემალ-ფაშას მიერ ამ სანახაობის ნახვისას, გადმოცემის თანახმად, ნათქვამი სიტყვები „როგორც მოვიდნენ, ისე წავლენ“ ეროვნული ბრძოლის სიმბოლურ ფრაზად იქცეოდა.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["უკანდახევა არაქსის რეგიონში: იგდირი დაცალეს", "57572ab4"], "d": ["მუდროსის დროებითი ზავის იმ დებულების შესაბამისად, რომელიც 1914 წლის საზღვრის უკან გასვლას ითვალისწინებდა, იაქუბ შევქი-ფაშამ 21 ნოემბრის ბრძანებით დაავალა ბრესტ-ლიტოვსკის საზღვრის გარეთ მყოფი ნაწილების 4 დეკემბრამდე გამოყვანა; იგდირი და მისი შემოგარენი ამ თარიღისთვის სრულად დაიცალა. შემდეგ არაქს-თურქული მთავრობა 1918 წლის დეკემბრის ბოლოს სომხებმა დაამხეს.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["ინგლისელები ართვინში დამკვიდრდნენ", "e2cb3153"], "d": ["რადგან 1918 წლის 30 ოქტომბრის მუდროსის დროებითი ზავი ოსმალეთის ჯარის 1914 წლის საზღვრის უკან გასვლას მოითხოვდა, ართვინი დაიცალა და 1918 წლის 17 დეკემბერს ინგლისელებმა დაიკავეს. TDV-ის სტატიის „ართვინი“ თანახმად, ინგლისური ოკუპაცია 1920 წლის აპრილამდე გაგრძელდა.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["ბრიტანული მმართველობა ბათუმში მუდროსის შემდეგ", "9dd768fc"], "d": ["1918 წლის 30 ოქტომბრის მუდროსის დროებითი ზავის თანახმად, ოსმალეთის სახელმწიფო იძულებული გახდა ბათუმიდან გასულიყო; ქალაქი 1918 წლის 24 დეკემბერს ბრიტანულმა ნაწილებმა დაიკავეს. 1918 წლის აპრილში დამოუკიდებელი სანჯაყის ცენტრად ქცეული ბათუმი ამ დროიდან 1920 წლის ივლისამდე ინგლისის კონტროლის ქვეშ დარჩა.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["არტაანი ქართული მმართველობის ქვეშ გადავიდა", "97cf47f6"], "d": ["მუდროსის შემდეგ დაცლილი არტაანი 1919 წლის 20 აპრილს ქართულმა ძალებმა დაიკავეს, იმ დღეებში, როცა ინგლისელები სამხრეთ-დასავლეთ კავკასიის მთავრობას შლიდნენ. ქართული მმართველობა 1921 წლის 23 თებერვლამდე უნდა გაგრძელებულიყო.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["პრესტონმა ყარსის მმართველობა სომეხ გუბერნატორს გადასცა", "efa81cb0"], "d": ["ინგლისელმა მეთაურმა პრესტონმა, რომელმაც 1919 წლის 12-13 აპრილს სამხრეთ-დასავლეთ კავკასიის მთავრობა დაშალა, 1919 წლის 30 აპრილს გააუქმა დროებითი საბჭოს მთავრობა და ქალაქის მმართველობა ყარსის გუბერნატორად დანიშნულ სომეხ კარგანოვს გადასცა; ყარსში სომხური მმართველობის ხანა დაიწყო და ქაზიმ ყარაბექირის 1920 წლის 30 ოქტომბრის გამარჯვებამდე გაგრძელდა.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["ერზურუმის კონგრესი: აღმოსავლეთი ვილაიეთების ეროვნული წინააღმდეგობის გადაწყვეტილება", "41ef0457"], "d": ["აღმოსავლეთი ანატოლიის უფლებების დაცვის საზოგადოების მიერ მოწვეული კონგრესი, ინგლისური ზეწოლით გადადების შემდეგ, ორმოცდათექვსმეტი დელეგატით გაიხსნა და მის თავმჯდომარედ სამხედრო სამსახურიდან გადამდგარი მუსტაფა ქემალ-ფაშა აირჩიეს. კონგრესმა გამოაცხადა, რომ ეროვნულ საზღვრებში სამშობლო ერთიანი მთლიანობაა, რომ მანდატისა და მფარველობის მიღება შეუძლებელია, ხოლო მთავრობის დაშლის შემთხვევაში ერი საკუთარ ბედს თავად აიღებს ხელში. ეს გადაწყვეტილებები ექვსი თვის შემდეგ ეროვნული აღთქმის (Misâk-ı Millî) ტექსტის ბირთვს შექმნიდა.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["სივასის კონგრესი: ეროვნული წინააღმდეგობის ერთ ჭერქვეშ გაერთიანება", "0e9ad36b"], "d": ["1919 წლის 4 სექტემბერს სივასის ლიცეუმში (სულთანიში) მუშაობის დამწყებმა კონგრესმა ქვეყნის ყველა კუთხის უფლებების დაცვის საზოგადოებები ანატოლიისა და რუმელიის უფლებების დაცვის საზოგადოების სახელით გააერთიანა და წარმომადგენლობითი კომიტეტი აირჩია. ამერიკული მანდატის წინადადება ხანგრძლივი დისკუსიების შემდეგ უარყვეს. 11 სექტემბერს გამოქვეყნებული განცხადებით ეროვნული ბრძოლა ერთცენტრიან, ლეგიტიმურ პოლიტიკურ მოძრაობად იქცა და სტამბოლის მთავრობასთან ღია ძალთა ბრძოლა დაიწყო.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["ამასიის ოქმი: სტამბოლის მთავრობასა და წარმომადგენლობითი კომიტეტის მოლაპარაკება", "40e6a6ab"], "d": ["დამად ფერიდის დაცემისა და ალი რიზა-ფაშას მთავრობის შექმნის შემდეგ საზღვაო მინისტრი სალიჰ-ფაშა წარმომადგენლობით კომიტეტთან სასაუბროდ ამასიაში გაგზავნეს. მიღწეული ოქმებით სტამბოლის მთავრობამ ანატოლიის მოძრაობის არსებობა ფაქტობრივად აღიარა; დათანხმდნენ დეპუტატთა პალატის შეკრებაზე, არჩევნების თავისუფლად ჩატარებასა და ეროვნული საზღვრების დაცვაზე. ეს ეროვნული ბრძოლის მიერ სტამბოლის წინაშე მოპოვებული პირველი ოფიციალური პოლიტიკური მონაპოვარია.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["ეროვნული აღთქმის (Misâk-ı Millî) მიღება უკანასკნელ ოსმალურ პარლამენტში", "6322865e"], "d": ["უკანასკნელ ოსმალურ დეპუტატთა პალატაში 121 დეპუტატის მიერ ხელმოწერილი ეროვნული აღთქმის ტექსტი პირობად აყენებდა მუდროსის ხაზის შიგნით დარჩენილი და მუსლიმ-თურქული უმრავლესობით დასახლებული მიწების განუყოფელ მთლიანობას, არაბულ ვილაიეთებსა და დასავლეთ თრაკიაში სახალხო კენჭისყრას, კაპიტულაციების გაუქმებასა და სრულ პოლიტიკურ-ფინანსურ დამოუკიდებლობას. ტექსტი 1920 წლის 17 თებერვალს ერთხმად მიიღეს და მსოფლიოს გამოუცხადეს. ეს დეკლარაცია როგორც ეროვნული ბრძოლის პოლიტიკური პროგრამა, ისე ლოზანაში დასაცავი საზღვრების რუკა იყო; ის 16 მარტს ანტანტის სახელმწიფოების მიერ სტამბოლის ოფიციალური ოკუპაციის პირდაპირი მიზეზი გახდა.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["ინგლისელების გასვლისას ართვინი საქართველოს დარჩა", "6d086b06"], "d": ["TDV-ის სტატიის „ართვინი“ თანახმად, ინგლისური ოკუპაცია 1920 წლის აპრილამდე გაგრძელდა; ინგლისელებმა გასვლისას ქალაქი საქართველოს დაუტოვეს. ართვინი საქართველოს ხელში თურქეთის დიდი ეროვნული კრების 1921 წლის 23 თებერვლის ულტიმატუმამდე დარჩა.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["ბათუმი ქართულ ადმინისტრაციას გადაეცა", "6523d095"], "d": ["ინგლისელების მიერ ბათუმის ქართველებისთვის ოფიციალური გადაცემა 1920 წლის 7 ივლისს მოხდა (TDV-ის სტატია „ბათუმი“ მხოლოდ „1920 წლის ივლისს“ ასახელებს). ანკარის მთავრობამ 25 ივლისს ეს გადაცემა „ოკუპაციად“ შეაფასა და გააპროტესტა.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["გიუმრის ზავი: თურქეთის დიდი ეროვნული კრების მთავრობის პირველი საერთაშორისო ხელშეკრულება", "9232c690"], "d": ["ქაზიმ ყარაბექირის სარდლობით აღმოსავლეთი ფრონტის ჯარის მიერ სარიყამიშისა და ყარსის დაბრუნების შემდეგ სომხეთმა ზავი ითხოვა და გიუმრიში ხელმოწერილი ხელშეკრულებით მიიღო, რომ სევრს არ აღიარებდა და აღმოსავლეთში ტერიტორიულ მოთხოვნებზე უარს ამბობდა. ანკარის მთავრობის მიერ ხელმოწერილი ეს პირველი ხელშეკრულება სევრის ფაქტობრივად უარმყოფელი პირველი საერთაშორისო დოკუმენტი გახდა და დიდ ეროვნულ კრებას სამართლებრივი აღიარების გზა გაუხსნა. ამგვარად, აღმოსავლეთის საზღვარი უზრუნველყოფილი გახდა და დასავლეთ ფრონტზე ძალების გადატანა შესაძლებელი გახდა.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["ინონიუს პირველი ბრძოლა: რეგულარული ჯარის პირველი გამარჯვება", "4add3719"], "d": ["ახლად შექმნილმა რეგულარულმა ჯარმა ბურსის მიმართულებიდან წინ მიმავალი ბერძნული ძალები ინონიუს პოზიციებთან შეაჩერა და უკან დახევაზე აიძულა. სამხედრო თვალსაზრისით შეზღუდული მასშტაბის ამ წარმატებას თავისი პოლიტიკური შედეგებით ძალზე დიდი მნიშვნელობა ჰქონდა: ანკარის მთავრობა ლონდონის კონფერენციაზე მიიწვიეს, საბჭოთა რუსეთთან მოსკოვის ხელშეკრულების გზა გაიხსნა და ძირითადი ორგანიზაციის კანონი (Teşkilât-ı Esâsiyye) მიიღეს. შიდა საზოგადოებრივ აზრში რეგულარული ჯარისადმი ნდობაც ამ გამარჯვებით განმტკიცდა.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["ინონიუს მეორე ბრძოლა: ბერძნული შეტევის მეორედ გატეხვა", "a974521c"], "d": ["ლონდონის კონფერენციიდან შედეგის ვერმიმღები ბერძნული ჯარი ბურსისა და უშაქის მიმართულებიდან ახალ შეტევაზე გადავიდა, მაგრამ კვლავ ინონიუს სერებზე შეაჩერეს და იძულებული გახდა უკან დაეხია. მუსტაფა ქემალ-ფაშას მიერ ისმეთ-ფაშასთვის გაგზავნილი დეპეშა „თქვენ იქ მხოლოდ მტერი კი არა, ერის უკუღმართი ბედიც დაამარცხეთ“ ამ გამარჯვების შემდეგ დაიწერა. ბრძოლამ ეროვნული ბრძოლის საერთაშორისო ავტორიტეტი აამაღლა და იტალიის ანატოლიიდან გასვლის პროცესი დააჩქარა.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["ანკარის შეთანხმება: ზავი საფრანგეთთან და სამხრეთ ფრონტის დახურვა", "35fc32db"], "d": ["საქარიას გამარჯვების შემდეგ საფრანგეთთან ანკარაში ხელმოწერილი შეთანხმებით სამხრეთ ფრონტზე ომი დასრულდა; ფრანგულმა ძალებმა ადანას, ანთეფის, მარაშისა და ურფის ჩათვლით ჩუქუროვა და სამხრეთ-აღმოსავლეთი დაცალეს და სირიის საზღვრამდე უკან დაიხიეს. ამგვარად, ანტანტის ერთ-ერთმა სახელმწიფომ ანკარის მთავრობა ფაქტობრივად აღიარა და სევრის ფრონტზე პირველი ბზარი გაჩნდა. დაცლილი მხარეებიდან გადაბარებულმა იარაღმა და გათავისუფლებულმა ნაწილებმა დიდი შეტევის მომზადებაში გადამწყვეტი როლი ითამაშა.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["მუდანიას დროებითი ზავი: სტამბოლისა და სრუტეების უბრძოლველი გადაცემა", "ac0d9baf"], "d": ["დიდი შეტევის შემდეგ ჩანაქალესა და იზმითში თურქული ჯარის ინგლისურ ძალებთან პირისპირ დადგომის გამო მუდანიაში შეკრებილი კონფერენცია თერთმეტდღიანი მძიმე ვაჭრობის შემდეგ დროებითი ზავით დასრულდა. აღიარეს, რომ აღმოსავლეთ თრაკია მარიცამდე თხუთმეტ დღეში საბერძნეთი დაცლიდა და თურქულ მმართველობას გადასცემდა, ხოლო სტამბოლი და სრუტეები სამშვიდობო ხელშეკრულებით ჩაბარდებოდა. ამგვარად, ეროვნული ბრძოლის შეიარაღებული ეტაპი ერთი ტყვიის გასროლის გარეშე მოპოვებული დიპლომატიური გამარჯვებით დასრულდა და ლოზანის კარი გაიღო.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["მეჰმედ VI ვაჰდედინის გამგზავრება სტამბოლიდან და აბდულმეჯიდ ეფენდის ხალიფად არჩევა", "8ab0e847"], "d": ["სულთანობის გაუქმების შემდეგ სადავო მდგომარეობაში აღმოჩენილმა უკანასკნელმა ფადიშაჰმა მეჰმედ VI ვაჰდედინმა 1922 წლის 17 ნოემბერს, პარასკევ დილას, ინგლისური ჯავშნოსანი „მალაიათი“ სტამბოლი დატოვა და მალტაზე გაემგზავრა. დიდმა ეროვნულმა კრებამ ორი დღის შემდეგ, 19 ნოემბერს, აბდულმეჯიდ ეფენდი პოლიტიკური უფლებამოსილების არმქონე ხალიფად აირჩია. ექვსას ოცდასამწლიანი ოსმალური დინასტიის მმართველობა ამგვარად ფაქტობრივად დასრულდა; ხალიფატი კი კიდევ თხუთმეტი თვე სიმბოლურად გაგრძელდებოდა. მალტასა და შემდეგ იტალიაში გადასული ვაჰდედინი სან-რემოს „ვილა ნობელში“ დასახლდა; მუსლიმ ქვეყანაში მიღების თხოვნებმა შედეგი არ გამოიღო და 1926 წლის 16 მაისს იქ გარდაიცვალა, კვლავ აცხადებდა, რომ სულთანობისა და ხალიფატის უფლებებზე არასოდეს უარს არ ამბობდა.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["უკანასკნელი ფადიშაჰის, მეჰმედ VI ვაჰდედინის გარდაცვალება სან-რემოში", "7149ed0e"], "d": ["სტამბოლიდან წასვლის შემდეგ იტალიის ქალაქ სან-რემოში დასახლებული ოსმალეთის უკანასკნელი ფადიშაჰი მეჰმედ ვაჰდედინი 1926 წლის 16 მაისს გარდაიცვალა ისე, რომ არ მიუღია ცნობა სახალიფოს კონგრესის (1926 წლის 13 მაისი) შეკრების შესახებ, რომლისთვისაც განაცხადა, რომ სასულთნო და სახალიფო უფლებებზე უარი არასოდეს უთქვამს. ის მძიმე ფულად გაჭირვებაში იყო; სან-რემოელი ვაჭრების 60 000 ლირა ემართა, და მისი გარდაცვალების გაგებისთანავე კრედიტორებმა მისი სახლის ნივთებს ყადაღა დაადებინეს.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["ქონურალფის მიერ ბოლუს მხარის დაპყრობა — მუდურნუ, ქონურაფა და ბოლუ", "e245cd27"], "d": ["ორჰან ღაზის ერთ-ერთი სარდალი ქონურალფი საქარიას აღმოსავლეთით მდებარე მთიანი რეგიონისკენ დაიძრა და მუდურნუს, ქონურაფასა და ბოლუს მხარე ოსმალურ მმართველობას დაუქვემდებარა; დუზჯეს ვაკეზე მდებარე დაბას მისი სახელი ეწოდა. დაპყრობის ზუსტი თარიღი უცნობია; თხრობა აშიქფაშაზადეს გადმოცემას ეყრდნობა. რეგიონი იმ დროს სასაზღვრო ზოლი იყო, რომელიც ჯანდარიდებსა და ბიზანტიას შორის გადადიოდა ხელიდან ხელში; დაპყრობამ ოსმალები პირველად მიაახლოვა შავი ზღვის დასავლეთ სანაპიროს. ანკარის ბრძოლის შემდეგ მხარე ხელახლა ჯანდარიდებს უნდა გადასცემოდა, საბოლოოდ კი მხოლოდ ფათიჰის დროს დაბრუნდებოდა.", "d7b58190"]}
});
